export const knSmv1: MeaningPack = {
  lang: 'kn',
  texts: {
    'sumadhva-vijaya-01': {
      verses: {
        '0.0': 'ಸುಂದರನೂ, ಕಲ್ಯಾಣಗುಣಗಳಿಗೆ ಏಕೈಕ ನೆಲೆಯೂ, ಉದಯಿಸುವ ಸೂರ್ಯನಂತೆ ಪ್ರಕಾಶಿಸುವವನೂ, ಸಕಲ ಜಗತ್ತಿಗೆ ಕಾರಣನೂ, ಶ್ರೀದೇವಿಗೂ ಪ್ರಾಣದೇವರಿಗೂ (ವಾಯುವಿಗೂ) ಒಡೆಯನೂ ಆದ ನಾರಾಯಣನಿಗೆ ನಮಸ್ಕರಿಸುತ್ತೇನೆ.',
        '0.1': 'ಯಾರಿಂದ ಪಾಲಿತವಾದ ಗೋಕುಲವು ಯಾವಾಗಲೂ ಕಳವಳವಿಲ್ಲದೆ ನಿರ್ಮಲ ಮನಸ್ಸಿನಿಂದ ಮೆರೆಯಿತೋ, ಆ ಕಾರ್ಮೋಡದಂತೆ ನೀಲವರ್ಣನಾದ, ಕೃಷ್ಣೆಯ (ದ್ರೌಪದಿಯ) ಪತಿಯಾದ ಭೀಮನಿಗೆ ಪ್ರಿಯನಾದ ಶ್ರೀಕೃಷ್ಣನಿಗೆ ನಮಸ್ಕಾರ.',
        '0.2': 'ಮೂರು ಲೋಕಗಳನ್ನೂ ಮೀರಿ ಬೆಳಗುವ, ಒಳಗಿನ ಅಜ್ಞಾನಾಂಧಕಾರವನ್ನು ಮತ್ತೆ ಮತ್ತೆ ಹೋಗಲಾಡಿಸುವ, ಸೂರ್ಯನ ಕಾಂತಿಯನ್ನೂ ಮೀರಿಸುವ ಶ್ರೀಮಧ್ವರ ಕೀರ್ತಿಯು ನಮಗೆ ನಿರ್ಮಲವಾದ ದೃಷ್ಟಿಯನ್ನು ಕರುಣಿಸಲಿ.',
        '0.3': 'ಯಾರ ಮುಖಚಂದ್ರನಿಂದ ಹೊರಟ ತತ್ತ್ವದೀಪಗಳಂತಿರುವ ವಾಕ್ಕುಗಳೆಂಬ ಕಿರಣಗಳಿಂದ ಲೋಕದ ಕತ್ತಲು ಕಳೆದು ಆನಂದವನ್ನು ಪಡೆಯಿತೋ, ಆ ಶ್ರೇಷ್ಠ ಗುರುಗಳಾದ ತ್ರಿವಿಕ್ರಮಾಚಾರ್ಯರಿಗೆ (ಕವಿಯ ತಂದೆಯವರಿಗೆ) ನಮಸ್ಕರಿಸುತ್ತೇನೆ.',
        '0.4': 'ಗುರುಭಕ್ತಿಯಿಂದ ಹುಟ್ಟುವ ಮುಕುಂದಭಕ್ತಿಗಾಗಿಯೂ, ಸಜ್ಜನರ ನಿರಂತರ ಪ್ರಸನ್ನತೆಗಾಗಿಯೂ ಜಗದ್ಗುರುವಾದ ವಾಯುದೇವರ ಅವತಾರಗಳ ಶ್ರೇಷ್ಠವೂ ಪರಿಶುದ್ಧವೂ ಆದ ಲೀಲೆಯನ್ನು ಹೇಳುತ್ತೇನೆ.',
        '0.5': 'ಆ ಲೀಲೆಯು ವೇದಮಂತ್ರಗಳ ಅಕ್ಷರಗಳಿಂದ ವರ್ಣಿಸಲು ಯೋಗ್ಯವಾದುದು; ರುದ್ರ, ಇಂದ್ರ ಮೊದಲಾದವರೂ ಅದನ್ನು ಹೇಳಲು ಬಯಸುತ್ತಾರೆ. ಮಂದಬುದ್ಧಿಯಾದ ನಾನು ಸಂಕ್ಷೇಪವಾಗಿ ಹೇಳಹೊರಟಿರುವಾಗ ಗುಣಶಾಲಿಗಳಾದ ಸಜ್ಜನರು ನನ್ನ ಮೇಲೆ ಕರುಣೆ ತೋರಲಿ.',
        '0.6': 'ಮೇಲುಕೀಳಾದ ಸಕಲ ಚಟುವಟಿಕೆಗಳೂ ಯಾರಿಂದ (ಪ್ರಾಣರೂಪನಾದ ವಾಯುವಿನಿಂದ) ನಡೆಯುತ್ತವೆಯೋ, ಅವನ ಚರಿತ್ರೆಯಲ್ಲಿ ಹೇಳಬೇಕಾದ ಆಶ್ಚರ್ಯವೇನು? ಆದರೂ ಕೀರ್ತಿವಂತರ ಶಿರೋಮಣಿಗಳ ಚರಿತ್ರೆಯನ್ನು ಹೇಳುವುದು ಮನಸ್ಸಿನ ಶುದ್ಧಿಗಾಗಿ.',
        '0.7': 'ಅವನ ಚರಿತ್ರೆಯೆಂಬ ರತ್ನಗಳಿಂದ ಮಾಲೆ ಕಟ್ಟುತ್ತಿರುವ, ಸೂಕ್ಷ್ಮದೃಷ್ಟಿಯಿಲ್ಲದಿದ್ದರೂ ಕುತೂಹಲವುಳ್ಳ ನನ್ನಿಂದ ಹಿಂದುಮುಂದಾಗುವ ಕ್ರಮದೋಷವಾಗಲಿ ಬೇರೆ ತಪ್ಪಾಗಲಿ ಆದರೆ ಮಹಾತ್ಮರು ಮತ್ತೆ ಮತ್ತೆ ಕ್ಷಮಿಸಲಿ.',
        '0.8': 'ಶ್ರೀಪತಿಯ ಆಜ್ಞೆಯನ್ನೂ ಇಂದ್ರಾದಿ ದೇವತೆಗಳ ಪ್ರಾರ್ಥನೆಯನ್ನೂ ಮೂರು ಲೋಕಗಳಲ್ಲಿ ಅತ್ಯಂತ ಯೋಗ್ಯವೆಂದು ಮನ್ನಿಸಿ, ಪ್ರಾಣಗಳ ಒಡೆಯನೂ ಜೀವಸಮೂಹದ ನಿಯಾಮಕನೂ ಸಜ್ಜನರ ಗುರುವೂ ಆದ ವಾಯುದೇವರು ಕೇಸರಿಯ ಮನೆಯಲ್ಲಿ ಅವತರಿಸಿದರು.',
        '0.9': 'ಲೋಕದಲ್ಲಿ ಪ್ರಸಿದ್ಧವಾದ ಯಾವ ಯಾವ ಗುಣಗಳಿವೆಯೋ ಆ ಎಲ್ಲದಕ್ಕೂ ಇವನನ್ನೇ ಉದಾಹರಣೆಯಾಗಿ ತೋರಿಸುತ್ತಾರೆ; ಮಹಾಭಾಗವತರಲ್ಲಿ ಸಾಕ್ಷಾತ್ ಶ್ರೇಷ್ಠನಾದ ಈ ಶ್ರೀಮಂತನನ್ನು ಹನುಮಂತನೆಂದು ಕರೆಯುತ್ತಾರೆ.',
        '0.10': 'ದೇವಸಭೆಗಳಲ್ಲಿ ಹೊಗಳಲ್ಪಟ್ಟ ಪರಮಾದ್ಭುತ ಕಾರ್ಯಗಳನ್ನು ಮಾಡುತ್ತಾ ಅವನು ಸುಗ್ರೀವನ ಮಿತ್ರನೂ ಜಗತ್ತನ್ನು ಪಾವನಗೊಳಿಸುವವನೂ ಆದ ರಾಮರೂಪಿ ರಮಾಪತಿಯನ್ನು ಕಂಡನು.',
        '0.11': 'ಆಗ ಮಹಾಭಕ್ತಿಯ ಭಾರದಿಂದ ಪ್ರೇರಿತನಾದ ಕಪಿಶ್ರೇಷ್ಠನು ಪಾದಾರವಿಂದಗಳಿಗೆ ನಮಸ್ಕರಿಸಲು, ಆ ಪುರಾಣಪುರುಷನು ಕಮಲದ ಒಳಭಾಗದಂತೆ ಸುಂದರವಾದ ತನ್ನ ಎರಡು ತೋಳುಗಳಿಂದ ಅವನನ್ನು ಅಪ್ಪಿಕೊಂಡನು.',
        '0.12': 'ಸೀಳಲಾಗದ ಸಾಲವೃಕ್ಷಗಳ ಸಾಲನ್ನು ಸೀಳಿದ, ಇಂದ್ರಪುತ್ರನಾದ ವಾಲಿಯನ್ನು ಕೊಂದ, ಸೂರ್ಯಪುತ್ರನಾದ ಸುಗ್ರೀವನಿಗೆ ಅತಿಶಯ ಸಂತೋಷವನ್ನಿತ್ತ ಮಧುಸೂದನನಾದ ಶ್ರೀರಾಮನು ಆ ವೀರನನ್ನು (ಸೀತಾನ್ವೇಷಣೆಗೆ) ಕಳುಹಿಸಿದನು.',
        '0.13': 'ಕಿವಿಯವರೆಗೆ ಎಳೆದು ಬಿಡುವ, ಗುಣಗ್ರಾಹಿಯಾದ (ಬಿಲ್ಲಿನ ಹೆದೆಯನ್ನು ಹಿಡಿಯುವ) ರಣಕುಶಲನಾದ ರಾಮನಿಂದ ಬಿಡಲ್ಪಟ್ಟ ಅವನು, ಶ್ರೇಷ್ಠ ಬಾಣದಂತೆ ಹೊಳೆಯುತ್ತಾ ಶತ್ರುಗಳಿಗೆ ಭಯಂಕರನೂ ಸಜ್ಜನರ ಪಕ್ಷಪಾತಿಯೂ (ಉತ್ತಮ ಗರಿಯುಳ್ಳವನೂ) ಆದನು.',
        '0.14': 'ಆಹಾ! ಈ ಹನುಮಂತನು ಹೊಸ ಮಳೆಮೋಡದಂತೆ: ತನ್ನ ಮಾತುಗಳಿಂದ (ಮೋಡವು ನೀರಿನಿಂದ) ಸೀತೆಯನ್ನು ಸಂತೋಷಪಡಿಸಿದನು, ತನ್ನ ಬೆಂಕಿಯಿಂದ ಮಾಂಸಾಹಾರಿ ರಾಕ್ಷಸರ ರಾಶಿಯನ್ನು (ಮಿಂಚು ಮರಗಳನ್ನು) ಸುಟ್ಟನು, ಸಮುದ್ರವನ್ನು ದಾಟಿ ವಿಷ್ಣುಪಾದಕ್ಕೆ (ಆಕಾಶದಲ್ಲಿ) ನಮಸ್ಕರಿಸಿದನು.',
        '0.15': 'ಮೂರು ಲೋಕಗಳಲ್ಲಿ ರೆಕ್ಕೆಯಿಲ್ಲದ (ಪಕ್ಷಪಾತವಿಲ್ಲದ), ಭೋಗಗಳನ್ನು ಅನುಭವಿಸದ (ಹಾವುಗಳನ್ನು ತಿನ್ನದ) ಈ ಪುರುಷನು ವಿಶ್ವಂಭರನಾದ ರಾಮನನ್ನು ಹೊತ್ತು ವೇಗದ ಪರಾಕ್ರಮಗಳಲ್ಲಿ ಪಕ್ಷಿರಾಜ ಗರುಡನನ್ನೇ ಗೆದ್ದನು — ಇದು ಆಶ್ಚರ್ಯ.',
        '0.16': 'ರಘುವಂಶಕೇತುವಾದ ರಾಮನು ತನ್ನ ಹುಬ್ಬುಗಂಟಿನಿಂದಲೇ ಕಳವಳಗೊಂಡ ಸಮುದ್ರದ ಮಧ್ಯೆ ಸೇತುವೆಯನ್ನು ಕಟ್ಟಿಸಿದ ಮೇಲೆ, ಹನುಮಂತನು ಸೀತೆಯನ್ನು ಬೆದರಿಸಿದ್ದಕ್ಕೆ ತಕ್ಕ ಉತ್ತರವಾಗಿ ದಶಕಂಠನಿಗೆ ಮುಷ್ಟಿಯ ಹೊಡೆತವನ್ನು ಕೊಟ್ಟನು.',
        '0.17': 'ಜಾಜ್ವಲ್ಯಮಾನನಾದ ರಾಘವನೇ ಅಗ್ನಿಯಾಗಿ, ಸುಗ್ರೀವನೇ ಯಜಮಾನನಾಗಿದ್ದ ಯುದ್ಧವೆಂಬ ಯಜ್ಞದಲ್ಲಿ, ಅವನು ಸುಮಿತ್ರಾಪುತ್ರ ಲಕ್ಷ್ಮಣನನ್ನು ಸಹಾಯಕ ಋತ್ವಿಜನನ್ನಾಗಿ ಮಾಡಿಕೊಂಡು ಅಧ್ವರ್ಯುವಿನ ಕೆಲಸ ಮಾಡಿದನು.',
        '0.18': 'ರಾಮನ ಪೂಜೆಗೆ ಹೂವನ್ನು ತರುವಾಗ ಅವನು ಎರಡು ಕೈಗಳಿಂದ ಶ್ರದ್ಧೆಯಿಂದ ತಂದನು; ಸಂಜೀವಿನಿ ಮೊದಲಾದ ಔಷಧಿಗಳ ನೆಲೆಯಾದ ಮಹಾಪರ್ವತವನ್ನು ಒಂದೇ ತೋಳಿನಿಂದ ತರುವಾಗ ಅವನಿಗೆ ಯಾವ ಪ್ರಯಾಸವೂ ಆಗಲಿಲ್ಲ.',
        '0.19': 'ಶತ್ರುಗಳನ್ನು ಸಂಹರಿಸಿದ, ಅಗ್ನಿಪ್ರವೇಶದಿಂದ ಶುದ್ಧಿ ಪ್ರಕಟವಾದ ರಾಜಪುತ್ರಿ ಸೀತೆಯೊಡನೆ ಕೂಡಿ, ಚಿನ್ನದ ಮಾಲೆಯಿಂದ ಅಲಂಕೃತನಂತೆ ಶೋಭಿಸುತ್ತಿದ್ದ ಪರಮಪುರುಷನನ್ನು ಅವನು ಸೇವಿಸಿದನು.',
        '0.20': 'ಶ್ಯಾಮವರ್ಣದ, ಮಂದಹಾಸಮುಖದ, ವಿಶಾಲವೂ ದೀರ್ಘವೂ ಆದ ತೋಳುಗಳ, ಕಮಲನೇತ್ರದ, ಗಜರಾಜನ ನಡಿಗೆಯ, ಜಗನ್ಮಂಗಳವಾದ ಅಯೋಧ್ಯಾಪತಿಯ ರೂಪವನ್ನು ಅವನು ಬಹುಕಾಲ ತನ್ನ ಕಣ್ಣುಗಳಿಂದ ಸೇವಿಸಿದನು.',
        '0.21': 'ಪಟ್ಟಾಭಿಷೇಕವು ಮುಗಿದ ಮೇಲೆ, “ನಮ್ಮನ್ನು ಭಜಿಸುವವರಲ್ಲಿ ಅತ್ಯಂತ ಪ್ರಿಯನಾದವನಿಗೆ ಇದನ್ನು ಕೊಡು” ಎಂಬ ರಾಮನ ಮಾತಿನಂತೆ ಸೀತೆಯು ಸುಂದರ ರತ್ನಹಾರದ ನೆಪದಲ್ಲಿ ತನ್ನ ದೀರ್ಘವಾದ ಕರುಣೆಯನ್ನು ಅವನಿಗೆ ಕಟ್ಟಿದಳು.',
        '0.22': 'ಹೃದಯದ ಅಪಾರ ಸ್ನೇಹ ತುಂಬಿದ ಕೈಯನ್ನು ಅವನ ತಲೆಯ ಮೇಲಿಟ್ಟು, ದಯೆಯಿಂದ ಆರ್ದ್ರವಾದ ದೃಷ್ಟಿಯಿಂದ, ಅಮೃತದಂತಹ ಮಾತಿನಿಂದ, ಸೇವೆಗೆ ಪ್ರಸನ್ನನಾದ ದೇವನು ಅವನಿಗೆ ತನ್ನೊಡನೆ ಭೋಗವನ್ನು ಅನುಗ್ರಹಿಸಿದನು.',
        '0.23': 'ರಾಮನಿಗೆ ಅವನಿಗಿಂತ ಪ್ರಿಯರಾರೂ ಇರಲಿಲ್ಲ; ರಾಮರಾಜ್ಯದಲ್ಲಿ ದುರ್ಲಭವಾದುದು ಏನೂ ಇರಲಿಲ್ಲ; ಆದರೂ ಅವನ ಪಾದಸೇವೆಯಲ್ಲೇ ಆಸಕ್ತನಾದ ಹನುಮಂತನು ಭೋಗಗಳನ್ನು ಬಯಸಲಿಲ್ಲ — ಅದೇ ನಿಜವಾದ ವೈರಾಗ್ಯ.',
        '0.24': '“ನಾಥ, ನಮೋ ನಮಃ, ನಿನಗೆ ನಮೋ ನಮಃ; ರಾಮ, ನಮೋ ನಮಃ, ನಿನಗೆ ನಮೋ ನಮಃ; ನಾಥ, ನಿನ್ನ ಪಾದಾರವಿಂದಕ್ಕೆ ಮತ್ತೆ ಮತ್ತೆ ನಮಿಸುತ್ತೇನೆ” ಎಂದು ನಮಿಸುತ್ತಾ ಅವನು ಆನಂದಪಟ್ಟನು.',
        '0.25': 'ಆ ಕಪಿಶ್ರೇಷ್ಠನ ಮೇಲೆ ಸೀತಾಪತಿಯು ತೋರಿದ ಪರಮಪ್ರಸಾದವನ್ನು ಏನೆಂದು ವರ್ಣಿಸೋಣ! ಭೂಮಿಯನ್ನು ಬಿಟ್ಟು ಹೊರಡುವಾಗ ನಿತ್ಯಸೇವೆಗಾಗಿ ತನ್ನನ್ನೇ ಅವನಿಗೆ ಕೊಟ್ಟನು.',
        '0.26': 'ಭಕ್ತರಿಗೆ ಆನಂದಕಾರಣವಾದ ರಾಮಕಥಾಮೃತದಲ್ಲಿ ಸದಾ ಮುಳುಗಿರುವ ಅವನು ಈಗಲೂ ಕಿಂಪುರುಷವರ್ಷದಲ್ಲಿ ತನ್ನ ಸ್ವಾಮಿಯಾದ ರಾಮನನ್ನು ಸೇವಿಸುತ್ತಾ ಇದ್ದಾನೆ.',
        '0.27': 'ಅದೇ ವಾಯುದೇವರ ಎರಡನೆಯ ಅವತಾರವೇ ಭೀಮನೆಂದು ಸಜ್ಜನರು ಹೇಳುತ್ತಾರೆ; ಪ್ರೀತಿಯುಳ್ಳ ವಾಯುವಿನ ಸ್ಪರ್ಶಮಾತ್ರದಿಂದಲೇ ಪಾಂಡುರಾಜನ ಪತ್ನಿ ಕುಂತಿಯು ಅವನನ್ನು ಹೆತ್ತಳು.',
        '0.28': 'ಹಿಂದೆ ಇಂದ್ರನ ಕೈಯಿಂದ ಎಸೆಯಲ್ಪಟ್ಟ ವಜ್ರಾಯುಧವು ಪರ್ವತಗಳ ರೆಕ್ಕೆಗಳನ್ನು ಮಾತ್ರ ಕತ್ತರಿಸಿತು; ಆದರೆ ತಾಯಿಯ ಕೈಯಿಂದ ಜಾರಿ ಬಿದ್ದ ಈ ಶಿಶುವು ತನ್ನ ಅಂಗಸ್ಪರ್ಶದಿಂದಲೇ ಪರ್ವತದ ದೇಹವನ್ನು ಒಡೆದುಹಾಕಿದನು — ಇದು ಆಶ್ಚರ್ಯ!',
        '0.29': 'ಪಟ್ಟಣದಲ್ಲಿ ರಾಜಕುಮಾರರ ಸೋಮಾರಿ ಆಟಗಳನ್ನು ನೋಡಿ ಆ ಆಟದಲ್ಲಿ ಉತ್ಸಾಹವಿಲ್ಲದವನಾದ ಭೀಮನು, ಸಿಂಹಗಳ ಗುಂಪನ್ನೇ ಕೊಂದ ಕಾಡಿನ ತನ್ನ ಬಾಲ್ಯದ ಆಟವನ್ನು ಹಂಬಲದಿಂದ ನೆನೆಸಿಕೊಂಡನು.',
        '0.30': 'ಶತ್ರುವು ಕೊಟ್ಟ ವಿಷವನ್ನು ತಿಂದು ಜೀರ್ಣಿಸಿಕೊಂಡನು; ಆದ್ದರಿಂದ ಸರ್ಪಗಳ ವಿಷದ ಶಕ್ತಿಯೂ ಕುಂದಿತು; ಪ್ರಮಾಣಕೋಟಿಯಿಂದ ಆಟವಾಡುವಂತೆ ಮರಳಿ ಬಂದನು. ಜಗತ್ತಿಗೆ ಜೀವವನ್ನು ಕೊಡುವವನಲ್ಲಿ ಇದು ಆಶ್ಚರ್ಯವಲ್ಲ.',
        '0.31': 'ಯೋಗಿಯು ಯೋಗಬಲದಿಂದ ದೇಹವನ್ನು ದಹಿಸಿ ತನ್ನ ಧರ್ಮಗಳನ್ನು ಹೊತ್ತು ನಾರಾಯಣನನ್ನು ಸೇರುವಂತೆ, ಭೀಮನು ತನ್ನ ಶಕ್ತಿಯಿಂದ ಅರಗಿನ ಮನೆಯನ್ನು ಸುಟ್ಟು, ಸಹೋದರರನ್ನು ಹೊತ್ತು ಹೊರಬಂದು, ಲೋಕಪೂಜ್ಯನಾಗಿ ವ್ಯಾಸರೂಪಿ ನಾರಾಯಣನನ್ನು ಸೇರಿದನು.',
        '0.32': 'ಶುದ್ಧಬುದ್ಧಿಯುಳ್ಳ ಆ ಕೃತಾರ್ಥನು ಇಲ್ಲಿಯವರೆಗೆ ಮಾಡಿದ ಸತ್ಕರ್ಮಗಳನ್ನೆಲ್ಲ ಭೂಮನಾದ ವ್ಯಾಸರಿಗೆ ಸಮರ್ಪಿಸಿ, ಮುಂದೆ ಮಾಡುವವುಗಳನ್ನೂ ಅವರ ಪೂಜೆಯೆಂದೇ ಸಂಕಲ್ಪಿಸಿದನು.',
        '0.33': 'ಆಮೇಲೆ ಆಕಾಶವನ್ನು ಆಶ್ರಯಿಸಿದ ಬಕನನ್ನು (ಬಕಾಸುರನನ್ನು) ನಿವಾರಿಸಿದ, ಇತರ ಪಕ್ಷಿಗಳನ್ನು (ಶತ್ರುಗಳನ್ನು) ಓಡಿಸಿದ, ಉತ್ತಮ ಪಕ್ಷವುಳ್ಳ ಆ ರಾಜಹಂಸನು ಸಹೋದರರೊಡನೆ ರಾಜಹಂಸಿಯಂತೆ ರಾಜಕನ್ಯೆಯಾದ ದ್ರೌಪದಿಯನ್ನು ಪಡೆದನು.',
        '0.34': 'ನೀಲಕಮಲದ ಕಾಂತಿಯನ್ನು ಮೀರಿಸುವ ಸೌಂದರ್ಯವುಳ್ಳ, ಮಂದಹಾಸದ ಚಂದ್ರಮುಖವುಳ್ಳ, ಕಮಲದಂತೆ ವಿಶಾಲ ನೇತ್ರಗಳುಳ್ಳ, ತನ್ನ ಸೋದರಮಾವನ ಮಗನಾದ ಪ್ರಿಯ ಮುಕುಂದನನ್ನು ಭೀಮನು ಬಹುಕಾಲ ಸಂತೋಷದಿಂದ ಆದರಿಸಿದನು.',
        '0.35': 'ಆ ವೀರನು ಮಹಾಗದಾಧಾರಿಯೂ ರಣಚಂಡನೂ ಆದ ಬೃಹದ್ರಥಪುತ್ರ ಜರಾಸಂಧನನ್ನು ಬೇಗನೆ ಕೆಡವಿ, ಗೋವಿಂದ ಮತ್ತು ಇಂದ್ರಪುತ್ರ ಅರ್ಜುನರೊಡನೆ ಸೇರಿ ಧರ್ಮರಾಜನಿಂದ ಅತ್ಯುಜ್ಜ್ವಲವಾದ ರಾಜಸೂಯಯಾಗವನ್ನು ಮಾಡಿಸಿದನು.',
        '0.36': 'ಶತ್ರುಗಳನ್ನು ಕೊಲ್ಲುವ ಬಯಕೆಯಿಂದ ತೀಕ್ಷ್ಣನಾದ ಭೀಮನು ದುಃಶಾಸನನಿಂದ ಕೆದರಲ್ಪಟ್ಟ ತನ್ನ ಪ್ರಿಯೆಯ ನಯವಾದ ಗುಂಗುರಾದ ಕಪ್ಪು ಕೂದಲನ್ನು ಕರಿನಾಗರಹಾವುಗಳನ್ನು ಸಂಗ್ರಹಿಸುವಂತೆ ಸಂಗ್ರಹಿಸಿದನು.',
        '0.37': 'ಕಾಡಿನಿಂದ ಕಾಡಿಗೆ ಜಾಜ್ವಲ್ಯಮಾನವಾಗಿ, ಕ್ರೂರರಾದ ರಾಜಸಮೂಹವನ್ನು ಸುಡಬಯಸುತ್ತಿದ್ದ ವೃಕೋದರನೆಂಬ ಅಗ್ನಿಯ ಮಹಾತೇಜಸ್ಸಿನಿಂದ ಜನರಿಗೆ ಭಯ ಕೊಡುತ್ತಿದ್ದ ಪ್ರಾಣಿಗಳು ನಾಶವಾದವು.',
        '0.38': 'ಪರ್ವತರಾಜನ ಮೇಲೆ ಅಲ್ಲಲ್ಲಿ ಸಂಚರಿಸುತ್ತಿದ್ದ, ದೊಡ್ಡ ದೇಹವುಳ್ಳ, ಕೆಂಗಣ್ಣಿನ, ಹಾವುಗಳಂತೆ ಎರಡು ನಾಲಿಗೆಯ, ಮಣಿಮಂತನೇ ಮೊದಲಾದ ಅನೇಕ ಕ್ರೂರ ಕ್ರೋಧವಶರೆಂಬ ರಾಕ್ಷಸರನ್ನು ಅವನು ಕೊಂದನು.',
        '0.39': 'ಆಮೇಲೆ ಬೂದಿಯಲ್ಲಿ ಅಡಗಿದ ಬೆಂಕಿಯಂತೆ ಬೇರೆ ವೇಷದಲ್ಲಿ ಮರೆಯಾಗಿದ್ದ ತೇಜಸ್ವಿಯಾದ ವಾಯುಪುತ್ರನು ಕ್ರಮವಾಗಿ ಎಲ್ಲ ದಿಕ್ಕುಗಳನ್ನೂ ಆಕ್ರಮಿಸಿದ್ದ, ಗದ್ದಲದ, ಪ್ರಚಂಡವಾದ ಕೀಚಕಸಮೂಹವನ್ನೆಲ್ಲ ಭಸ್ಮಮಾಡಿದನು.',
        '0.40': 'ಕಪ್ಪು ದಾರಿಯುಳ್ಳ ಅಗ್ನಿಯಂತೆ ಕೃಷ್ಣನ ಮಾರ್ಗವನ್ನು ಅನುಸರಿಸುತ್ತಾ, ವಿಜಯನೊಡನೆ (ಅರ್ಜುನ/ಜಯ) ಕೂಡಿ, ಮತ್ತೆ ಮತ್ತೆ ಮಹಾಯುಧಗಳನ್ನು (ಜ್ವಾಲೆಗಳನ್ನು) ಧರಿಸಿ, ಅಜೇಯನಾಗಿ ಅವನು ಭೀಷ್ಮ ದ್ರೋಣ ಮೊದಲಾದವರಿಂದ ಭಯಂಕರವಾದ ಶತ್ರುವನವನ್ನು ದಹಿಸುತ್ತಾ ಬೆಳಗಿದನು.',
        '0.41': 'ಬಲಿಷ್ಠರೂ, ಮೇಲೆದ್ದು ಬಂದವರೂ, ಅಧೀರರೂ, ಅತಿತೀಕ್ಷ್ಣಕೋಪಿಗಳೂ, ರೆಕ್ಕೆ (ಪಕ್ಷ) ಸುಟ್ಟುಹೋದವರೂ ಆದ ಧೃತರಾಷ್ಟ್ರಪುತ್ರರೆಲ್ಲರನ್ನು ನಾಶಮಾಡಿ, ಅನೇಕ ಆಯುಧಗಳೊಡನೆ ಲೀಲೆಯಾಡುವ ಅವನು ಪರಮಶೋಭೆಯಿಂದ ಮೆರೆದನು.',
        '0.42': 'ಕೃಷ್ಣನ ಪಾದಕಮಲಗಳಿಗೆ ದುಂಬಿರಾಜನೂ, ಕೃಷ್ಣೆಯ (ದ್ರೌಪದಿಯ) ಮುಖಕಮಲಕ್ಕೆ ಹಂಸರಾಜನೂ, ಪ್ರಜೆಗಳೆಂಬ ಕಮಲಸಮೂಹಕ್ಕೆ ಸೂರ್ಯನೂ ಆದ ವೀರರಾಜ ಭೀಮನು ಸಹೋದರರೊಡನೆ ವಿರಾಜಿಸಿದನು.',
        '0.43': 'ತನ್ನ ಸಹೋದರ ಅರ್ಜುನನ ಮೊಮ್ಮಗನಾದ ಪರೀಕ್ಷಿತನಿಗೆ ಭೂಮಿಯನ್ನೂ, ಅಸುರರ ಮನಸ್ಸಿನಲ್ಲಿ ಸಂಕಟವನ್ನೂ, ಮೂರು ಲೋಕಗಳಲ್ಲಿ ಕೀರ್ತಿಯನ್ನೂ, ಹೃದಯದಲ್ಲಿ ಮುಕುಂದನನ್ನೂ ಇಟ್ಟು, ಭೀಮನು ಸಹೋದರರೊಡನೆ ತನ್ನ ಸ್ಥಾನವನ್ನು ಸೇರಿದನು.',
        '0.44': 'ಹೀಗೆ ವಿಷ್ಣುಪಾದವನ್ನು ಸೇವಿಸುವ ವಾಯುವಿನ ಘೋರ ಹೊಡೆತಗಳಿಂದ ನಾಶವಾದ ದೇವಶತ್ರುಗಳು, ಗಾಳಿಯಿಂದ ಚದುರಿದ ಮೋಡಗಳಂತೆ ಸಾರವನ್ನು ಕಳೆದುಕೊಂಡು ಚಂಚಲ ನಡತೆಯವರಾಗಿ ಶೋಭೆಯನ್ನು ಕಳೆದುಕೊಂಡರು.',
        '0.45': 'ಇದಕ್ಕೆ ಪ್ರತೀಕಾರ ಮಾಡಬಯಸಿದ, ಶಕ್ತಿಗುಂದಿದ ಅವರು ಹೀಗೆ ಸಂಕಟಕ್ಕೆ ಸಿಲುಕಿ, ಕಾಲಕ್ರಮದಲ್ಲಿ ಕಲಿಯುಗದಲ್ಲಿ ತಮಗೆ ತಕ್ಕುದಾದ “ಮುಕುಂದನು ನಿರ್ಗುಣ” ಎಂಬ ವಾದವನ್ನು ರಚಿಸಿದರು.',
        '0.46': '(ಕವಿಯ ವಾದಾತ್ಮಕ ಭಾಗ ಇಲ್ಲಿಂದ.) ಹಿಂದೆ ಭೀಮನಿಂದ ಹತನಾದ, ಅಪಾರ ವೈರವುಳ್ಳ, ವಾಗ್ಮಿಯೂ ಪ್ರಾಬಲ್ಯವನ್ನು ಬಯಸುವವನೂ ಈಶನನ್ನು ಸಂತೋಷಪಡಿಸಿದವನೂ ಆದ ಮಣಿಮಂತನು “ಸಂಕರ” ಎಂಬ ಹೆಸರಿನಿಂದ ಭೂಮಿಯಲ್ಲಿ ಹುಟ್ಟಿದನು; ಇತರ ಅಸುರಮುಖ್ಯರೂ ಸ್ಪರ್ಧೆಯಿಂದ ಇಲ್ಲಿ ಜನಿಸಿದರು.',
        '0.47': 'ಹೃದಯದಲ್ಲಿ ತಿಳುವಳಿಕೆಯಿಲ್ಲದ ಬೆಕ್ಕು ಯಜ್ಞದ ಹವಿಸ್ಸನ್ನು ಹಿಡಿದಂತೆ, ಸಾರಹೀನವನ್ನು ಬಯಸುವ ನಾಯಿ ಪುರೋಡಾಶವನ್ನು ಹಿಡಿದಂತೆ, ಚಂಚಲವಾದ ಕೋತಿ ರತ್ನಹಾರವನ್ನು ಹಿಡಿದಂತೆ, ಈ ಪಾಪಿಯು ವೇದಾದಿಗಳನ್ನು ಹಿಡಿದನು.',
        '0.48': '“ಇಲ್ಲದಿದ್ದರೆ ಜನರು ನಮಿಸುವುದಿಲ್ಲ” ಎಂದು ಭಾವಿಸಿ ಆ ಶಠನು ನಾಲ್ಕನೆಯ ಆಶ್ರಮವಾದ ಸಂನ್ಯಾಸವನ್ನು ಸ್ವೀಕರಿಸಿದನು — ನಿರ್ಮಲವಾದ ಕಮಲಸರೋವರವನ್ನು ಕಲಕಬಯಸಿ ಅಡಗಿಸಲಾಗದ ದುಷ್ಟ ಆನೆ ಪ್ರವೇಶಿಸುವಂತೆ.',
        '0.49': 'ವೇದಬಾಹಿರವಾದ ಮಾಧ್ಯಮಿಕ (ಬೌದ್ಧ) ಮತವು ಖಂಡಿತವಾದುದನ್ನು ಕಂಡು, ಆ ಪಕ್ಷದ ಪಕ್ಷಪಾತಿಯಾದ ಅವನು ಅದೇ ಪಕ್ಷವನ್ನು ಪ್ರತಿಪಾದಿಸಲು ತಕ್ಕ ಮಾರ್ಗವನ್ನು ಇಲ್ಲಿ ನಿರೂಪಿಸಿದನು.',
        '0.50': 'ಬೌದ್ಧರು “ಅಸತ್” ಎಂದ ಸ್ಥಾನದಲ್ಲಿ ಅವನು ಸತ್ತು ಅಸತ್ತುಗಳೆರಡರಿಂದ ಭಿನ್ನವಾದುದನ್ನು ಹೇಳಿ, ಅವರ “ಸಂವೃತಿ”ಗೆ “ಮಾಯೆ” ಎಂದು ಹೆಸರಿಟ್ಟನು; ಶೂನ್ಯವನ್ನು ಸಾಧಿಸಲು ಬ್ರಹ್ಮವನ್ನೂ ಅಖಂಡವೆಂದನು — ಆದ್ದರಿಂದ ಅವನು ಪ್ರಚ್ಛನ್ನಬೌದ್ಧನೆಂದು ಪ್ರಸಿದ್ಧನೆಂದು ಕವಿ ಹೇಳುತ್ತಾನೆ.',
        '0.51': 'ವೇದಸಮೂಹವೆಂಬ ಕುದುರೆಯನ್ನೂ, ತನ್ನ ಕಿರಣಗಳಿಂದ (ವಾಕ್ಯಗಳಿಂದ) ಎಲ್ಲವನ್ನೂ ಬೆಳಗುವ ಬ್ರಹ್ಮಸೂತ್ರಸಮೂಹವೆಂಬ ಸೂರ್ಯನನ್ನೂ ಅವನು ಕದ್ದುದರಿಂದ ಅವನನ್ನು ಮಹಾತಸ್ಕರನೆಂದು ಕರೆಯುತ್ತಾರೆ.',
        '0.52': 'ವ್ಯಾಸರು ರಚಿಸಿದ ಸೂತ್ರಗಳಿಗೇ ವಿರುದ್ಧವಾಗಿ ಮಾತನಾಡುತ್ತಾ “ನಾನು ಅವುಗಳ ಭಾಷ್ಯಕಾರ” ಎಂದು ಹೇಳಿದವನನ್ನು ಆ ಕ್ಷಣವೇ ಸುಡಬಯಸದ ವ್ಯಾಸರೂಪಿ ಭಗವಂತನು ಕ್ಷಮೆಯ ಸಮುದ್ರ.',
        '0.53': 'ವೇದಗಳೆಂಬ ಶ್ರೇಷ್ಠ ಮಣಿದೀಪಗಳ ಸಮೂಹವು ಅವನ ವಿಸ್ತಾರವಾದ ವಾಕ್ಯಸಮೂಹವೆಂಬ ಕೆಸರಿನಲ್ಲಿ ಬೆಳಕು ಮುಚ್ಚಿಹೋಯಿತು; ಅಜ್ಞರಿಗೆ ಸಂಕರತೆಯ (ಗೊಂದಲದ) ಆಕರನಾದ್ದರಿಂದ ಅವನು “ಸಂಕರ” ಎಂದು ಕೇಳಲ್ಪಟ್ಟನಂತೆ.',
        '0.54': '“ಜಗತ್ತು ಮಿಥ್ಯೆ, ಪರಮಾತ್ಮನು ನಿರ್ಗುಣ, ಜೀವರಲ್ಲಿ ಭೇದವಿಲ್ಲ” ಎಂದು ದೈತ್ಯರು ತಮ್ಮ ಮಾತಿಗೆ ಎಲ್ಲ ದಿಕ್ಕುಗಳಲ್ಲೂ ಬಹಳ ಪ್ರಸಿದ್ಧಿಯನ್ನು ತಂದರು; ಅಯ್ಯೋ! ಆನಂದಾದಿ ಮಹಾಗುಣಗಳಿಂದ ಪರಿಪೂರ್ಣನಾದ ವಾಸುದೇವನು ಸಜ್ಜನರ ಮನಸ್ಸಿನಲ್ಲೂ ಮೆಲ್ಲಮೆಲ್ಲನೆ ಮರೆಯಾದನು.',
        '0.55': 'ಹೀಗೆ ಕವಿಕುಲತಿಲಕರಾದ ತ್ರಿವಿಕ್ರಮಪಂಡಿತಾಚಾರ್ಯರ ಪುತ್ರ ನಾರಾಯಣಪಂಡಿತಾಚಾರ್ಯರು ರಚಿಸಿದ “ಆನಂದ” ಎಂಬ ಅಂಕಿತವುಳ್ಳ ಶ್ರೀಮತ್ಸುಮಧ್ವವಿಜಯ ಮಹಾಕಾವ್ಯದ ಮೊದಲನೆಯ ಸರ್ಗ ಮುಗಿಯಿತು.',
      },
    },
    'sumadhva-vijaya-02': {
      verses: {
        '0.0': 'ಕಾಲಬಲದಿಂದ ಜ್ಞಾನಸೂರ್ಯನು ಅಸ್ತಮಿಸಲು, ದುರ್ಭಾಷ್ಯಗಳೆಂಬ ದಟ್ಟ ಕತ್ತಲಿನಿಂದ ಕುರುಡಾದ ಜನರು ಸಜ್ಜನರ ಮಾರ್ಗದಿಂದ ಜಾರುತ್ತಿರಲು, ಖಿನ್ನಮನಸ್ಕರಾದ ಚತುರ್ಮುಖಬ್ರಹ್ಮನೇ ಮೊದಲಾದ ದೇವತೆಗಳು ಮುಕುಂದನಿಗೆ ಶರಣು ಹೋದರು.',
        '0.1': 'ಮೂರು ಯುಗಗಳಲ್ಲಿ ಮಾತ್ರ ಪ್ರಕಟನಾಗುವುದರಿಂದ “ತ್ರಿಯುಗ” ಎನಿಸಿದ ಸ್ವಾಮಿಯು ಕಲಿಯುಗದಲ್ಲಿ ಅವತರಿಸಲು ಬಯಸದೆ, ಅವತಾರವಿಲ್ಲದ ಬ್ರಹ್ಮನಿಗೂ ಆಜ್ಞಾಪಿಸಲು ಬಯಸದೆ, ಆ ಕಾರ್ಯಕ್ಕೆ ಸಮರ್ಥನಾದ ಬೇರೆ ಸರ್ವಜ್ಞನನ್ನು ಕಾಣದೆ, ಮುಗುಳ್ನಗೆಯಿಂದ ಜಗಜ್ಜೀವನನಾದ ವಾಯುವಿಗೆ ಹೇಳಿದನು.',
        '0.2': '“ವೇದಾಂತಮಾರ್ಗವನ್ನು ಹುಡುಕುತ್ತಾ ದೀನರೂ ದುಃಖಿತರೂ ಆದ ದೈವೀಪ್ರಜೆಗಳು ಆಶ್ರಯವಿಲ್ಲದೆ ನಮ್ಮ ಕರುಣೆಗೆ ಪಾತ್ರರಾಗಿದ್ದಾರೆ. ಸುಮುಖನೇ, ಬೇರೊಂದು ರೂಪದಿಂದ ಭೂಭಾಗವನ್ನು ಅಲಂಕರಿಸಿ, ನನ್ನ ಸದ್ಗುಣಗಳ ನಿರ್ಣಯದಿಂದ ಅವರನ್ನು ಆನಂದಪಡಿಸು.”',
        '0.3': 'ಕೈಮುಗಿದು ವಾಯುದೇವರು ಆ ಆಜ್ಞೆಯನ್ನು ಉಜ್ಜ್ವಲವಾದ ಅಮೂಲ್ಯ ಶಿರೋಮಣಿಯಂತೆ ತಲೆಯಲ್ಲಿ ಧರಿಸಿ, ದೇವತೆಗಳ ಪ್ರಾರ್ಥನೆಯನ್ನು ಹಾರದಂತೆ ಹೃದಯದಲ್ಲಿ ಧರಿಸಿ, ತನ್ನವರನ್ನು ಅನುಗ್ರಹಿಸಬಯಸಿ ಅವತರಿಸಲು ನಿಶ್ಚಯಿಸಿದರು.',
        '0.4': '“ವೇದಾಂತದ ಸಿದ್ಧಾಂತದ ಸಾರವನ್ನು ನಾವು ಅರಿಯೆವು; ಅಯ್ಯೋ, ಶ್ರೇಯಸ್ಸನ್ನು ಹೇಗೆ ಪಡೆಯುವೆವು?” ಎಂದು ಅನೇಕ ಸಜ್ಜನಕುಲಗಳು ಚಿಂತಾಕುಲವಾದ ಕಾಲವೇ ಆಗ ಬಂದಿತು.',
        '0.5': 'ಅವರನ್ನು ಸಂತೋಷಪಡಿಸಲು ಶುಭಸೂಚನೆ ಕೊಡುವುದಕ್ಕಾಗಿ, ಮಹೋತ್ಸವಕ್ಕೆ ಕುತೂಹಲದಿಂದ ಕೋಲಾಹಲದೊಡನೆ ಮಹಾಜನಸಮೂಹ ಸೇರಿದಾಗ, ರಜತಪೀಠಪುರದಲ್ಲಿ (ಉಡುಪಿಯಲ್ಲಿ) ನೆಲೆಸಿರುವ ದೇವರು ಒಬ್ಬ ಪುರುಷನನ್ನು ಆವೇಶಿಸಿದರು.',
        '0.6': 'ಸ್ವಭಾವತಃ ನೃತ್ಯಕುಶಲನಲ್ಲದ ಆ ಪುರುಷನನ್ನು ಆವೇಶಿಸಿ, ತನ್ನ ಜನರಿಗೆ ನಂಬಿಕೆ ಹುಟ್ಟಿಸುತ್ತಾ, ಎತ್ತರವಾದ ಧ್ವಜಸ್ತಂಭದ ತುದಿಯಲ್ಲಿ ರಂಗದ ಮೇಲಿನ ನಟನಂತೆ ಅಂಗವಿನ್ಯಾಸ ಮಾಡುತ್ತಾ ಎಲ್ಲರಿಗೂ ಆಶ್ಚರ್ಯವಾಗುವಂತೆ ಚೆನ್ನಾಗಿ ಕುಣಿದನು.',
        '0.7': 'ಅಲ್ಲಿನ ಜನರನ್ನು ಉದ್ದೇಶಿಸಿ, ತೋಳನ್ನು ಮೇಲೆತ್ತಿ, ಆಣೆಯೊಡನೆ ಗಟ್ಟಿಯಾಗಿ ಹೀಗೆ ಹೇಳಿದನು: “ಎಲ್ಲ ಜನರ ಹಿತಕ್ಕಾಗಿ ನಡೆಯುವ ಸರ್ವಜ್ಞನಾದ ಭಗವಂತನು ಶೀಘ್ರದಲ್ಲೇ ಈ ಲೋಕದಲ್ಲಿ ಇಲ್ಲಿ ಹುಟ್ಟುವನು.”',
        '0.8': 'ಸಪ್ತದ್ವೀಪ ಸಪ್ತಸಮುದ್ರಗಳುಳ್ಳ ಭೂಮಿಯಲ್ಲಿ, ಕರ್ಮಭೂಮಿಯಾದ ಭಾರತಖಂಡದಲ್ಲಿ, ಕಲಿಯುಗದಲ್ಲಿ, ಅತಿ ನಿರ್ಮಲವಾದ ವಂಶದಲ್ಲಿ ಜನಿಸಿದ, ಸಜ್ಜನರಾದ ಮಧ್ಯಗೇಹ ಕುಲಕ್ಕೆ ಶಿರೋಮಣಿಯಾದ ಒಬ್ಬ ಬ್ರಾಹ್ಮಣನಿದ್ದನು.',
        '0.9': 'ವೇದಾದ್ರಿಯ ಮತ್ತು ಪವಿತ್ರ ರಜತಪೀಠಪುರದ ಸ್ವಾಮಿಗಳಿಂದ ಅಲಂಕೃತವಾದ, ಮೇರುಪರ್ವತದ ಅಧಿಪತಿಯಿಂದ ಬೆಳಗುವ ಇಲಾವೃತದಂತೆ ಶೋಭಿಸುವ, ಶ್ರೇಷ್ಠಗುಣಗಳುಳ್ಳ ಶಿವರೂಪ್ಯ (ಶಿವಳ್ಳಿ) ಎಂಬ ಗ್ರಾಮವೇ ಅವನ ಮೂಲಸ್ಥಾನವಾಗಿತ್ತು.',
        '0.10': 'ಪರಶುರಾಮನಿಂದ ಪ್ರತಿಷ್ಠಿತಳಾದ ಹರಿಯ ತಂಗಿ ದುರ್ಗೆಯ ಹೊಳೆಯುವ ವಿಮಾನವು ಶಿಖರದಲ್ಲಿರುವ ಬೆಟ್ಟದಿಂದ ಶೋಭಿತವಾದ “ಪಾಜಕ” ಎಂಬ ಕ್ಷೇತ್ರದಲ್ಲಿ ಮೂರು ಕುಲಗಳಿಗೆ ಏಕೈಕ ಧ್ವಜದಂತಿದ್ದ ಅವನು ವಾಸಿಸುತ್ತಿದ್ದನು; ಜಗತ್ತನ್ನು ಕಾಪಾಡುವುದರಿಂದ (ಪಾಜ) ಸದಾ ಸುಖವನ್ನು (ಕ) ಧರಿಸುವುದರಿಂದ ಅದು ಪಾಜಕ.',
        '0.11': 'ಪುರುಷಾರ್ಥಕ್ಕೆ ಕಾರಣವಾದ ಅನುಪಮ ಸಂಪತ್ತನ್ನು ಕೊಡಲು ಯೋಗ್ಯಳಾದ, ಉಚಿತಸ್ವರೂಪದ, ಚಿನ್ನದಂತೆ ಹೊಳೆಯುವ (ಉತ್ತಮ ವರ್ಣಗಳಿಂದ ಶೋಭಿಸುವ ವೇದವಿದ್ಯೆಯಂತಿರುವ), ಶ್ರೇಷ್ಠ ಬ್ರಾಹ್ಮಣನಿಂದ ಕೊಡಲ್ಪಟ್ಟ ಕನ್ಯೆಯನ್ನು ಅವನು ವಿವಾಹವಾದನು.',
        '0.12': 'ಮಹಾವಿವೇಕಿಯು ನಿರ್ಮಲವಾದ ಉಪನಿಷತ್ತಿನಲ್ಲಿ, ಶುದ್ಧೇಂದ್ರಿಯನು ಭಕ್ತಿಯಲ್ಲಿ, ಮಿಥ್ಯಾಭಿಮಾನವಿಲ್ಲದವನು ಪರಮಮುಕ್ತಿಯಲ್ಲಿ ರಮಿಸುವಂತೆ, ಆ ದ್ವಿಜಶ್ರೇಷ್ಠನು ನಿರಂತರ ಆನಂದವನ್ನು ಕೊಡುವ ಅವಳೊಡನೆ ರಮಿಸಿದನು.',
        '0.13': 'ಸ್ವಧರ್ಮನಿರತನಾದ ಆ ಧೀರನು ಕುಲದೇವತೆಯಾದ ಆ ಪ್ರಭುವಿನ ಪಾದಗಳಲ್ಲಿ ಭಕ್ತಿಯನ್ನು ನೆಲೆಗೊಳಿಸಿದನು; ಭಾರತ ಪುರಾಣಗಳ ಮಹಾರಹಸ್ಯವನ್ನು ಅರಿತ ಆ ವಿನಯಶಾಲಿಯನ್ನು ಜನರು “ಭಟ್ಟ” ಎಂದು ಕರೆಯುತ್ತಾರೆ.',
        '0.14': 'ಗೋವಿಂದನ ಸುಂದರ ಕಥಾಮೃತದಿಂದ ಅವನು ಮನುಷ್ಯರ ಇಂದ್ರಿಯಗಳನ್ನು ಮಾತ್ರವಲ್ಲ, ರಜತಪೀಠಪುರದಲ್ಲಿ ಶ್ರೀಪತಿಯ ಪಾದಕಮಲಗಳನ್ನು ಸೇವಿಸುವ ದೇವತೆಗಳ ಇಂದ್ರಿಯಗಳನ್ನೂ ಆನಂದಪಡಿಸುತ್ತಿದ್ದನು.',
        '0.15': 'ಹೀಗೆ ಹರಿಯ ಗುಣಕಥಾಮೃತದಿಂದ ತೃಪ್ತನಾಗಿದ್ದರೂ, ನಿರ್ಗುಣವಾದದಲ್ಲಿ ಹಠವುಳ್ಳ ಜನರನ್ನು ಕಂಡು, ಕಾಲಪ್ರಭಾವದಿಂದ ತತ್ತ್ವದಲ್ಲಿ ಸಂಶಯಗೊಂಡ ಆ ಬುದ್ಧಿವಂತನು ಶ್ರವಣದಿಂದ ಶುದ್ಧವಾದ ಬುದ್ಧಿಯಿಂದ ಚಿಂತಿಸಿದನು.',
        '0.16': '“‘ಪುತ್’ ಎಂಬ ನರಕದಿಂದ ಕಾಪಾಡುವವನೇ ಪುತ್ರ; ಅಪೂರ್ಣನಾದ ಪುರುಷನಿಂದ ಮುಖ್ಯ ರಕ್ಷಣೆ ಸುಲಭವಲ್ಲ. ಆದ್ದರಿಂದ ಸರ್ವಜ್ಞನೂ ದೋಷರಹಿತನೂ ವಿದ್ಯೆಯ ಆಕರದಂತಿರುವವನೂ ಆದ ಮಗನನ್ನು ನಾವು ಯಾವ ಉಪಾಯಗಳಿಂದ ಪಡೆಯೋಣ?”',
        '0.17': '“ಹಿಂದೆಯೂ ಕರ್ದಮ, ಪರಾಶರ, ಪಾಂಡು ಮೊದಲಾದವರು ಯಾರ ಸೇವೆಯಿಂದ ಗುಣಸಂಪನ್ನರಾದ ಮಕ್ಕಳನ್ನು ಪಡೆದರೋ, ಆ ಪೂರ್ಣಸದ್ಗುಣಶರೀರನೂ ಕರುಣಾಮೃತಸಾಗರನೂ ಕುಲಪತಿಯೂ ಆದ ನಾರಾಯಣನಿಗೆ ಶರಣು ಹೋಗೋಣ.”',
        '0.18': 'ಹೀಗೆ ಚಿಂತಿಸಿ, ಬೇರೆ ಬಂಧುವಿಲ್ಲದ ಆ ಶುಭಾತ್ಮನು ಧ್ಯಾನಯೋಗ್ಯನೂ ಪ್ರಿಯವನ್ನು ಕೊಡುವವನೂ ಸಂಸಾರಸಾಗರದ ಭಯವನ್ನು ನಾಶಮಾಡುವವನೂ ರಜತಪೀಠಪುರವಾಸಿಯೂ ಶೇಷಶಾಯಿಯೂ ಆದ ಭಗವಂತನನ್ನು ಹನ್ನೆರಡು ವರ್ಷ ಭಕ್ತಿಯಿಂದ ಸೇವಿಸಿದನು.',
        '0.19': 'ಪತ್ನಿಯೊಡನೆ ಭಗವಂತನ ಪಾದಕಮಲವನ್ನು ಸೇವಿಸುತ್ತಾ ಅವನು ಅಲ್ಪವಾದ ಭೋಗಗಳನ್ನೂ ಇನ್ನೂ ಅಲ್ಪಗೊಳಿಸಿದನು; ಸ್ವತಃ ದಾಂತವಾದ ಮನಸ್ಸನ್ನು ಮತ್ತಷ್ಟು ನಿಗ್ರಹಿಸಿದನು; ನಿರ್ಮಲವಾದ ದೇಹವನ್ನು ಇನ್ನಷ್ಟು ಶುದ್ಧಗೊಳಿಸಿದನು.',
        '0.20': 'ಗುಣಸಾಗರನಾದ ಪುತ್ರನನ್ನು ಬಯಸಿದ ಆ ದಂಪತಿಗಳು ಹಾಲನ್ನು ಮಾತ್ರ ಸೇವಿಸುವ ವ್ರತವೇ ಮೊದಲಾದ ಕಠಿಣವಾದ ವಿವಿಧ ಶ್ರೇಷ್ಠ ವ್ರತಗಳಿಂದ, ಹಿಂದೆ ದೇವತೆಗಳಿಂದ ಪ್ರೇರಿತರಾದ ಅದಿತಿ ಕಶ್ಯಪರಂತೆ, ಪೂರ್ಣಪುರುಷನನ್ನು ಅತ್ಯಂತ ಸಂತೋಷಪಡಿಸಿದರು.',
        '0.21': 'ಸ್ವಾಮಿಯ ಅಪಾರ ಕರುಣಾಮೃತದಿಂದ ಅಭಿಷಿಕ್ತರಾದ, ಶ್ರೀ ಶ್ರೀಧರರ ಅನುಗ್ರಹದ ಸಾರದಿಂದ ಪುಷ್ಟವಾದ ಕೃಶದೇಹಗಳುಳ್ಳ, ಅನೇಕ ವ್ರತಗಳಿಂದ ಉಂಟಾದ ದಿವ್ಯಕಾಂತಿಯುಳ್ಳ ಅವರು ದೇಹಶುದ್ಧಿಯನ್ನೂ ಮನಶ್ಶುದ್ಧಿಯನ್ನೂ ಪಡೆದರು.',
        '0.22': 'ಆಮೇಲೆ ಉಚಿತಕಾಲದಲ್ಲಿ ಪತಿಯಿಂದ ಆದರಿಸಲ್ಪಟ್ಟ ಆ ವಿಪ್ರಪುತ್ರಿಯು ಲೋಕಗಳ ಸುಖಕ್ಕಾಗಿ ಗರ್ಭವನ್ನು ಧರಿಸಿದಳು — ನಿರ್ಮಲ ಆಕಾಶವುಳ್ಳ, ದಿಕ್ಕುಗಳನ್ನು ಆಶೆಯಿಂದ ತುಂಬಿದ ರಾತ್ರಿಯು ಕತ್ತಲನ್ನು ಹೋಗಲಾಡಿಸುವ ಶುಕ್ಲಪಕ್ಷದ ಚಂದ್ರನನ್ನು ಧರಿಸಿದಂತೆ.',
        '0.23': 'ಶುಕ್ಲಪಕ್ಷದ ಚಂದ್ರಬಿಂಬದಂತೆ ಬೆಳೆಯುತ್ತಿದ್ದ ಅವನನ್ನು ಆ ವಿಪ್ರಪತ್ನಿಯು ಹೆರುವ ಮೊದಲೇ, ವಾಯುದೇವರು ತನ್ನ ಅಂಶದಿಂದ ಅವತರಿಸಿ, ರೂಪ್ಯಪೀಠದಲ್ಲಿ (ಉಡುಪಿಯಲ್ಲಿ) ವಿಷ್ಣುವಿಗೆ ನಮಸ್ಕರಿಸಿ ಅವರ ಮನೆಗೆ ಹೋದರು.',
        '0.24': 'ರಾಜನು ಶ್ರೇಷ್ಠ ನಗರವನ್ನು ಪ್ರವೇಶಿಸುವಂತೆ, ಸಕಲ ಸುಲಕ್ಷಣಗಳಿಂದ ಕೂಡಿದ, ಹೊಳೆಯುವ ಒಂಬತ್ತು ದ್ವಾರಗಳುಳ್ಳ ಆ ಪರಮಸುಂದರ ಮಂದಿರವನ್ನು (ದೇಹವನ್ನು) ಭುವನಾಧಿಪತಿಯಾದ ಆ ಭಗವಂತನು ಬೇರೆಯವರನ್ನು ಹೊರಹಾಕುತ್ತಾ ಪ್ರವೇಶಿಸಿದನು.',
        '0.25': '“ಸಜ್ಜನರೆಲ್ಲರೂ ಸಂತೋಷಪಡಲಿ, ದುರ್ಜನರು ಖಿನ್ನರಾಗಲಿ; ಈ ವಾಯುವು ಭೂಮಿಯಲ್ಲಿ ಪ್ರಕಟನಾದನು” ಎಂದು ಸಾರುವಂತೆ ದೇವದುಂದುಭಿಗಳ ಗಂಭೀರ ನಾದವು ಕುತೂಹಲಗೊಂಡ ಮನುಷ್ಯರಿಗೂ ಇಲ್ಲಿ ಕೇಳಿಸಿತು.',
        '0.26': 'ಸ್ವಾಮಿಯನ್ನು ಸೇವಿಸಿ ಮನೆಯ ಸಮೀಪಕ್ಕೆ ಬಂದ ಆ ಪ್ರಾಜ್ಞನು ಉತ್ಸವಕ್ಕೆಂಬಂತೆ ಮೊಳಗಿದ ದುಂದುಭಿನಾದವನ್ನೂ ಆಮೇಲೆ ಪುತ್ರಜನನದ ಸುದ್ದಿಯನ್ನೂ ಕೇಳಿ ಮಹಾಸುಖವನ್ನು ಪಡೆದನು; ತನ್ನ ಅಭೀಷ್ಟ ಸಿದ್ಧಿಸಿತೆಂಬ ಪರೋಕ್ಷವಾದ ಅರಿವನ್ನೂ ಪಡೆದನು.',
        '0.27': 'ಮನೆಯನ್ನು ಪ್ರವೇಶಿಸಿ, ಚಂದ್ರಮುಖನಾದ ತನ್ನ ಮಗನನ್ನು ಮತ್ತೆ ಮತ್ತೆ ಅಭಿನಂದಿಸಿ, ಮುಕುಂದನ ದಯೆಗೆ ವಂದಿಸಿ, ಸತ್ಕರ್ಮಿಯಾದ ಅವನು ಗುಣಸಮೂಹವನ್ನು ಹೊತ್ತು ಹುಟ್ಟಿದ ಆ ಶಿಶುವಿಗೆ ಜಾತಕರ್ಮವೇ ಮೊದಲಾದ ಸಂಸ್ಕಾರಗಳನ್ನು ಮಾಡಿದನು.',
        '0.28': 'ಜ್ಞಾನಕ್ಕಾಗಿಯೇ ಈ ಅಸುದೇವನು (ಪ್ರಾಣದೇವನು) ಅವತರಿಸಿದ್ದರಿಂದಲೂ, ಸದಾ ವಾಸುದೇವನ ಪಾದಭಕ್ತಿಯಲ್ಲಿ ನಿರತನಾಗಿದ್ದರಿಂದಲೂ, ನಾಮಕರಣ ಮಾಡಿದ ತಂದೆಯು ಇಟ್ಟ “ವಾಸುದೇವ” ಎಂಬ ಹೆಸರನ್ನೇ ದೇವತೆಗಳೂ ಅನುಮೋದಿಸಿದರು.',
        '0.29': 'ಶಿಶುವಿಗೆ ಹಾಲು ಕುಡಿಯಲು ಹಸುವನ್ನು ದಾನಮಾಡಿದ ಪೂರ್ವಾಲಯ ಕುಟುಂಬದ ಒಬ್ಬನು ಮುಂದೆ ತನ್ನ ಮಗನ ಮಗನಾಗಿಯೇ ಹುಟ್ಟಿ ಮೋಕ್ಷಕಾರಣವಾದ ಪರಮಾತ್ಮವಿದ್ಯೆಯನ್ನು ಪಡೆದನು; ದಾನವು ಪಾತ್ರದ ಗುಣಕ್ಕೆ ತಕ್ಕಂತೆ ನಿಶ್ಚಯವಾಗಿ ಫಲಿಸುತ್ತದೆ.',
        '0.30': 'ಒಮ್ಮೆ ಒಬ್ಬ ಆಪ್ತನಾದ ಬುಧನು ಎಂದೂ ಹೆದರದ, ಸದಾ ಅರಳಿದ ಕಣ್ಣುಗಳುಳ್ಳ, ಕಾಂತಿಯಿಂದ ಹೊಸ ಚಂದ್ರನನ್ನೂ ಅಣಕಿಸುವ, ಲೋಕದಲ್ಲಿ ಅಮೂಲ್ಯನಾದ ಆ ಪುತ್ರರತ್ನವನ್ನು ಎತ್ತಿಕೊಂಡು ತನ್ನ ಸ್ವಾಮಿಗೆ (ಉಡುಪಿಯ ದೇವರಿಗೆ) ಕಾಣಿಕೆಯಾಗಿ ಅರ್ಪಿಸಿದನು.',
        '0.31': 'ರಜತಪೀಠಪುರವಾಸಿಯಾದ ಹರಿಗೆ ನಮಸ್ಕರಿಸಿ, ಮಗುವಿಗೆ ಆಪತ್ತಿಲ್ಲದ ಸಂಪತ್ತನ್ನು ಬೇಡಿ, ಅವನು ಮಗುವಿನೊಡನೆ ಪರಿವಾರಜನರೊಂದಿಗೆ ಮಧ್ಯರಾತ್ರಿಯಲ್ಲಿ ತನ್ನ ಮನೆಗೆ ಹೊರಟನು.',
        '0.32': 'ಅತಿ ಭಯಂಕರವಾದ ಕಾಡಿನಲ್ಲಿ ರಾತ್ರಿ ಅವನೊಡನೆ ಹೋಗುತ್ತಿದ್ದವರಲ್ಲಿ ಒಬ್ಬನನ್ನು ಅಲ್ಲಿ ಸಂಚರಿಸುವ ಒಂದು ಗ್ರಹವು (ಭೂತವು) ಪೀಡಿಸಿತು; ಅವನು ರಕ್ತ ಕಾರುವುದನ್ನು ಕಂಡು ಯಾರೋ “ಆಹಾ! ಶಿಶುಪೀಡಕವಾದ ಇದು ಮಗುವನ್ನು ಬಿಟ್ಟು ಹೀಗೇಕೆ ಮಾಡಿತು?” ಎಂದರು.',
        '0.33': 'ಆ ಮಹಾಗ್ರಹವು ಒಬ್ಬ ಪುರುಷನನ್ನು ಆವೇಶಿಸಿ ಹೇಳಿತು: “ನಮ್ಮ ಸಂಚಾರದ ಸಮಯದಲ್ಲಿ ಬರುವವರೆಲ್ಲರನ್ನೂ, ಅವನ ಶಕ್ತಿಯ ರಕ್ಷಣೆಯಿಲ್ಲದಿದ್ದರೆ, ಕೊಲ್ಲಲು ನಾನು ಸಮರ್ಥ; ಆದರೆ ಲೋಕೇಶ್ವರನಾದ ಅವನು ನೋಡಲು ಮಾತ್ರ ಪುಟ್ಟ ಮಗು!”',
        '0.34': 'ಒಮ್ಮೆ ಹಾಲೂಡಿಸಿ ಮಗುವನ್ನು ತೃಪ್ತಿಪಡಿಸಿ, ಅಗಲಿಕೆಯನ್ನು ಸಹಿಸಲಾರದಿದ್ದರೂ ತಾಯಿ ಮನೆಯಿಂದ ಹೊರಗೆ ಹೋದಳು; ಭೀರುವಾದ ಅವಳು ವಿಶ್ವಪಾಲಕನನ್ನು ಪಾಲಿಸುವುದಕ್ಕಾಗಿ ತನ್ನ ಮಗಳನ್ನು ಬಿಟ್ಟುಹೋದಳು!',
        '0.35': 'ಅಳುತ್ತಿದ್ದ ಮಗುವನ್ನು ಸಮಾಧಾನಪಡಿಸುತ್ತಾ ಆ ಮುಗ್ಧ ಹುಡುಗಿಯು ತೊದಲು ಮಾತುಗಳಿಂದ ಓಲೈಸಿದಳು: “ಅಳಬೇಡ ಕಂದಾ, ಮುದ್ದು ಮುಖದವನೇ; ಅಮ್ಮ ನಿನಗೆ ಬೇಕಾದುದನ್ನು ಬೇಗನೆ ತರುತ್ತಾಳೆ.”',
        '0.36': 'ಮಗುವಿನ ಅಳು ಮತ್ತೆ ಮತ್ತೆ ಮುಂದುವರಿಯಲು, ತಾಯಿ ಬಹಳ ಹೊತ್ತಾದರೂ ಬಾರದಿರಲು, ಆ ಹುಡುಗಿಯು ಮಗುವನ್ನು ಎತ್ತಿಕೊಂಡು ತಾನೂ ಮತ್ತೆ ಮತ್ತೆ ತಾಯಿಯ ದಾರಿಯನ್ನು ನೋಡುತ್ತಿದ್ದಳು.',
        '0.37': 'ಏನು ಮಾಡಬೇಕೆಂದು ತೋಚದೆ, ನಿರ್ಧರಿಸಿ, ಅವಳು ಚೆನ್ನಾಗಿ ಬೆಂದ ಹುರುಳಿಯ ರಾಶಿಯನ್ನೇ ಅವನಿಗೆ ತಿನ್ನಿಸಿದಳು; ತಣ್ಣೀರನ್ನೂ ಕುಡಿಸುತ್ತಿದ್ದಳು — ಹುರುಳಿಯ ಉಷ್ಣರೋಗಕ್ಕೆ ತಾಯಿ ಬಹಳ ಹೆದರುತ್ತಿದ್ದಳು.',
        '0.38': '“ಅಯ್ಯೋ, ಮಗು ಬಾಯಾರಿ ಬಹಳ ಅಳುತ್ತಿರಬೇಕು; ಪರರ ಕೆಲಸದಲ್ಲಿ ತೊಡಗಿದ ದಯೆಯಿಲ್ಲದ ನನಗೆ ಧಿಕ್ಕಾರ!” ಎಂದು ಆತಂಕದಿಂದ ಮನೆಗೆ ಬಂದ ವಿಪ್ರಪತ್ನಿಯು ಪ್ರಸನ್ನನಾಗಿ ಹೊಟ್ಟೆ ತುಂಬಿದ ಮಗನನ್ನು ಕಂಡಳು.',
        '0.39': 'ಕೇಳಿ ನಡೆದುದೆಲ್ಲವನ್ನೂ ತಿಳಿದು, “ಯುವಕರಿಗೂ ಜೀರ್ಣಿಸಲು ಕಷ್ಟವಾದುದನ್ನು ಶಿಶು ತಿಂದಿದೆ” ಎಂದು ಚಿಂತಿಸಿ ಅವಳು ಮಗಳನ್ನು ಬಹಳ ಗದರಿಸಿದಳು — ಮೊದಲು ಹೆದರಿ, ನಂತರ ಕೋಪಗೊಂಡು, ಬಳಿಕ ಮನಸ್ಸಿನಲ್ಲಿ ಪಶ್ಚಾತ್ತಾಪಪಟ್ಟಳು.',
        '0.40': 'ಮಗನು ಮೊದಲಿನಂತೆಯೇ ಆರೋಗ್ಯದಿಂದಿರಲು ಅವನ ತಾಯಿ ಆಶ್ಚರ್ಯಪಟ್ಟಳು — ಸರ್ವಶಕ್ತನಾದ ಅವನು (ಹಾಲಾಹಲ) ವಿಷವನ್ನು ಕುಡಿದಾಗಲೂ ಅವನ ನಿಜವಾದ ತಾಯಿ, ತ್ರಿಲೋಕಜನನಿ ಲಕ್ಷ್ಮಿಯು ಆಶ್ಚರ್ಯಪಡಲಿಲ್ಲ.',
        '0.41': 'ತಾಯಿ ಮತ್ತೆ ಮತ್ತೆ ಎತ್ತಿಕೊಂಡು ಹಾಲೂಡಿಸುತ್ತಿದ್ದಳು; ತಂದೆ ಅವನನ್ನು ಹಿಡಿದು ಕ್ಷೇಮಕ್ಕಾಗಿ ಜಪಿಸುತ್ತಿದ್ದನು; ಇತರರೂ ಮುದ್ದಿಸುತ್ತಿದ್ದರು; ಆದರೆ ಎಲ್ಲರೂ ಅವನ ಮುಗುಳ್ನಗೆಯ ಮುಖವೆಂಬ ರಸಾಯನಕ್ಕಾಗಿ ಹಾತೊರೆಯುತ್ತಿದ್ದರು.',
        '0.42': 'ಮೊದಲು ಅಸ್ಪಷ್ಟವಾಗಿದ್ದ ಅವನ ಬಾಯಿನ ಮಾತು ನಾಚಿಕೆಯಿಂದೆಂಬಂತೆ ಆಟವಾಡಿತು — ಲೋಕಪೂಜಿತವಾದ, ದೇವತೆಗಳಿಂದಲೂ ಸಜ್ಜನರಿಂದಲೂ ಆದರದಿಂದ ಪಾಲಿಸಲ್ಪಟ್ಟ, ಪದಗಳಿಂದ (ಹೆಜ್ಜೆಗಳಿಂದ) ಭಾರತೀದೇವಿಯಂತೆಯೇ ಶೋಭಿಸುವ ಮಾತು.',
        '0.43': 'ಅವನು ಅಂಬೆಗಾಲಿಟ್ಟನು, ಆಮೇಲೆ ತಾನೇ ನಿಂತನು, ಬಳಿಕ ಅಭ್ಯಾಸದಿಂದ ಕ್ರಮವಾಗಿ ನಡೆದನು; ಆಹಾ! ಜಗತ್ತಿನ ಎಲ್ಲ ಚಲನೆಯೂ ಯಾರ ಅನುಗ್ರಹದಿಂದ ನಡೆಯುತ್ತದೆಯೋ, ಆ ವಾಯುವಿಗೆ ಇದೆಲ್ಲವೂ ಕೇವಲ ಅಭಿನಯ.',
        '0.44': 'ಒಮ್ಮೆ ಬೆಳಿಗ್ಗೆ ದನದ ಹಟ್ಟಿಯಿಂದ ಹೊರಡುತ್ತಿದ್ದ ತನ್ನ ಪ್ರಿಯ ಎತ್ತಿನ ಬಾಲದ ತುದಿಯನ್ನು ಹಿಡಿದು, ಮನೆಯವರಿಗೆ ಕಾಣದಂತೆ ಅವನು ಬೇರೆ ಬೇರೆ ಕಾಡುಗಳಲ್ಲಿ ಹುಲ್ಲು ಮೇಯುತ್ತಿದ್ದ ಅದರೊಡನೆ ಇದ್ದಕ್ಕಿದ್ದಂತೆ ಹೊರಟುಹೋದನು.',
        '0.45': 'ಎತ್ತರವಾದ ಹೊಳೆಯುವ ಕೊಂಬುಗಳುಳ್ಳ, ದೊಡ್ಡ ದೇಹದ, ಗೊರಸುಗಳಿಂದ ನೆಲವನ್ನು ಆವರಿಸಿದ ಆ ಎತ್ತಿನ ದೇಹದ ಒಂದು ಭಾಗವನ್ನು ಹಿಡಿದ ಆ ಮಗು ಉದಯಪರ್ವತದ ಮೇಲಿನ ಬಾಲಸೂರ್ಯನಂತೆ ಶೋಭಿಸಿತು.',
        '0.46': '“ಮಗು ಆಟವಾಡುತ್ತಿದೆಯೋ? ಬೇರೆ ಮನೆಗೆ ಹೋಗಿದೆಯೋ? ಸ್ವಭಾವತಃ ಸ್ವತಂತ್ರನಾದ ಅವನು ಬಾವಿಗೆ ಬಿದ್ದನೋ?” ಎಂದು ಚಿಂತಿಸಿ ಮನೆಯವರು ಮತ್ತೆ ಮತ್ತೆ ಹುಡುಕಿ, ಅಯ್ಯೋ, ಮಗನನ್ನು ಕಾಣದೆ ಹೃದಯದಲ್ಲಿ ಸಂಕಟಪಟ್ಟರು.',
        '0.47': 'ಮಗುವು ಎತ್ತನ್ನು ಹಿಡಿದುಕೊಂಡಿದ್ದುದರ ಬಗ್ಗೆ ಕಾಡಿನವರು ಹೇಳಿದ ಮಾತು ನಂಬಲರ್ಹವಾಯಿತು; ಏಕೆಂದರೆ ಸಂಜೆ ಒಂದು ವರ್ಷದ ಆ ಮಗು ಎಳೆಯ ಎತ್ತನ್ನು ಹಿಡಿದುಕೊಂಡು ಬರುತ್ತಿರುವುದನ್ನು ಜನರು ಕಂಡರು.',
        '0.48': 'ದರಿದ್ರನು ಬಯಸಿದ್ದನ್ನು ಕೊಡುವ ಚಿಂತಾಮಣಿಯನ್ನು ಪಡೆದಂತೆ, ಮುಮುಕ್ಷುವು ವಿಷ್ಣುಪರವಾದ ಜ್ಞಾನಮಾರ್ಗವನ್ನು ಪಡೆದಂತೆ, ಕಳೆದುಹೋದ ಮಗನನ್ನು ಮರಳಿ ಪಡೆದ ಮನೆಯವರು ಅದನ್ನು ಆ ಸ್ವಾಮಿಯ ಅನುಗ್ರಹವೆಂದೇ ಭಾವಿಸಿದರು.',
        '0.49': 'ಒಮ್ಮೆ ಆಟ ಮುಗಿದ ಮೇಲೆ ಮಗನು ಊಟಕ್ಕೆ ಬರಲು ಒತ್ತಾಯಿಸಿದಾಗ, ತಂದೆಯು ಮಗನ ಮುಖಚಂದ್ರನನ್ನು ನೋಡಿ ಮೆಲ್ಲನೆ “ಎತ್ತನ್ನು ಮಾರಿದ ಈ ಸಾಲಗಾರನು ನಮ್ಮನ್ನು ತಡೆದಿದ್ದಾನೆ” ಎಂದನು.',
        '0.50': 'ಆಗ ಮಗುವು ಮುಗುಳ್ನಕ್ಕು ತನ್ನ ಕೋಮಲವಾದ ಲೀಲಾಹಸ್ತದಿಂದ ಅವನು ಬಯಸಿದ ನಾಣ್ಯಗಳ ಬದಲಿಗೆ ಕೆಲವು ಬೀಜಗಳನ್ನು ಬೇಗನೆ ಕೊಟ್ಟಿತು; ಸಾಲಗಾರನು ಅವನ್ನು ಬಹುಮಾನದಿಂದ ಸ್ವೀಕರಿಸಿದನು.',
        '0.51': '“ನಿನ್ನ ಮಗನಿಂದ ಪಡೆದಿದ್ದೇನೆ” ಎಂದು ಹೇಳಿ, ಮುಂದೆ ಆ ವಿಪ್ರಶ್ರೇಷ್ಠನು ತನ್ನ ಧನವನ್ನು ಹಿಂದಿರುಗಿಸಲು ಬಯಸಿದಾಗಲೂ ಅವನು ಸ್ವೀಕರಿಸಲಿಲ್ಲ; ಬೀಜಗಳ ನೆಪದಲ್ಲಿ ಹೊಸ ಶಿಶುರೂಪದ ಅತಿಮಾನುಷನಿಂದ ಅವನು ವಿಶಿಷ್ಟವಾದ ಪುರುಷಾರ್ಥವನ್ನೇ ಪಡೆದನು — ಆಶ್ಚರ್ಯ!',
        '0.52': 'ವಿವಿಧ ಲೀಲೆಗಳನ್ನಾಡುವ, ಪ್ರಾಣದೇವತೆಯ ನಿಜವಾದ ಅಂಶವಾದ, “ವಾಸುದೇವ” ಎಂಬ ಪವಿತ್ರ ಹೆಸರುಳ್ಳ ಆ ಮಗುವನ್ನು ಜನರು ಸಾಕ್ಷಾತ್ ವಾಸುದೇವನೆಂಬಂತೆ ಅಭಿನಂದಿಸಿದರು.',
        '0.53': 'ಹೀಗೆ ವಿಷ್ಣುದಾಸನು ಮರೆಯಾಗಿದ್ದರೂ ಭೂಮಿಯಲ್ಲಿ ವಿಹರಿಸುತ್ತಿರಲು ಸಜ್ಜನರ ಮನಸ್ಸು ಆನಂದದಿಂದ ತುಂಬಿತು; ಮೋಡಗಳ ಸಾಲಿನಲ್ಲಿ ಮರೆಯಾಗಿದ್ದರೂ ಸೂರ್ಯನು ಉದಯಿಸಿದಾಗ ಜನರ ಕಣ್ಣುಗಳೆಂಬ ಕಮಲಗಳು ಅರಳುತ್ತವಲ್ಲವೇ?',
        '0.54': 'ಹೀಗೆ ಕವಿಕುಲತಿಲಕರಾದ ತ್ರಿವಿಕ್ರಮಪಂಡಿತಾಚಾರ್ಯರ ಪುತ್ರ ನಾರಾಯಣಪಂಡಿತಾಚಾರ್ಯರು ರಚಿಸಿದ “ಆನಂದ” ಎಂಬ ಅಂಕಿತವುಳ್ಳ ಶ್ರೀಮತ್ಸುಮಧ್ವವಿಜಯ ಮಹಾಕಾವ್ಯದ ಎರಡನೆಯ ಸರ್ಗ ಮುಗಿಯಿತು.',
      },
    },
    'sumadhva-vijaya-03': {
      verses: {
        '0.0': 'ಒಮ್ಮೆ, ಸುಂದರನಾದ ಮಗನ ಮುಗುಳ್ನಗೆಯ ಮುಖಚಂದ್ರನನ್ನು ನೋಡುತ್ತಿದ್ದ ಜನರಿಗೆ ಪ್ರಿಯರಾದ ಆ ದಂಪತಿಗಳು ತಮ್ಮ ಬಂಧುಗಳ ಸಂತೋಷಕ್ಕಾಗಿ ಸ್ವಜನರೊಡನೆ ಸಂತೋಷದಿಂದ ಉತ್ಸವಕ್ಕೆ ಹೋದರು.',
        '0.1': 'ಬಂಧುಗಳ ಬರುವಿಕೆ-ಹೋಗುವಿಕೆ, ಭೇಟಿ, ಪರಸ್ಪರ ಸತ್ಕಾರಗಳ ಗಡಿಬಿಡಿಯಲ್ಲಿ ತಾಯಿಗೆ ತಿಳಿಯದಂತೆ ಆ ಬಾಲಕನು ಆ ಗದ್ದಲದ ಮನೆಯಿಂದ ಕೆಲವು ದಾರಿಹೋಕರೊಡನೆ ಹೊರಟುಹೋದನು.',
        '0.2': '“ಮಗು, ಎಲ್ಲಿಗೆ ಹೋಗಬಯಸುತ್ತೀಯೆ? ಈಗ ನಿನ್ನವರನ್ನು ಬಿಟ್ಟು ಹೋಗುವುದು ಸರಿಯಲ್ಲ” ಎಂದು ದಾರಿಹೋಕರು ಹೇಳಲು, ನಡೆಯುತ್ತಲೇ ಆ ಪ್ರಭುವು ಶಾಂತವಾದ ಮುಗುಳ್ನಗೆಯ ಉತ್ತರವನ್ನಿತ್ತನು.',
        '0.3': 'ಬೇಗನೆ ಹೋಗಿ ಅಲ್ಲಿನ ವನದೇವತೆಯ ಗುಡಿಯಲ್ಲಿ ರಮಾಪತಿಗೆ ನಮಸ್ಕರಿಸಿದನು; ಅಲ್ಲಿಂದ ಮುಂದೆ ಹೋಗಿ “ಕಿರು ತೆಂಗು” ಎಂಬ ಹೆಸರಿನ ಸ್ಥಳದ ದೇವಾಲಯದಲ್ಲಿರುವ ಅವನಿಗೂ ನಮಸ್ಕರಿಸಿದನು.',
        '0.4': 'ಪದ್ಮನಾಭನ ದರ್ಶನದ ಸಂತೋಷದಿಂದ ಅರಳಿ ಹೊಳೆಯುವ ಕಣ್ಣುಗಳುಳ್ಳ, ಜನರ ಮನಸ್ಸು ಕಣ್ಣುಗಳೆಂಬ ಕಮಲಗಳಿಗೆ ಸೂರ್ಯನಾದ ಅವನು ರಜತಪೀಠಪುರಕ್ಕೆ (ಉಡುಪಿಗೆ) ಹೋದನು.',
        '0.5': '“ಚೆನ್ನಾಗಿ ಮಾಡಿದ ಈ ಹರಿನಮಸ್ಕಾರಗಳು ಅನೇಕ ಅಶ್ವಮೇಧಗಳನ್ನು ಮೀರಿಸುತ್ತವೆ” ಎಂಬಂತೆ, ದೇವತೆಗಳೂ ಬ್ರಾಹ್ಮಣಸಮೂಹಗಳೂ ವಿಸ್ಮಯದಿಂದ ನೋಡುತ್ತಿರಲು ಅವನು ನಮಸ್ಕರಿಸಿದನು.',
        '0.6': 'ಅವನು ಹರಿಗೆ ನಮಿಸದ, ಅವನನ್ನು ಕಾಣದ, ವಂದಿಸದ ಕ್ಷಣವೇ ಇಲ್ಲ; ಆದರೂ ಇಲ್ಲಿ ವಿಶೇಷವಾಗಿ ಹಾಗೆ ಮಾಡಿ ಅವನು ಸಜ್ಜನರಿಗೆ ಬೋಧಿಸಿದನು.',
        '0.7': 'ಮಗನನ್ನು ಕಾಣದೆ ಪುತ್ರವತ್ಸಲನಾದ ಆ ವಿಪ್ರಶ್ರೇಷ್ಠನು ಹುಡುಕತೊಡಗಿದನು; ದಾರಿ ದಾರಿಯಲ್ಲೂ ಅವನ ಹೆಜ್ಜೆಯನ್ನನುಸರಿಸಿ ಬೇಗನೆ ಹೋಗುತ್ತಾ ಅವನು ಹೋದ ದಾರಿಯನ್ನು ಜನರನ್ನು ಮತ್ತೆ ಮತ್ತೆ ಕೇಳಿದನು.',
        '0.8': 'ಜನರು (ಮತ್ತು ಸದಾ ಚಲಿಸುವ ಗಾಳಿ) ತೋರಿಸಿದ ದಾರಿಯಲ್ಲಿ ಹೆಜ್ಜೆಹೆಜ್ಜೆಗೂ ತೀವ್ರ ಹಂಬಲದಿಂದ ಹೋಗುತ್ತಿದ್ದ ಆ ವಿಪ್ರನೆಂಬ ಮಹಾಭ್ರಮರವು ಮಗನ ಮನೋಹರವಾದ ಮುಗುಳ್ನಗೆಯ ಮುಖಕಮಲವನ್ನು ಪಡೆಯಿತು.',
        '0.9': 'ಅಗಲಿಕೆಯ ದುಃಖದಿಂದ ಕಣ್ಣುಗಳಲ್ಲಿ ಉಕ್ಕಬಂದ ಕಣ್ಣೀರನ್ನು ಅವನು ಹಿಂದೆಯೇ ತಡೆದಿದ್ದನು; ಈಗ ಸಂತೋಷದಿಂದ ಉಕ್ಕಿದ ಕಣ್ಣೀರನ್ನೂ ತಡೆದು ಆ ತಂದೆಯು ಹೀಗೆ ಹೇಳಿದನು.',
        '0.10': '“ಮಗನೇ, ನಿಜ ಹೇಳು; ನೀನು ಈಗ ಇಲ್ಲಿಗೆ ಬಂದಿದ್ದೀಯೆ; ಆದರೆ ಸ್ವಜನರಿಲ್ಲದ ನಿನಗೆ ಈ ಬಹಳ ದೀರ್ಘವಾದ ದಾರಿಯಲ್ಲಿ ಜೊತೆಗಾರನು ಯಾರು, ಕಂದಾ?”',
        '0.11': 'ತಂದೆಯ ಮಾತನ್ನು ಕೇಳಿ ಕಮಲನೇತ್ರನು ಮಧುರವಾಗಿ ಉತ್ತರಿಸಿದನು: “ನನ್ನ ಸ್ಥಾನಕ್ಕೆ ಬರುವಾಗಲೂ ಅಲ್ಲಿಂದ ಮುಂದೆ ಹೋಗುವಾಗಲೂ ವನದ ದೇವರೇ ನನ್ನ ಸ್ನೇಹಿತ.”',
        '0.12': '“ಆ ಇನ್ನೊಂದು ದೇವಾಲಯದಿಂದ ನಮಸ್ಕರಿಸಿ ಬಂದಾಗ ಅಲ್ಲಿನ ಹರಿಯೇ ಸ್ನೇಹಿತ. ಇಲ್ಲಿಯೂ ಪೂರ್ವದಿಕ್ಕಿನ ದೇವಾಲಯದ ದೇವರಿಗೂ, ಬಳಿಕ ಅಧೀಶ್ವರನಿಗೂ ನಮಸ್ಕರಿಸಿದೆನು.”',
        '0.13': '“ಆಮೇಲೆ ಅವನೊಡನೆ ಬಂದು ಇಲ್ಲಿರುವ ಭಗವಂತನಿಗೆ ನಮಸ್ಕರಿಸಿದೆನು.” ಎಂದು ಹೇಳಿ ಆ ಮಗು ವಿಸ್ಮಿತರಾದ ಸಭಿಕರಿಂದ ಸನ್ಮಾನಿತನಾಗಿ ಶೋಭಿಸಿತು.',
        '0.14': '“ಕರುಣಾಲಯನೇ, ಸ್ವಜನರಿಲ್ಲದೆ ವಿವಿಧ ಭೂತಗಳಿಂದ ಭಯಂಕರವಾದ ದಾರಿಯಲ್ಲಿ ಬಂದ, ನಿನ್ನ ಪಾದಗಳನ್ನು ಪ್ರೀತಿಸುವ, ಅಲ್ಪಪುಣ್ಯನಾದ ನನ್ನ ಈ ಮಗುವನ್ನು ಕಾಪಾಡು” ಎಂದು ವಿಪ್ರನು ನಮಸ್ಕರಿಸಿದನು.',
        '0.15': 'ಮಗನನ್ನು ಅಪ್ಪಿಕೊಂಡು ತಪೋನಿಧಿಯಾದ ಅವನು ಪತ್ನಿಯೊಡನೆ ಮನೆಗೆ ಹೋದನು; ಆ ಬಾಲಸೂರ್ಯನು ಉದಯಿಸುತ್ತಿರಲು ಸಜ್ಜನರ ಮುಖಕಮಲಗಳು ಮುಗುಳ್ನಕ್ಕವು.',
        '0.16': 'ಶ್ರೇಷ್ಠ ವಿಮಾನವುಳ್ಳ ಬೆಟ್ಟದಲ್ಲಿ ಚಂಡಿಕೆಯೇ (ದುರ್ಗೆಯೇ) ತಾಯಿಯಾಗಿ ಆ ಮಗುವನ್ನು ಮುದ್ದಿಸಿದಳು; ಇಲ್ಲದಿದ್ದರೆ ಸಹಾಯಕರಿಲ್ಲದ ಅವನು ಸಂತುಷ್ಟನಾಗಿ ಅಲ್ಲಿ ಅಷ್ಟು ಹೊತ್ತು ಹೇಗೆ ಇರುತ್ತಿದ್ದನು?',
        '0.17': 'ಸಕಲಶಬ್ದಮಯಿಯಾದ ಸರಸ್ವತಿಯೇ ಯಾರಿಗೆ ಸದಾ ತಾನಾಗಿ ನಮಿಸುತ್ತಾಳೋ, ಆ ಮಗನಿಗೆ ಒಮ್ಮೆ ಆ ವಿಪ್ರಶ್ರೇಷ್ಠನು ಅಕ್ಷರಮಾಲೆಯನ್ನು ಪರಿಚಯಿಸತೊಡಗಿದನು.',
        '0.18': '“ಅಪ್ಪಾ, ಈ ಅಕ್ಷರಸಾಲನ್ನು ನಿನ್ನೆಯೇ ಬರೆದಾಯಿತಲ್ಲ, ಮತ್ತೆ ಏಕೆ ಬರೆಯಬೇಕು?” ಎಂಬ, ತನ್ನ ಪ್ರತಿಭೆಯನ್ನು ತೋರಿಸುವ ಆ ಹರಿದಾಸನ ಮಾತು ತಂದೆಯನ್ನು ಆನಂದಪಡಿಸಿತು.',
        '0.19': '“ಈ ಮಗು ಪ್ರತಿಭೆಯ ಸಮುದ್ರ; ಜನರ ಕಣ್ಣು ಮಾತುಗಳ ದೃಷ್ಟಿದೋಷ ಇವನಿಗೆ ತಾಗದಿರಲಿ” ಎಂದು ಅವನು ತನ್ನ ಮಗನಿಗೆ ಏಕಾಂತಸ್ಥಳದಲ್ಲಿ ಕಲಿಸಿದನು.',
        '0.20': 'ಒಮ್ಮೆ ಉತ್ಸವಕ್ಕೆ ಹೋಗುತ್ತಿದ್ದ ಸ್ವಜನರ ಒತ್ತಾಯದಿಂದ, ತಾಯಿಯೊಡನೆ, ಸುಂದರ ವಾಚನದಿಂದ ಶೋಭಿಸುವ ವಾಕ್ಶ್ರೀಯುಳ್ಳ ಆ ಪ್ರಭುವು ಘೃತವಲ್ಲಿಗೆ (ನೆಯ್ಯಂಪಳ್ಳಿಗೆ) ಹೋದನು.',
        '0.21': 'ಅಲ್ಲಿ ಮಹಾಸಭೆಯಿಂದ ಸುತ್ತುವರಿಯಲ್ಪಟ್ಟು ಪುರಾಣಕಥೆಯನ್ನು ಹೇಳುತ್ತಿದ್ದ ಧೌತಪಟನ ಮಗನಾದ ಶಿವ ಎಂಬುವನನ್ನು ಬಾಲರೂಪದ ವಿಶಾಲಬುದ್ಧಿಯ ಅವನು ಕಂಡನು.',
        '0.22': 'ವಿಚಾರಕುಶಲನಾದ ಅವನು ಜನರ ನಡುವೆ ಮೆಲ್ಲನೆ ಮುಗುಳ್ನಗುತ್ತಾ ಈ ಶುದ್ಧವಾದ ಮಾತನ್ನಾಡಿದನು: “ಕಥಕನೇ, ನೀನು ಮಹಾತ್ಮರ ಅಭಿಪ್ರಾಯಕ್ಕಿಂತ ಬೇರೆಯಾಗಿ ಹೇಳಿದ್ದೀಯೆ.”',
        '0.23': 'ವಾಸುದೇವನೆಂಬ ಹೆಸರಿನ ಅವನು ಮಾತನಾಡಿದ ಮೇಲೆ ಜನರು ಶಿವನನ್ನು ಲೆಕ್ಕಿಸಲಿಲ್ಲ; ಸಿಂಹದ ಮರಿ ಗರ್ಜಿಸುತ್ತಿರುವಾಗ ಗದ್ದಲದ ನರಿಯನ್ನು ಯಾರು ಬಯಸುತ್ತಾರೆ?',
        '0.24': '“ಹಾಗಾದರೆ ನೀನೇ ಕಥೆ ಹೇಳು” ಎಂದು ಜನರು ಹೇಳಲು ಅವನು ಉಚಿತವಾದ ಅರ್ಥವನ್ನು ಹೇಳಿದನು; ವಿಸ್ಮಿತರಾದ ಜನರೂ ವಿಜಯದ ಅಂಕುರವನ್ನು ಪೂಜಿಸುವ ದೇವತೆಗಳೂ ಅವನನ್ನು ಮುದ್ದಿಸಿದರು.',
        '0.25': 'ತಾಯಿಯೊಡನೆ ಮನೆಗೆ ಬಂದು ಅವನು ತಂದೆಗೆ ಆ ಸುದ್ದಿಯನ್ನು ತಿಳಿಸಿ, “ಅಪ್ಪಾ ಹೇಳು, ಕಥಕನಾದ ಶಿವನ ಮಾತು ತಪ್ಪೋ, ನನ್ನದೋ?” ಎಂದು ಕೇಳಿದನು.',
        '0.26': '“ಮಗನೇ, ನೀನು ಹೇಳಿದುದು ಸರಿ” ಎಂದು ಹೇಳಿ ಅವನು ವಿಸ್ಮಯದಿಂದ ಹೀಗೆ ಯೋಚಿಸಿದನು: “ನನ್ನ ಮಗುವಿನ ಈ ಪಾಂಡಿತ್ಯವು ಸಹಜವಾದುದು; ನನ್ನ ಸ್ವಾಮಿಯ ದಯೆಯಿಂದ ಹುಟ್ಟಿದುದು.”',
        '0.27': 'ಒಮ್ಮೆ ಕಥಕರಲ್ಲಿ ಶ್ರೇಷ್ಠನಾದ ತನ್ನ ತಂದೆಯು ಜನಸಮೂಹದ ಮಧ್ಯೆ ಕಥೆ ಹೇಳುತ್ತಿದ್ದಾಗ, ಎಲ್ಲರ ಕಣ್ಣು ಮನಸ್ಸುಗಳಿಗೆ ಉತ್ಸವವಾದ ಆ ಚತುರಬುದ್ಧಿಯು ಅವನನ್ನು ವಿವರಿಸುವಂತೆ ಮಾಡಿದನು.',
        '0.28': 'ವಿವಿಧ ವೃಕ್ಷಗಳನ್ನು ವರ್ಣಿಸುವಾಗ “ಲಿಕುಚ” ಎಂಬುದರ ಅರ್ಥವನ್ನು ಹೇಳದೆ ಮುಂದೆ ಹೋಗಲು, “ಅಪ್ಪಾ, ಅದರ ಅರ್ಥವನ್ನು ಹೇಳದೆ ಏಕೆ ಮುಂದುವರಿಸುತ್ತೀಯೆ?” ಎಂದು ಅವನು ಮೆಲ್ಲನೆ ಕೇಳಿದನು.',
        '0.29': 'ತಂದೆ ಉತ್ತರಿಸದಿರಲು, ಅಲ್ಲಿನ ಜನರೂ ತಿಳಿಯಲು ಬಯಸಲು, ಒತ್ತಾಯಿಸಲ್ಪಟ್ಟ ಅವನು ಅದರ ಅರ್ಥವನ್ನು ಹೇಳಿ ಸಭೆಯಿಂದ ಅಸಮಾನವಾದ ಸನ್ಮಾನವನ್ನು ಪಡೆದನು.',
        '0.30': 'ಹೀಗೆ ಅನೇಕ ಸುಂದರ ಚರಿತ್ರೆಗಳಿಂದ ಲೋಕಕ್ಕೆಲ್ಲ ಕುತೂಹಲವನ್ನುಂಟುಮಾಡುತ್ತಾ ಉಚಿತ ವಯಸ್ಸಿಗೆ ಬಂದ ಅವನಿಗೆ ಉಪನಯನ ಮಾಡಲು ಆ ವಿಪ್ರಶ್ರೇಷ್ಠನು ಮನಸ್ಸು ಮಾಡಿದನು.',
        '0.31': 'ಉಚಿತ ಗ್ರಹಯೋಗಗಳಿಂದ ಕೂಡಿದ ದೋಷರಹಿತ ಮುಹೂರ್ತವನ್ನು ನಿಶ್ಚಯಿಸಿ, ಪ್ರೀತಿಯ ಬಂಧುಗಳೊಡನೆ ಅವನು ಬ್ರಾಹ್ಮಣಕುಲಗಳಿಂದ ತುಂಬಿದ ಉತ್ಸವವನ್ನು ನಡೆಸಿದನು.',
        '0.32': 'ವಿವಿಧ ವೇದಗಳ ರೂಪದಲ್ಲಿ ಅವನ ಮುಖವೆಂಬ ರಂಗದಲ್ಲಿ ಬಹುಕಾಲ ವಿಹರಿಸಲು ಬಯಸುತ್ತಿದ್ದ ದೇವಾಂಗನೆಯರು ತಮ್ಮ ಪತಿಗಳೊಡನೆ ಆಕಾಶದಿಂದ ಆ ಉತ್ಸವವನ್ನು ಅಭಿನಂದಿಸಿದರು.',
        '0.33': 'ಉಜ್ಜ್ವಲಬುದ್ಧಿಯುಳ್ಳ ಅವನು ಉಚಿತ ಸಾಧನಗಳಿಂದ ಸತ್ಕ್ರಿಯೆಗಳಿಂದ ಅಗ್ನಿಯನ್ನು ಉಜ್ಜ್ವಲಿಸಿ, ಅಲಂಕೃತನಾದ, ಕ್ಷೇಮವಾಗಿರುವ, ಚೌಲಸಂಸ್ಕಾರವಾದ ಮಗನಿಗೆ ಉಪನಯನ ಮಾಡಿದನು.',
        '0.34': '“ಅಗ್ನಿಯನ್ನೂ ಗುರುವನ್ನೂ ಸೇವಿಸು, ವ್ರತಗಳನ್ನು ಆಚರಿಸು, ಸದಾಚಾರಿಯಾಗು, ಸತ್ಶಾಸ್ತ್ರಗಳನ್ನು ಚೆನ್ನಾಗಿ ಓದು” ಎಂದು ತ್ರಿಜಗದ್ಗುರುವಿಗೆ ತಂದೆ ಬೋಧಿಸುತ್ತಿರಲು ಸಾಕ್ಷಿಗಳಾಗಿದ್ದ ದೇವತೆಗಳು ಬಹಿರಂಗವಾಗಿ ನಕ್ಕರು.',
        '0.35': 'ಕುಮಾರಸ್ವಾಮಿಯ ಗುಣಗಳನ್ನೂ ಮೀರಿಸಿದ, ಸುಕುಮಾರನಾದ, ಸಹಜವಾಗಿಯೇ ಉಚಿತಾಚಾರದಲ್ಲಿ ಚತುರನಾದ ತನ್ನ ಮಗನನ್ನು ನೋಡಿ ಆ ವಿಪ್ರನು ನಿರಂತರವಾಗಿ ಕಲಿಸುತ್ತಾ ಸಂತೋಷಪಟ್ಟನು.',
        '0.36': 'ದರಿದ್ರನಂತೆ ತುಂಡುಬಟ್ಟೆಯನ್ನುಟ್ಟು, ತನ್ನ ವೈಭವಕ್ಕೆ ತಕ್ಕದಲ್ಲದ ಕಾಲ್ನಡಿಗೆ ಮೊದಲಾದುದನ್ನು ಮಾಡುತ್ತಾ — ಆಹಾ! ಭುವನಭರ್ತನ ಈ ಆತ್ಮಗೋಪನೆಯು ದೇವಸಭೆಗಳಲ್ಲಿ ಕುತೂಹಲವನ್ನುಂಟುಮಾಡಿತು.',
        '0.37': 'ನಿರಂತರವಾದ ವಿಷದ ಉಷ್ಣದಿಂದ ಎಲ್ಲ ಜನರನ್ನೂ ಕಳವಳಗೊಳಿಸುತ್ತಾ ಸಂಚರಿಸುತ್ತಿದ್ದ ಸರ್ಪರೂಪಿ ಅಸುರನೊಬ್ಬನು ಒಮ್ಮೆ ಅವನನ್ನು ಕೊಲ್ಲಬಯಸಿ ಅಶಾಂತನಾಗಿ ಹತ್ತಿರ ಬಂದನು.',
        '0.38': 'ಬೇಗನೆ ಹೆಡೆಯನ್ನು ಎತ್ತಿ ಹರಡಿ ಅವನು ಕಚ್ಚಿದರೂ ಆ ಬಾಲಕನಿಗೆ ಗಾಯವಾಗಲಿಲ್ಲ; ಪ್ರಭುವಿನ ಕೆಂಪಾದ ಸುಂದರ ಕಾಲ್ಬೆರಳುಗಳ ಲೀಲೆಯಿಂದ ಜಜ್ಜಲ್ಪಟ್ಟ ದೇಹದ ಆ ಸರ್ಪವು ಒದ್ದಾಡಿ ಬಿದ್ದಿತು.',
        '0.39': 'ಗರುಡನ ಕೊಕ್ಕಿಗೆ ಸಿಕ್ಕಿದಂತೆ ಆ ವಿಪ್ರಕುಮಾರನ ಪಾದಕ್ಕೆ ಸಿಕ್ಕಿ ಅವನು ಸತ್ತನು; ಮಹಾತ್ಮರಿಗೆ ತಕ್ಕ ಈ ಚರಿತ್ರೆಯನ್ನು ದೇವತೆಗಳು ಮನಸ್ಸಿನಲ್ಲೇ ಪೂಜಿಸಿದರು.',
        '0.40': 'ರುದ್ರ, ಬೃಹಸ್ಪತಿ, ಇಂದ್ರ ಮೊದಲಾದ ದೇವಶ್ರೇಷ್ಠರು ಯಾರ ಪಾದಧೂಳಿಯನ್ನು ಧರಿಸುತ್ತಾರೋ, ಆ ಮಾನವವೇಷಧಾರಿಯು ಬ್ರಾಹ್ಮಣ ಗುರುವಿನ ಪಾದಗಳಿಗೆ ನಮಸ್ಕರಿಸಿ ಅಧ್ಯಯನವನ್ನು ಆರಂಭಿಸಿದನು.',
        '0.41': 'ಸಕಲ ಕಲೆಗಳೊಡನೆ ಸಕಲ ವಿದ್ಯೆಯೂ ಅವನ ಅಂಗೈಯಲ್ಲಿ ಚೆಂಡಿನಂತೆ ಸದಾ ಇತ್ತು; ಗುರುವಿನ ಮುಂದೆ ಸಾಮಾನ್ಯ ಜನರನ್ನು ಅನುಕರಿಸುತ್ತಿದ್ದ ಅವನ ಮನಸ್ಸಿನಲ್ಲಿ ಅದು ಚಕ್ರಧಾರಿ ವಿಷ್ಣುವಿನೊಡನೆ ಹೊಳೆಯುತ್ತಿತ್ತು.',
        '0.42': 'ಅಧ್ಯಯನದ ಬಿಡುವಿನಲ್ಲಿ ಗುರುವಿನಿಂದ ದೂರದಲ್ಲಿ ತನಗಿಂತ ಕಿರಿಯರೂ ಹಿರಿಯರೂ ಆದ ಅನೇಕ ಚತುರ ವಟುಗಳಾದ ಸ್ನೇಹಿತರೊಡನೆ ಅವನು ಸುಖವಾಗಿ ಆಟವಾಡುತ್ತಿದ್ದನು.',
        '0.43': 'ಓಟದ ಗುರಿಯನ್ನು ಹೇಳಿದಾಗ ವೇಗವಾದ ಸ್ನೇಹಿತರಲ್ಲಿ ಅವನೇ ಮುಂದಿರುತ್ತಿದ್ದನು; ಅವನು ಪ್ರಯಾಸವಿಲ್ಲದೆ ಹಾಗೆ ಮಾಡಿದುದು ಆಶ್ಚರ್ಯವಲ್ಲ — ಮನೋವೇಗವನ್ನೂ ಗೆದ್ದ ವಾಯುವೇ ಅವನು.',
        '0.44': 'ಹಾರುವ ಶಕ್ತಿಯಲ್ಲಿ ಅವನು ಆಗ ಎಲ್ಲ ಜನರನ್ನು ಗೆದ್ದುದು ಮಾತ್ರವಲ್ಲ; ಹನುಮದ್ರೂಪದಲ್ಲಿ ಪ್ರಭುವಿನ ಆಜ್ಞೆಯನ್ನು ನೆರವೇರಿಸುವಾಗ ವಾಲಿಪುತ್ರ ಅಂಗದನೇ ಮೊದಲಾದವರನ್ನೂ ಗೆದ್ದಿದ್ದನು.',
        '0.45': 'ಜಲಕ್ರೀಡೆಯಲ್ಲಿ ಸೋತ ಸ್ನೇಹಿತರು ಸ್ಪರ್ಧೆಯಿಂದ ಎರಚಿದ ನೀರಿನಿಂದ ತೊಯ್ದ, ಕಣ್ಣು ಮಿಟುಕಿಸುತ್ತಿದ್ದ ಅವನ ಮುಖವು ಮುಗುಳ್ನಗೆಯ ಒಂದು ವಿಶೇಷ ಸೊಬಗನ್ನು ಹೊಂದಿತ್ತು.',
        '0.46': 'ಕುಸ್ತಿಯಾಟದಲ್ಲಿ ಒಟ್ಟಿಗೆ ಬಂದ ಬಲಿಷ್ಠ ಸ್ನೇಹಿತರನ್ನು ಅವನು ಮೆಲ್ಲನೆ ಕೆಡವುತ್ತಿದ್ದನು; ಒಟ್ಟಿಗೆ ನಿಜವಾಗಿ ಹೋರಾಟಕ್ಕಿಳಿದವರನ್ನು ಆ ವಿಪ್ರಕುಮಾರನು ನಗುತ್ತಾ ಪ್ರಯಾಸವಿಲ್ಲದೆ ಕೆಡವುತ್ತಿದ್ದನು.',
        '0.47': 'ಹಿಡಿಯುವುದು, ಅದುಮುವುದು, ಬಿಗಿಯಾಗಿ ಹಿಡಿಯುವುದು, ಭಾರವನ್ನೆತ್ತುವುದು ಮೊದಲಾದವುಗಳಲ್ಲಿ ಚತುರನಾದ ಅವನನ್ನು ಜನರು ಉಪಚಾರವಾಗಿ “ಭೀಮ” ಎಂದು ಕರೆದರು; ಅದು ನಿಜವಾಗಿಯೂ ಸತ್ಯವೇ.',
        '0.48': '“ಅವನು ಆಟವಾಡುತ್ತಾನೆ, ಸ್ಪಷ್ಟವಾಗಿ ಓದುವುದಿಲ್ಲ, ಮನೆಗೆ ತಡವಾಗಿ ಬರುತ್ತಾನೆ” ಎಂದು ಪೂಗವನ ವಂಶದ ಆ ವಿಪ್ರಗುರುವು ಆ ಜಗದ್ಗುರುವಿನ ವಿಷಯದಲ್ಲಿ ಸಂತುಷ್ಟನಾಗಿರಲಿಲ್ಲ.',
        '0.49': 'ಒಮ್ಮೆ ಅಧ್ಯಯನದ ಮಧ್ಯೆ ಬೇರೆ ಕಡೆ ಮನಸ್ಸಿಟ್ಟಂತಿದ್ದ ಅವನಿಗೆ ಕೋಪಗೊಂಡ ಗುರುವು ಹೇಳಿದನು: “ಶಠನೇ, ನೀನು ಓದುವುದಿಲ್ಲ; ಸ್ನೇಹಿತರೊಡನೆ ಸೇರಿ ನಿನ್ನ ಬುದ್ಧಿ ಯಾವಾಗಲೂ ಏಕೆ ಉದಾಸೀನವಾಗಿದೆ?”',
        '0.50': '“ಪಾದ ಪಾದವಾಗಿ ಮತ್ತೆ ಮತ್ತೆ ಹೇಳಿಸುವ ಪಾಠ ನನ್ನ ಮನಸ್ಸಿಗೆ ಹಿಡಿಸುವುದಿಲ್ಲ” ಎಂದು ಅವನು ಹೇಳಲು, “ಚತುರಮಾತಿನವನೇ, ಮುಂದಿನದನ್ನು ನಿನಗೆ ಇಷ್ಟಬಂದಂತೆ ಹೇಳು” ಎಂದನು ಆ ವಿಪ್ರ.',
        '0.51': 'ಸಕಲ ಲಕ್ಷಣಶಿಕ್ಷಣಕ್ಕೆ ಮೂಲವಾದ, ತಪ್ಪಿಲ್ಲದ ಅವನ ವೇದಪಠಣವು ಆ ಗುರುವಿಗೆ ಮಾತ್ರವಲ್ಲ, ದೇವತೆಗಳಿಗೂ ಕುತೂಹಲವನ್ನುಂಟುಮಾಡಿತು.',
        '0.52': 'ಒಮ್ಮೆ ನಿರ್ಜನವಾದ ಕಾಡಿನಲ್ಲಿ ಅವನು ತನ್ನ ಪ್ರಿಯಮಿತ್ರನ ಹುಟ್ಟಿನಿಂದಲೇ ಇದ್ದ ಅಸಹನೀಯವಾದ ತೀವ್ರ ತಲೆನೋವನ್ನು ಕಿವಿಯಲ್ಲಿ ಊದಿದ ಬಾಯಿಗಾಳಿಯಿಂದ ಶಮನಗೊಳಿಸಿದನು.',
        '0.53': 'ಒಮ್ಮೆ ಕೇಳಿದ ಉಪನಿಷತ್ತು ಅವನಿಗೆ ಕರಗತವಾದುದೂ, ಭಾಗವತವು ಸ್ಪಷ್ಟವಾದುದೂ ಆಶ್ಚರ್ಯವಲ್ಲ; ಎಂದೂ ಕೇಳದ ನೂರಾರು ಶ್ರುತಿಗಳನ್ನೂ ಅವನು ಪ್ರತಿಭೆಯಿಂದ ಅರಿತಿದ್ದನು.',
        '0.54': 'ಆಮೇಲೆ ಆ ಪ್ರಭುವು ಏಕಾಂತದಲ್ಲಿ ಐತರೇಯ ಉಪನಿಷತ್ತಿನ ಪಾಠದ ನೆಪದಲ್ಲಿ ಅದರ ಅರ್ಥಸಾರವನ್ನು ಹೇಳುತ್ತಾ, ಮೋಕ್ಷಬೀಜವಾದ ಗೋವಿಂದಭಕ್ತಿಯನ್ನು ಉಚಿತವಾದ ಗುರುದಕ್ಷಿಣೆಯಾಗಿ ಅಧ್ಯಾಪಕನಿಗೆ ಕೊಟ್ಟನು.',
        '0.55': '“ಸ್ವಾಮಿ, ದುಷ್ಟರನ್ನು ಬೇಗನೆ ಬಹಿರಂಗವಾಗಿ ನಿಗ್ರಹಿಸು, ನಿಗ್ರಹಿಸು; ನಿನ್ನವರನ್ನು ಸಂತೋಷಪಡಿಸುತ್ತಾ ವಿಷ್ಣುವಿನ ಗೂಢಗುಣಗಳನ್ನು ಹೇಳು, ಹೇಳು” ಎಂದು ಬೇಡುತ್ತಿದ್ದ ದೇವತೆಗಳಿಗೆ ಆನಂದವನ್ನುಂಟುಮಾಡುತ್ತಾ ತ್ರಿಭುವನಗುರುವು ತನ್ನ ಬ್ರಾಹ್ಮಣಗುರುವಿನ ಅನುಮತಿಯನ್ನು ಪಡೆದನು.',
        '0.56': 'ಹೀಗೆ ಕವಿಕುಲತಿಲಕರಾದ ತ್ರಿವಿಕ್ರಮಪಂಡಿತಾಚಾರ್ಯರ ಪುತ್ರ ನಾರಾಯಣಪಂಡಿತಾಚಾರ್ಯರು ರಚಿಸಿದ “ಆನಂದ” ಎಂಬ ಅಂಕಿತವುಳ್ಳ ಶ್ರೀಮತ್ಸುಮಧ್ವವಿಜಯ ಮಹಾಕಾವ್ಯದ ಮೂರನೆಯ ಸರ್ಗ ಮುಗಿಯಿತು.',
      },
    },
    'sumadhva-vijaya-04': {
      verses: {
        '0.0': 'ಆಮೇಲೆ ಸದಾಗಮಸ್ವರೂಪನಾದ ಆ ವಿಶಾರದನು ಸಜ್ಜನರ ಮೇಲಿನ ದಯಾಮೃತದಿಂದ ಆರ್ದ್ರವಾದ, ಅಸತ್ತನ್ನು ನಿರಾಕರಿಸಬಯಸುವ, ರಮಾಪತಿಗೆ ನೆಲೆಯಾದ ತನ್ನ ವಿಶಾಲಬುದ್ಧಿಯಿಂದ ಹೀಗೆ ಚಿಂತಿಸಿದನು.',
        '0.1': '“ಬೇರೆಯದರಲ್ಲಿ ಸಂಗವಿಲ್ಲದಿರುವುದರಿಂದಲೇ ಹರಿಯ ಗುಣಗಳಲ್ಲಿ ಸಂಗ ಉಂಟಾಗುತ್ತದೆ; ಜನರಿಗೆ ಶ್ರೇಷ್ಠರ ನಡತೆಯೇ ಪ್ರಮಾಣ; ಆದ್ದರಿಂದ ನಾನು ಪರಮಹಂಸಾಶ್ರಮವನ್ನು ಸ್ವೀಕರಿಸಿ ಅಸಂಗತ್ವವನ್ನು ಪ್ರಕಟಪಡಿಸುತ್ತೇನೆ.”',
        '0.2': '“ಇದಲ್ಲದೆ ವಿಷ್ಣುದ್ವೇಷಿಗಳ ವಿಷಯದಲ್ಲಿ ದಂಡವನ್ನು (ಶಿಕ್ಷೆಯನ್ನು) ಧರಿಸದಿರುವುದು ನನ್ನ ಪ್ರಭುವಿನ ಕಾರ್ಯಕ್ಕೆ ಶೋಭಿಸದು; ಹರಿಯ ತಂಗಿ ದುರ್ಗೆಯು ಶೀಘ್ರದಲ್ಲೇ ದುಷ್ಟರ ನಾಶಕ್ಕೆ ನೆರವಾಗುವಳು; ಆದ್ದರಿಂದ ನಾನು ಕೇವಲ ದಂಡಧಾರಿಯಲ್ಲ.”',
        '0.3': 'ಹೀಗೆ ಚಿಂತಿಸುತ್ತಾ ಅನಂತನನ್ನು ಧ್ಯಾನಿಸುವ, ಸಂಪೂರ್ಣ ಸಂನ್ಯಾಸದಲ್ಲಿ ದೃಢನಿಶ್ಚಯನಾದ ಅವನು ಅನುಮತಿಗಾಗಿ ಸರ್ವವ್ಯಾಪಿಯೂ ತನ್ನನ್ನೇ ಕೊಡುವವನೂ ಆದ ಹರಿಗೆ ನಮಸ್ಕರಿಸಿದನು.',
        '0.4': '“ನಿನ್ನವನಿಗೆ ಏಕೆ ನಮಿಸುತ್ತೀಯೆ?” ಎಂದು ಕೇಳಿದಾಗ “ನನ್ನ ಸ್ವಂತ ವಸ್ತುವಿಗೆ ನಮಿಸಿದೆನು” ಎಂದು ಹೇಳಿ, ಸಕಲಲೋಕಶಿಕ್ಷಕನಾದ ಜಗದ್ಗುರುವು ಆಗ ಗುರುವನ್ನು ಹುಡುಕುತ್ತಾ ಹೊರಟನು.',
        '0.5': 'ಭೂಮಿಯಲ್ಲಿ ಮಹಾವೈರಾಗ್ಯವನ್ನೇ ಆಭರಣವಾಗಿ ಹೊಂದಿದ ಒಬ್ಬ ಜಿತೇಂದ್ರಿಯ ಯತಿಯಿದ್ದನು; ಹೆಸರಿನಿಂದ ಮಾತ್ರವಲ್ಲ, ಅರ್ಥದಿಂದಲೂ ಶುದ್ಧನಾದ ಅವನನ್ನು ಜನರು “ಅಚ್ಯುತಪ್ರೇಕ್ಷ” ಎಂದು ಕರೆಯುತ್ತಿದ್ದರು.',
        '0.6': 'ಹಿಂದೆ ಪಾಂಡವರ ಆಲಯದಲ್ಲಿ ಕೃಷ್ಣೆಯ (ದ್ರೌಪದಿಯ) ಕೈಯಿಂದ ಶುದ್ಧವಾದ ಶ್ರೇಷ್ಠ ಅನ್ನವನ್ನು ಸೇವಿಸಿ ಶುದ್ಧಮನಸ್ಕನಾದ ಅವನು ಮಾಧುಕರ ವೃತ್ತಿಯಿಂದ ಕೆಲವು ವರ್ಷಗಳ ಕಾಲ ಸಂತೋಷದಿಂದ ಸಂಚರಿಸಿದ್ದನು.',
        '0.7': 'ಪರಂಪರೆಯಿಂದ ಬಂದ ಕುಶಾಸ್ತ್ರಾಭ್ಯಾಸವು ಆ ಯತಿಗೆ ಪಾಪವಾಗಲಿಲ್ಲ, ಏಕೆಂದರೆ ಕ್ರಮವಾಗಿ ಅವನಿಗೆ ಪಶ್ಚಾತ್ತಾಪ ಉಂಟಾಯಿತು — ಮುರಾರಿಯ ಪಾದಕಮಲಕ್ಕೆ ಬೇಡನು ಬಾಣ ಹೊಡೆದುದು ಅವನ ಮೇಲೆ ದೋಷವಾಗದಂತೆ.',
        '0.8': 'ತನ್ನ ಮರಣವು ಸಮೀಪಿಸಿದುದನ್ನು ತಿಳಿದ ಗುರುವು ಒಮ್ಮೆ ವಿನೀತನೂ ಉಪನಿಷತ್ತುಗಳಲ್ಲಿ ಪಂಡಿತನೂ ಸದಾ ತತ್ತ್ವವನ್ನು ತಿಳಿಯಬಯಸುವವನೂ ಆದ ಅವನಿಗೆ ಏಕಾಂತದಲ್ಲಿ ಈ ಮಾತನ್ನು ಹೇಳಿದನು.',
        '0.9': '“‘ಚೈತನ್ಯವು ಸ್ಪಷ್ಟವಾಗಿ ಬೆಳಗಿದಾಗ ನಾನೇ ಬ್ರಹ್ಮ, ನನಗಿಂತ ಬೇರೆ ಏನೂ ಇಲ್ಲ’ ಎಂದು ಮಾಯಾವಾದದಲ್ಲಿ ಪ್ರತಿಪಾದಿಸಿರುವುದು ಆಧಾರರಹಿತ; ಸುವ್ರತನೇ, ಅದನ್ನು ನಂಬಬೇಡ.”',
        '0.10': '“ಉಪಾಸನೆಗೆ ವಿಧಿಸಿರುವ ಈ ಆತ್ಮೈಕ್ಯವು ನನ್ನ ಗುರುವಿಗೂ ಅಪರೋಕ್ಷವಾಗಲಿಲ್ಲ; ಸೌಮ್ಯನೇ, ಹಿಂದಿನವರಿಗೂ ಎಲ್ಲಿಯೂ ಆಗಲಿಲ್ಲ; ಆದ್ದರಿಂದ ಜ್ಞಾನಕ್ಕಾಗಿ ಸಂತೋಷದಿಂದ ಮುಕುಂದನನ್ನು ಭಜಿಸು.”',
        '0.11': 'ಈ ಉಪದೇಶವನ್ನು ಮಾಡಿ ವಾಗ್ಮಿಯಾದ ತನ್ನ ಗುರುವು ಪರಲೋಕವನ್ನು ಸೇರಿದ ಮೇಲೆ, ಅವನು ಗುರುವಿನ ಮಾತನ್ನು ಮತ್ತೆ ಮತ್ತೆ ಆಲೋಚಿಸುತ್ತಾ ರೂಪ್ಯಪೀಠದಲ್ಲಿ ನೆಲೆಸಿರುವ ಇಂದಿರಾಪತಿಯನ್ನು ಸೇವಿಸಿದನು.',
        '0.12': 'ಪರತತ್ತ್ವವನ್ನು ತಿಳಿಯಬಯಸುವ ಆ ಸುಭಕ್ತನಿಂದ ಅಲ್ಲಿ ಸೇವಿಸಲ್ಪಟ್ಟ ಭಕ್ತವತ್ಸಲನು ಒಬ್ಬ ಪುರುಷನನ್ನು ಆವೇಶಿಸಿ “ಮುಂದೆ ಬರುವ ಶ್ರೇಷ್ಠ ಶಿಷ್ಯನಿಂದ ನನ್ನನ್ನು ತಿಳಿ” ಎಂದು ಅವನಿಗೆ ಹೇಳಿದನು.',
        '0.13': 'ಆ ಅನುಗ್ರಹವನ್ನು ಸಂತೋಷದಿಂದ ನಿರೀಕ್ಷಿಸುತ್ತಾ ಕಮಲನೇತ್ರನನ್ನು ಮತ್ತೆ ಮತ್ತೆ ಸೇವಿಸುತ್ತಿದ್ದ ಆ ಪ್ರಶಾಂತ ಯತಿಯ ಬಳಿಗೆ, ಕಾರಣಾರ್ಥವಾಗಿ ಮಾನವರೂಪವನ್ನು ಧರಿಸಿದ ಸಜ್ಜನರ ಗುರುವು ಬಂದನು.',
        '0.14': 'ವೈರಾಗ್ಯಶಾಲಿಯಾದ ತಮ್ಮ ಮಗನು ಯತೀಂದ್ರನ ಅನುಚರನಾಗಿ ಸಂನ್ಯಾಸದಲ್ಲಿ ಮನಸ್ಸಿಟ್ಟಿದ್ದಾನೆಂದು ಕೇಳಿ, ಅಗಲಿಕೆಯಿಂದ ಬಳಲಿದ ವಾತ್ಸಲ್ಯಮಯ ತಂದೆತಾಯಿಗಳು ರೂಪ್ಯಪೀಠದಲ್ಲಿದ್ದ ಅವನ ಬಳಿಗೆ ಬಂದರು.',
        '0.15': '“ಮಗನೇ, ವೃದ್ಧರೂ ಅನಾಥರೂ ಆದ ನಾವಿಬ್ಬರು ಬದುಕಿರುವವರೆಗೆ ನಿನಗೆ ಶ್ರೇಷ್ಠಾಶ್ರಮವು ಬೇಡ” ಎಂದು ಬೇಡುವ ಮಾತನ್ನಾಡಿ ಅವರು ಮಗನಿಗೆ ಪ್ರದಕ್ಷಿಣೆ ಮಾಡಿ ನಮಸ್ಕರಿಸಿದರು.',
        '0.16': 'ಆ ಪ್ರಭುವು ಹೇಳಿದನು: “ಸೇವಕನಿಗೆ ನಮಸ್ಕಾರ ಉಚಿತವಲ್ಲ; ಆದರೂ ನೀವು ಈಗ ಸ್ಪಷ್ಟವಾಗಿ ನಮಸ್ಕರಿಸಿದ್ದೀರಿ; ಆಹಾ! ವಿಧಾತನೇ ನಿಮ್ಮಿಂದ ಅನುಮತಿಯನ್ನು ಕೊಡಿಸಿದನು.”',
        '0.17': 'ಉತ್ತರ ತೋಚದೆ ಅವನು ಮತ್ತೆ ಬೇಡಿಕೊಂಡು ಯತೀಂದ್ರನಿಗೆ ನಮಸ್ಕರಿಸಿ ಪತ್ನಿಯೊಡನೆ ಹೊರಟನು; ಮನೆಯಲ್ಲಿದ್ದುಕೊಂಡು ಕಲ್ಪಗಳಂತಿರುವ ಕ್ಷಣಗಳನ್ನು ಕಳೆಯುತ್ತಾ ಮಗನ ಮುಖಚಂದ್ರನನ್ನು ನಿರಂತರ ನೆನೆಯುತ್ತಿದ್ದನು.',
        '0.18': 'ಮಗನ ಸಂಕಲ್ಪವನ್ನು ದುಃಖದಿಂದ ಚಿಂತಿಸುತ್ತಾ ಅವನು ಮತ್ತೆ ಮಹಾನದಿಯನ್ನು ದಾಟಿ ಬಂದು, ಒಂದು ಶ್ರೇಷ್ಠ ಗ್ರಾಮದ ಮಠದಲ್ಲಿ ಯತೀಶ್ವರನನ್ನು ಅನುಸರಿಸುತ್ತಿದ್ದ ತನ್ನ ಮಗನನ್ನು ಕಂಡನು.',
        '0.19': 'ಮಹಾತ್ಮರನ್ನು ಅತಿಕ್ರಮಿಸಲು ಹೆದರುವವನಾಗಿದ್ದರೂ, ಕೋಪದಿಂದ ಕಳವಳಗೊಂಡ ಆ ವಿಪ್ರನು “ನನ್ನ ಮಗನು ಕೌಪೀನವನ್ನು ಧರಿಸಿದರೆ ನಾನು ದುಡುಕಿನ ಕಾರ್ಯ ಮಾಡುವ ಪ್ರತಿಜ್ಞೆ ದೃಢ” ಎಂದನು.',
        '0.20': 'ಕ್ಷಣಮಾತ್ರದಲ್ಲಿ ಆ ಪ್ರಭುವು ತನ್ನ ವಸ್ತ್ರವನ್ನು ಹರಿದು ಕೌಪೀನಧಾರಿಯಾಗಿ “ಅಪ್ಪಾ, ನಿನ್ನ ದುಡುಕನ್ನು ಮಾಡು” ಎಂದು ಹೇಳಿ, ಮತ್ತೆ “ನೀನು ಶುಭಕ್ಕೆ ಅಡ್ಡಿ ಮಾಡಬಾರದು” ಎಂದನು.',
        '0.21': '“ಮಗನೇ, ತಂದೆತಾಯಿಗಳನ್ನು ಕಾಪಾಡದೆ ಶುಭವಿಲ್ಲವೆಂದು ಸಜ್ಜನರು ಹೇಳುತ್ತಾರೆ; ನೀನು ದೂರ ಸರಿದರೆ ನಮಗೆ ಪಾಲಕರಿಲ್ಲ; ನಾವಿಬ್ಬರೂ ಸತ್ತಂತೆಯೇ” ಎಂದು ಹೇಳಿದ ತಂದೆಗೆ ಮಗನು ಉತ್ತರಿಸಿದನು:',
        '0.22': '“ಪುರುಷನು ವಿರಕ್ತನಾದಾಗಲೇ ಸಂನ್ಯಾಸವಿಧಿಯೆಂದು ಶ್ರುತಿಯಲ್ಲಿ ಕೇಳಿಬರುತ್ತದೆ; ಆದರೂ ಸಂಗರಹಿತನಾದರೂ ನಿಮ್ಮಿಬ್ಬರಿಗೆ ಸೇವಕನನ್ನು ಏರ್ಪಡಿಸದೆ ನಾನು ಸಂನ್ಯಾಸ ಸ್ವೀಕರಿಸುವುದಿಲ್ಲ.”',
        '0.23': '“ಬಹುಶ್ರುತನಾದ್ದರಿಂದ ನಾನು ಬಲವಂತವಾಗಿ ಸಹಿಸಿಕೊಂಡೇನು; ಆದರೆ ನಿನ್ನ ತಾಯಿ ನಿನ್ನ ಅಗಲಿಕೆಯನ್ನು ಸಹಿಸಳು” ಎಂದು ವಿಪ್ರನು ಹೇಳಲು, “ನೀನು ಅನುಮತಿ ಕೊಡು” ಎನ್ನುತ್ತಾ ಅವನು ತಂದೆಗೆ ನಮಸ್ಕರಿಸಿದನು.',
        '0.24': 'ಆಲೋಚಿಸಿ ನಿರುತ್ತರನಾದ ಆ ವಿದ್ವಾಂಸನು “ಹಾಗೆಯೇ ಆಗಲಿ, ತಾಯಿ ಒಪ್ಪಿದರೆ” ಎಂದು ಕಷ್ಟದಿಂದ ಹೇಳಿ ಮನೆಗೆ ಹೋಗಿ ಪತ್ನಿಯ ಬಳಿ ಆ ಸುದ್ದಿಯನ್ನು ಹೇಳಿದನು.',
        '0.25': 'ಹಿಂದೆ ರಾಕ್ಷಸಾರಿಯಾದ ರಾಮನಿಗೆ ಲಕ್ಷ್ಮಣನಂತೆ, ವೃಕೋದರನಿಗೆ ಇಂದ್ರಪುತ್ರ ಅರ್ಜುನನಂತೆ, ಶೌರಿಗೆ ಗದನಂತೆ, ಆ ಸರ್ವಜ್ಞನಿಗೆ ಕಾರ್ಯವನ್ನು ನೆರವೇರಿಸುವ ಪ್ರಿಯನೂ ಭಕ್ತನೂ ಆದ ತಮ್ಮನು ಜನಿಸಿದನು.',
        '0.26': 'ಒಮ್ಮೆ ಮನೆಗೆ ಬಂದು ಈ ತಮ್ಮನನ್ನೇ ಅವರಿಬ್ಬರ ಪಾಲಕನೆಂದು ತಿಳಿಸುತ್ತಾ, ತನ್ನ ಸಂನ್ಯಾಸವನ್ನು ತಡೆಯಲು ದೃಢನಿಶ್ಚಯಳಾಗಿದ್ದ ತಾಯಿಗೆ ತಂದೆಯ ಅನುಮತಿಯಿಂದ ಅವನು ಹೀಗೆ ಹೇಳಿದನು.',
        '0.27': '“ಅಮ್ಮಾ, ನನ್ನನ್ನು ಎಂದಾದರೂ ನೋಡಬಯಸುವೆಯಾದರೆ ನನ್ನ ಶ್ರೇಷ್ಠಾಶ್ರಮಸ್ವೀಕಾರಕ್ಕೆ ಒಪ್ಪಿಗೆ ಕೊಡು; ಇಲ್ಲದಿದ್ದರೆ ಈ ದೇಶವನ್ನೇ ಬಿಟ್ಟು ಹೋಗಿ ನಿಮ್ಮ ಕಣ್ಣಿಗೆ ಎಂದೂ ಬೀಳುವುದಿಲ್ಲ.”',
        '0.28': 'ಮಗನು ಹೀಗೆ ಹೇಳಲು, ಅವನನ್ನು ಎಂದೂ ನೋಡದಿರುವುದು ಅವನ ಮರಣಕ್ಕೆ ಸಮಾನವೆಂದು ಭಾವಿಸಿ ಬಹಳ ಕಳವಳಗೊಂಡ ಆ ಸಾಧ್ವಿಯು ಕಷ್ಟದಿಂದ ಮಗನ ಬಯಕೆಯನ್ನು ತಡೆಯಲಿಲ್ಲ.',
        '0.29': 'ಆಮೇಲೆ ದೇವಶ್ರೇಷ್ಠನ ಅನುಗ್ರಹಕ್ಕೆ ಪಾತ್ರನಾದ ಆ ಜಗದ್ಗುರುವು ಗುರುವನ್ನು ಸಮೀಪಿಸಿ ಅವನನ್ನು ಪ್ರಸನ್ನಗೊಳಿಸಿದನು; ಸದಾ ಎಲ್ಲ ಆಶ್ರಮಗಳಿಗೂ ಸೇರಿದ ಆ ಸುರೇಶ್ವರನು ವಿಶೇಷವಾಗಿ ಶ್ರೇಷ್ಠಾಶ್ರಮವನ್ನು ಸ್ವೀಕರಿಸಿದನು.',
        '0.30': 'ಕಾಲವನ್ನರಿತ ಅವನು ಸಕಲ ಕ್ರಿಯಾಕಲಾಪವನ್ನು ವಿಧಿಮಾರ್ಗದಿಂದಲೇ ಮಾಡಿ, ಸದಾ ಪ್ರಸನ್ನನಾದ ಹರಿಯ ಪ್ರೀತಿಗಾಗಿ ಮತ್ತೆ ಮತ್ತೆ ಸರ್ವಸಂನ್ಯಾಸವನ್ನು ಉಚ್ಚರಿಸಿದನು.',
        '0.31': 'ಮೂರು ಮಾತ್ರೆಗಳಿಂದ ಆರಂಭವಾಗಿ ಅನಂತ ಮಾತ್ರೆಗಳಲ್ಲಿ ಕೊನೆಗೊಳ್ಳುವುದೆಂದು ಜ್ಞಾನಿಗಳು ಹೇಳುವ ಪ್ರಣವದ ಜಪಕ್ಕೆ ಅಧಿಕಾರಿಯಾಗಿ, ಭಾವಿಚತುರ್ಮುಖರೂಪನಾದ ಈ ಯತಿಯು ಆಗ ಸೂಚಿತನಾದನು.',
        '0.32': '“ಗುಣಗಳಿಗೆ ತಕ್ಕ ಉನ್ನತಿಯುಳ್ಳ ಪೂರ್ಣಬೋಧ (ಪೂರ್ಣಪ್ರಜ್ಞ)” ಎಂಬ ಹೆಸರನ್ನು ದ್ವಿಜವೃಂದದಿಂದ ವಂದಿತನಾದ ಆ ಕೀರ್ತಿಶಾಲಿ ಗುರುವು ಅವನಿಗೆ ಇಟ್ಟನು; ಅದು ಕೇವಲ ಮಂತ್ರಾಕ್ಷರವಲ್ಲ, ಅವನೇ ಮಂತ್ರಗಳನ್ನು ವಿವರಿಸುವವನು.',
        '0.33': 'ಅಂಗರಾಗವಿಲ್ಲದ, ಮುಖಕ್ಕೆ ಬಣ್ಣವಿಲ್ಲದ, ತನ್ನ ಅಲಂಕಾರವೇ ಲೋಕಕ್ಕೆ ಅಲಂಕಾರವಾದ, ಪಲಾಶದಂಡವನ್ನು ಧರಿಸಿದ ಅವನನ್ನು ನೋಡಿ ಜೀವಿಗಳು ಸ್ವಾಭಾವಿಕ ಸೌಂದರ್ಯವೇ ಅನುಪಮವೆಂದು ಭಾವಿಸಿದರು.',
        '0.34': 'ಶೇಷ, ರುದ್ರ, ಗರುಡ ಮೊದಲಾದವರು ಅವಕಾಶಕ್ಕಾಗಿ ಕಾದು ಅವನಿಗೆ ನಮಿಸುತ್ತಿದ್ದರೂ, ಅವನು ಗುರುವೇ ಮೊದಲಾದ ಯತಿಗಳಿಗೆ ನಮಸ್ಕರಿಸಿದನು — ಆಹಾ, ಮಹಾತ್ಮರ ಅಭಿನಯವು ಎಷ್ಟು ಹಿರಿದು!',
        '0.35': 'ಶ್ರೇಷ್ಠಾಶ್ರಮದ ವಿಶೇಷ ಆಚಾರವನ್ನು ಕಲಿಸಬಯಸಿದ ಅವನ ನಡತೆಯನ್ನು ನೋಡುತ್ತಾ, ಧೀರಬುದ್ಧಿಯ ಯತೀಶ್ವರನು ತಾನೇ ವಿಶೇಷ ಶಿಕ್ಷಣವನ್ನು ಪಡೆದು ಒಳಗೊಳಗೆ ವಿಸ್ಮಯಪಟ್ಟನು.',
        '0.36': 'ಮಹಾಮತಿಯಾದ ಅವನು ರೌಪ್ಯಪೀಠವಾಸಿಯಾದ ಸ್ವಾಮಿಗೆ ಸಂತೋಷದಿಂದ ನಮಸ್ಕರಿಸಿದಾಗ, ಶೇಷಶಾಯಿಯಾದ ಆ ದೇವನು ಒಬ್ಬ ಮನುಷ್ಯನನ್ನು ಆವೇಶಿಸಿ ತಕ್ಷಣ ತನ್ನ ಕೈಯಿಂದ ಅವನ ತೋಳನ್ನು ಹಿಡಿದನು.',
        '0.37': '“ಬಹುಕಾಲದಿಂದ ಸತ್ತತ್ತ್ವವನ್ನು ತಿಳಿಯಬಯಸಿ ನೀನು ಮಾಡಿದ ನನ್ನ ಸೇವೆಯ ಫಲವಾಗಿ ಇವನನ್ನು ನಿನಗೆ ಕೊಡುತ್ತೇನೆ” ಎಂದು ಹೇಳಿ ಆ ಸ್ವಾಮಿಯು ಅವನನ್ನು ಕರೆದೊಯ್ದು ಅಚ್ಯುತಪ್ರೇಕ್ಷರಿಗೆ ಒಪ್ಪಿಸಿದನು.',
        '0.38': 'ಆ ಅನುಗ್ರಹವನ್ನು ಆದರದಿಂದ ಸ್ವೀಕರಿಸಿ, ತಾನು ಪಡೆದ ಕೃತಕೃತ್ಯತೆಯನ್ನು ಸಂತೋಷದಿಂದ ನೆನೆಯುತ್ತಾ, ಅಸಂಗನಾಗಿದ್ದರೂ ಆ ಗುರುವು ಅವನಲ್ಲಿ ಸಂಗವುಳ್ಳವನಾದನು; ಅಸಂಗರಿಗೆ ಸಾಧುಸಂಗವೇ ಭೂಷಣವಲ್ಲವೇ!',
        '0.39': 'ಮಹಾಮನಸ್ಕನಾದ ಅವನು ಸ್ವರ್ಗಂಗೆಗೆ ಹೋಗಬಯಸಿ ಅನುಮತಿಗಾಗಿ ಮತ್ತೆ ಮತ್ತೆ ನಮಿಸುತ್ತಿರಲು, ಮುಂದೆ ಬರುವ ಅಗಲಿಕೆಯೆಂಬ ಬೆಂಕಿಯ ಭಯದಿಂದ ದುಃಖಿತನಾದ ಗುರುವು ತನ್ನ ಸ್ವಾಮಿಯನ್ನೇ ಸ್ಮರಿಸಿದನು.',
        '0.40': 'ಆಗ ಕರುಣಾಕರನಾದ ಹರಿಯು ಒಬ್ಬನನ್ನು ಆವೇಶಿಸಿ ಅವನಿಗೆ ಹೇಳಿದನು: “ಇಂದಿನಿಂದ ಮೂರನೆಯ ದಿನ ಸ್ವರ್ಗಂಗೆಯು ನಿನಗಾಗಿ ನಮ್ಮ ಸರೋವರಕ್ಕೆ ಬರುವಳು; ಆದ್ದರಿಂದ ಹೋಗಬೇಡ.”',
        '0.41': 'ಅವನ ಆಜ್ಞೆಯಂತೆ ಬಂದ ಗಂಗಾಜಲದಲ್ಲಿ ಜನರು ಪೂರ್ಣಬುದ್ಧಿಯೊಡನೆ ಅಲ್ಲಿ ಸ್ನಾನ ಮಾಡಿದರು; ಅಂದಿನಿಂದ ಅವನ ಅನುಗ್ರಹದ ಗುರುತಾಗಿ ಹನ್ನೆರಡು ವರ್ಷಗಳಿಗೊಮ್ಮೆ ಅವಳು ಸದಾ ಬರುತ್ತಾಳೆ.',
        '0.42': 'ಶ್ರೇಷ್ಠಾಶ್ರಮವನ್ನು ಪಡೆದು ಹತ್ತು ದಿನಗಳು ಕಳೆಯಲು, ಪತ್ರವನ್ನು ತೂಗುಹಾಕಿ (ವಾದಕ್ಕೆ ಆಹ್ವಾನಿಸಿ), ಅನೇಕ ತರ್ಕಗಳಿಂದ ಕಠಿಣರಾದ ಜಯಶಾಲಿಗಳಾದ ವಾಸುದೇವಪಂಡಿತ ಮೊದಲಾದವರನ್ನು ಅವನು ಗೆದ್ದನು.',
        '0.43': 'ತನ್ನ ಶಿಷ್ಯನನ್ನು ಚತುರನನ್ನಾಗಿಸಬಯಸಿದ ಗುರುವಿನ ಪ್ರೇರಣೆಯಿಂದ, ಆ ಮಹಾತ್ಮನು ಅನಾದರವಿದ್ದರೂ ಛಲ ಜಾತಿಗಳ ಸಮುದ್ರವಾದ “ಇಷ್ಟಸಿದ್ಧಿ”ಯನ್ನು ಇಲ್ಲಿ ಕೇಳಲು ಆರಂಭಿಸಿದನು.',
        '0.44': 'ಅದರ ಮೊದಲ ಪದ್ಯದಲ್ಲೇ ಮೂವತ್ತೆರಡು ದೋಷಗಳ ಸಮೂಹವನ್ನು ಅವನು ಹೇಳಲು, “ಅದು ಮುಂದೆ ನಿರಾಕರಿಸಲ್ಪಟ್ಟಿದೆ” ಎಂದು ಗುರುವು ಹೇಳಿದಾಗ, “ಹಾಗಾದರೆ ಹೇಳಲ್ಪಡಲಿ” ಎಂದು ಅವನು ಹೇಳಿದನು.',
        '0.45': '“ನಿನಗೆ ವಿವರಿಸುವ ಸಾಮರ್ಥ್ಯ ನನಗಿಲ್ಲ” ಎಂದು ಯತೀಶ್ವರನು ಕೋಪದಿಂದ ಹೇಳಲು, ಮಾಯಾವಾದದಲ್ಲಿ ನಿಪುಣರಾದ ಜನರಲ್ಲೂ ಅದರ ದೋಷಗಳ ಬಗ್ಗೆ ಸಂಶಯದ ಮೊಳಕೆ ಹುಟ್ಟಿತು.',
        '0.46': '“ಜ್ಞಾನಿಯು ಉಪದೇಶಿಸಬೇಕು, ಮುಮುಕ್ಷುವಾದ ಅಜ್ಞನು ನಿಶ್ಚಯವಾಗಿ ಕೇಳಬೇಕು, ಯತಿಯಂತೂ ವಿಶೇಷವಾಗಿ” ಎಂಬ ಜನರ ಒತ್ತಾಯದಿಂದ ಪೂರ್ಣಧೀಯು ಮಾಯಾವಾದವನ್ನು ಪ್ರವಚಿಸಿದನು.',
        '0.47': 'ಅಖಂಡವಾದ ಉಪನ್ಯಾಸವುಳ್ಳ, ಸಂಶಯರಹಿತವಾದ, ಸಂಪ್ರದಾಯಬದ್ಧವಾದ, ದೃಢವಾದ ಉತ್ತರಗಳುಳ್ಳ ಅವನ ಪ್ರವಚನವನ್ನು ಕೇಳಲು ವಿದ್ವಾಂಸರೂ ಚತುರರೂ ಉನ್ನತಿಯನ್ನು ಬಯಸುವವರೂ ಆದ ಜನರು ಆಸಕ್ತಿಯಿಂದ ಬಂದರು.',
        '0.48': 'ಒಮ್ಮೆ ಗುರುವಿನ ಬಳಿ ಭಾಗವತವನ್ನು ಕೇಳುತ್ತಿದ್ದ ಐದಾರು ಬ್ರಾಹ್ಮಣರು ಅನೇಕ ಪಾಠಭೇದಗಳಿಂದ ಬರೆಯಲ್ಪಟ್ಟಿದ್ದ ಭಾಗವನ್ನು ಓದಿದಾಗ, ಆ ಪ್ರಭುವು ಒಂದು ಪಾಠವನ್ನು ದೃಢವಾಗಿ ಹೇಳಿದನು.',
        '0.49': '“ಬೇರೆ ಪಾಠಗಳೂ ಸಾಧ್ಯವಿರುವಾಗ ನೀನು ಇದನ್ನೇ ಹೇಗೆ ನಿರ್ಣಯಿಸುತ್ತೀಯೆ?” ಎಂದು ಕೇಳಲು, ಆ ಮಹಾಹೃದಯನು ಮುಕುಂದಜ್ಞಾನದಿಂದ ಭಗವಂತನು (ವ್ಯಾಸರು) ರಚಿಸಿದ ಒಂದು ಪಾಠವನ್ನು ಸ್ಪಷ್ಟವಾಗಿ ಹೇಳಿದನು.',
        '0.50': '“ಜಗದ್ಗುರುವಿನ ಕೃತಿಯ ಸ್ಥಿತಿಯನ್ನು ನೀನು ಬಲ್ಲೆಯಾದರೆ ಇಲ್ಲಿಯೇ ಐದನೆಯ ಸ್ಕಂಧದ ಗದ್ಯವನ್ನು ಹೇಳು” ಎಂದು ಯತಿಶ್ರೇಷ್ಠನು ಹೇಳಲು, ಆ ಮಹಾಹೃದಯನು ತಾನು ಹೇಳಿದ ರೀತಿಯಲ್ಲೇ ಅದನ್ನು ಹೇಳಿದನು.',
        '0.51': 'ಆಗ ಅವನ ಆಜ್ಞೆಯಿಂದ ಎಲ್ಲ ಶಿಷ್ಯರೂ ಪರೀಕ್ಷೆಗಾಗಿ ಎಲ್ಲ ಹಸ್ತಪ್ರತಿಗಳನ್ನೂ ನೋಡಿದರು; ಅವುಗಳಲ್ಲಿ ಒಂದರಲ್ಲಿ ಮಾತ್ರ ಇದ್ದ ಅಧ್ಯಾಯಸಮೂಹವನ್ನು ಅವನು ಬಿಟ್ಟು ಹೇಳಿದ್ದನು.',
        '0.52': '“ಜಯಶೀಲನೇ, ಈ ಜನ್ಮದಲ್ಲಿ ನೀನು ಓದದಿದ್ದುದು ನಿನಗೆ ಹೇಗೆ ಹೊಳೆಯುತ್ತದೆ?” ಎಂದು ಅವನು ಕೇಳಲು, “ಹಿಂದಿನ ಜನ್ಮಗಳಲ್ಲಿ ಇದೆಲ್ಲವನ್ನೂ ಹಿಂದೆಯೇ ಅರಿತಿದ್ದೇನೆ” ಎಂದನು ಅಮಿತಬುದ್ಧಿ.',
        '0.53': 'ಹೀಗೆ ಲೋಕವನ್ನೆಲ್ಲ ಆಶ್ಚರ್ಯಗೊಳಿಸುವ ಅನೇಕ ಮನೋವ್ಯಾಪಾರಗಳಿಂದ ಅವನ ಹೊಸ ಕೀರ್ತಿಯು ಲೋಕದಲ್ಲಿ ವಿಸ್ತರಿಸಿತು — ಹರಡಿದ ಕತ್ತಲನ್ನು ನಾಶಮಾಡುವ ಸೂರ್ಯಪ್ರಭೆಯಂತೆ, ಸಜ್ಜನರೆಂಬ ನೈದಿಲೆಗಳಿಗೆ ಆನಂದ ಕೊಡುವ ಬೆಳದಿಂಗಳಿನಂತೆ.',
        '0.54': 'ಹೀಗೆ ಕವಿಕುಲತಿಲಕರಾದ ತ್ರಿವಿಕ್ರಮಪಂಡಿತಾಚಾರ್ಯರ ಪುತ್ರ ನಾರಾಯಣಪಂಡಿತಾಚಾರ್ಯರು ರಚಿಸಿದ “ಆನಂದ” ಎಂಬ ಅಂಕಿತವುಳ್ಳ ಶ್ರೀಮತ್ಸುಮಧ್ವವಿಜಯ ಮಹಾಕಾವ್ಯದ ನಾಲ್ಕನೆಯ ಸರ್ಗ ಮುಗಿಯಿತು.',
      },
    },
    'sumadhva-vijaya-05': {
      verses: {
        '0.0': 'ವೇದಾಂತವಿದ್ಯೆಯೆಂಬ ತನ್ನ ರಾಜ್ಯವನ್ನು ಪಾಲಿಸುವ ಮಹತ್ತರ ಕಾರ್ಯಕ್ಕೆ ಗುರುವಿನಿಂದ ಸಂಕಲ್ಪಿಸಲ್ಪಟ್ಟ ಆ ವಿಶಾಲಹೃದಯನು ಕಮಲಗಳಿಂದ ತುಂಬಿದ ಜಲದಿಂದ ಅಭಿಷಿಕ್ತನಾದನು.',
        '0.1': 'ಆನಂದರೂಪನಾದ ಪರಮಾತ್ಮನಿಗೆ ಪಾತ್ರನಾದ ಬುದ್ಧಿಯುಳ್ಳವನೂ ಆನಂದವನ್ನು ಕೊಡುವ ಸುಶಾಸ್ತ್ರಗಳನ್ನು ರಚಿಸುವವನೂ ಆದ್ದರಿಂದ, ಗುರುವು ಇಟ್ಟ “ಆನಂದತೀರ್ಥ” ಎಂಬ ಹೆಸರು ಅವನಿಗೆ ಅತ್ಯಂತ ಅನುರೂಪವಾಯಿತು.',
        '0.2': 'ಒಮ್ಮೆ ಅಚ್ಯುತಪ್ರೇಕ್ಷರ ಸ್ನೇಹಿತನಾದ ಒಬ್ಬ ಯತಿಯು ಅನೇಕ ಶಿಷ್ಯರೊಡನೆ ಅಲ್ಲಿಗೆ ಬಂದನು; ಅನುಮಾನಶಾಸ್ತ್ರದಲ್ಲಿ ಶಿಕ್ಷಿತರಾದ ಅವನ ಉದ್ಧತ ಶಿಷ್ಯರು ಮಹಾಬುದ್ಧಿಯಾದ ಮಧ್ವರನ್ನು ಗೆಲ್ಲಬಯಸಿದರು.',
        '0.3': '“ಭೇದವು ಸಾಧಿಸಲಾಗದು” ಎಂಬ ಪ್ರತಿಪಕ್ಷಕ್ಕೆ ಭಯಂಕರವಾದ ಅನುಮಾನವನ್ನು ಅವರು ಬೇಗನೆ ಪ್ರಯೋಗಿಸಿದರು; ಪಕ್ಷದಲ್ಲಿ ದಕ್ಷನಾದ ಅಖಂಡಬುದ್ಧಿಯು ಪಕ್ಷಿರಾಜನು ಹಾವನ್ನು ಸೀಳುವಂತೆ ಅದನ್ನು ಸ್ಪಷ್ಟವಾಗಿ ಖಂಡಿಸಿದನು.',
        '0.4': 'ಆಮೇಲೆ ಅವರು “ವಿವಾದದಲ್ಲಿರುವ ಜಗತ್ತು ಮಿಥ್ಯೆ, ಏಕೆಂದರೆ ಅದು ಜ್ಞಾನವಿಷಯ, ವಿವಾದರಹಿತವಾದ (ಶುಕ್ತಿರಜತದಂತಹ) ವಸ್ತುವಿನಂತೆ” ಎಂದರು; ಅವನು “ವಿವಾದದಲ್ಲಿರುವುದು ಸತ್ಯ, ಏಕೆಂದರೆ ಅದು ಸತ್ಯವೆಂದು ತಿಳಿಯಲ್ಪಡುತ್ತದೆ, ಘಟಾದಿಗಳಂತೆ” ಎಂಬ ಅನುಮಾನವನ್ನು ಹೇಳಿದನು.',
        '0.5': 'ಅವರು ಕುತೂಹಲದಿಂದ ಅವನ ಹೇತುವಿಗೆ ಅತಿವ್ಯಾಪ್ತಿದೋಷವನ್ನು ಹೇಳಿದಾಗ, ವಿಸ್ಮಯವಿಲ್ಲದ ಅವನು ಬೇಗನೆ “ಶುಕ್ತಿರಜತಾದಿಗಳು ಸತ್ಯವೆಂದು ತಿಳಿಯಲ್ಪಡುವುದಿಲ್ಲ; ಬೇರೆಯಾಗಿ ತಿಳಿಯಲ್ಪಡುವುದು ಬೇರೆ” ಮೊದಲಾಗಿ ಹೇಳಿ ಅವರನ್ನು ಗೆದ್ದನು.',
        '0.6': 'ವಿವಾದಾಸ್ಪದ ವಿಷಯದಲ್ಲಿ ಸತ್ಯಕ್ಕೂ ಅಸತ್ಯಕ್ಕೂ ಅನುಮಾನಗಳನ್ನು ಹೇಳಿ, ಅಲ್ಲಿ ಅನುಮಾನವೊಂದೇ ನಿರ್ಣಾಯಕವಲ್ಲವೆಂದು ತಾನೇ ಪ್ರತಿಪಾದಿಸಿ, ಸಭೆಗಳಲ್ಲಿ ಎಲ್ಲ ವಿದ್ವಾಂಸರನ್ನೂ ಗೆದ್ದು ಅವನು “ಅನುಮಾನತೀರ್ಥ” ಎಂಬ ಹೆಸರನ್ನೂ ಪಡೆದನು.',
        '0.7': 'ಆಮೇಲೆ ಎದುರಾಳಿಗಳನ್ನು ಬಯಸಿ ಭೂಮಿಯಲ್ಲಿ ಸಂಚರಿಸುತ್ತಿದ್ದ, ವಾದಿಶ್ರೇಷ್ಠರೆಂಬ ಆನೆಗಳನ್ನು ಭಂಗಿಸುವ, ವೇದದ್ವೇಷಿಗಳಲ್ಲಿ ಮೊದಲಿಗನಾದ ಬುದ್ಧಿಸಾಗರನು ವಾದಿಸಿಂಹನೊಡನೆ ಇಲ್ಲಿಗೆ ಬಂದನು.',
        '0.8': 'ಬಲವಾದ ಕೋಟೆಯ ಗರ್ವವುಳ್ಳ ಅವನನ್ನು ಗೆಲ್ಲಬಯಸಿ, ಮುಕುಂದನಲ್ಲಿ ಮನಸ್ಸಿಟ್ಟ ಗುರುವು ತನ್ನ ಶಿಷ್ಯನ ಕೈಯಿಂದ ಮಠವೆಂಬ ಬತ್ತಳಿಕೆಯಿಂದ ಉತ್ತಮ ಗರಿಯುಳ್ಳ ಹರಿತವಾದ ಸುಖತೀರ್ಥನೆಂಬ (ಆನಂದತೀರ್ಥನೆಂಬ) ಬಾಣವನ್ನು ಬೇಗನೆ ತೆಗೆದುಕೊಂಡನು.',
        '0.9': 'ಪ್ರತಿಜ್ಞೆಗಳ ವಿಷಯದಲ್ಲಿ ಕುತೂಹಲದಿಂದ ಕೂಡಿದ ಜನಸಮೂಹವು ಬೇಗನೆ ಸೇರಿದುದನ್ನು ಕೇಳಿ, ಗರಿಷ್ಠಬುದ್ಧಿಯಾದ ಅವನು ಬಂದು ರೂಪ್ಯಪೀಠದ ಉತ್ತಮ ದೇವಾಲಯದಲ್ಲಿದ್ದ ಗುರುವಿಗೆ ನಮಸ್ಕರಿಸಿದನು.',
        '0.10': 'ಪಂಡಿತಮಂಡಲದ ಮಧ್ಯೆ ಅವನು ವಾದಿಸಿಂಹನ ಗಂಭೀರ ಮಾತನ್ನು ತೀಕ್ಷ್ಣವೂ ಮಿತವೂ ವೇಗವೂ ಆದ ವಾಕ್ಯಗಳಿಂದ ಮತ್ತೆ ಮತ್ತೆ ಖಂಡಿಸಿದನು — ನಿಪುಣ ಧನುರ್ಧಾರಿಯು ಬಾಣದಿಂದ ಗದೆಯನ್ನು ಖಂಡಿಸುವಂತೆ.',
        '0.11': 'ಆಮೇಲೆ ಇನ್ನೊಬ್ಬನು (ಬುದ್ಧಿಸಾಗರನು) ಅಸೂಯೆಯಿಂದ ಒಂದು ವಿಷಯವನ್ನು ಹದಿನೆಂಟು ಬಗೆಗಳಲ್ಲಿ ಗಟ್ಟಿಯಾಗಿ ಕಲ್ಪಿಸಿದನು; ಆಗ ಜಗದ್ವಿಜೇತನಾದ ಪೂರ್ಣಪ್ರಜ್ಞನ ಜಯದ ಬಗ್ಗೆ ಜನರಿಗೆ ಸ್ವಲ್ಪ ಸಂಶಯ ಉಂಟಾಯಿತು.',
        '0.12': 'ಆಮೇಲೆ ಅಸಂಖ್ಯ ವಿಕಲ್ಪಗಳನ್ನು ಬೇಗನೆ ಖಂಡಿಸುತ್ತಾ ಆ ಬೃಹನ್ಮತಿಯು ಮುಗುಳ್ನಗೆಯ ಮುಖದಿಂದ ಇನ್ನಷ್ಟು ಹೊಳೆದನು — ನಿರ್ಮಲ ಕಿರಣಗಳಿಂದ ಕತ್ತಲೆಯ ರಾಶಿಯನ್ನು ನಾಶಮಾಡುತ್ತಾ ಆಕಾಶದಲ್ಲಿ (ವಿಷ್ಣುಪದದಲ್ಲಿ) ನೆಲೆಸಿರುವ ಸೂರ್ಯನಂತೆ.',
        '0.13': 'ಸಮುದ್ರವನ್ನು ಕುಡಿದ ಕುಂಭಸಂಭವನಾದ ಅಗಸ್ತ್ಯನಂತೆ, ಮಹಾಮನಸ್ಕನಾದ ಅವನು ತನ್ನ ದೃಷ್ಟಿಯಲ್ಲಿ ಅಗಾಧವಾದ, ಮೇರೆ ಮೀರಿದ, ಉದ್ಧತವಾದ, ಇತರ ಎಲ್ಲ ವಿದ್ಯಾಪ್ರವಾಹಗಳನ್ನು ತಿರಸ್ಕರಿಸಿದ ಆ “ಬುದ್ಧಿಸಾಗರ”ನನ್ನು ಸುಲಭವಾಗಿ ಹಗುರಗೊಳಿಸಿದನು.',
        '0.14': '“ನಾಳೆ ವಾದ ಮುಂದುವರಿಯಲಿ” ಎಂದು ಆ ಇಬ್ಬರು ದುಷ್ಟವಾದಿಗಳು ಹೇಳಲು, “ಉತ್ತರ ಹೊಳೆದರೆ ಇಂದೇ ಹೇಳಿ” ಎಂದು ಮಧ್ವರು ಹೇಳಿದಾಗ, ಜನರು ಅವರು ಸೋತರೆಂದು ಭಾವಿಸಿದರು; ರಾತ್ರಿ ಅವರು ಓಡಿಹೋದುದರಿಂದ ಅದನ್ನು ನಿಶ್ಚಯಿಸಿಕೊಂಡರು.',
        '0.15': '“ಆಹಾ! ಬುದ್ಧಿಸಾಗರನೂ ಆ ವಾದಿಶ್ರೇಷ್ಠನೂ ಬಹುಕಾಲ ಭೂಮಿಯನ್ನು ಸುತ್ತಿ ಗಳಿಸಿದ ಜಯಶ್ರೀಯನ್ನು ಇವನು ಪ್ರಯತ್ನವಿಲ್ಲದೆ ಕ್ಷಣದಲ್ಲಿ ಪಡೆದನು!” ಎಂದು ಜನರು ಅತ್ಯಂತ ವಿಸ್ಮಯಪಟ್ಟರು.',
        '0.16': 'ಒಮ್ಮೆ ಮಣಿಮಂತನಿಂದ (ಕವಿಯ ಪ್ರಕಾರ) ರಚಿತವಾದ ಭಾಷ್ಯವನ್ನು ತರ್ಕನಿಪುಣರಿಂದ ಸುತ್ತುವರಿಯಲ್ಪಟ್ಟು ವ್ಯಾಖ್ಯಾನಿಸುತ್ತಿರುವಾಗ, ಆನಂದತೀರ್ಥರು ಪರಿಹಾಸದ ನಗೆಯೊಡನೆ ದೇವತೆಗಳಿಗೆ ಸಂತೋಷ ಕೊಡುವ ಮಾತನ್ನಾಡಿದರು.',
        '0.17': '“ಶುದ್ಧಬುದ್ಧಿಯುಳ್ಳವರು ಉಗ್ರವಾದ ಗೂಢ ಹಠವನ್ನು ಬಿಟ್ಟು ಸೂತ್ರಗಳ ನಿಜವಾದ ಭಾವವನ್ನೂ ಭಾಷ್ಯದ ಅಭಿಪ್ರಾಯವನ್ನೂ ಪ್ರತ್ಯೇಕವಾಗಿ ವಿಚಾರಿಸಿದರೆ, ಆಹಾ, ಇವೆರಡರ ನಡುವೆ ಮಾನ್ಯವಾದ ಹೊಂದಾಣಿಕೆ ಕಾಣುವುದಿಲ್ಲ.”',
        '0.18': 'ಹೀಗೆ ಹೇಳುತ್ತಾ ಆ ಭಾಷ್ಯದಲ್ಲಿ ಪ್ರಬಲವಾದ ದೋಷಗಳನ್ನು ಮತ್ತೆ ಮತ್ತೆ ತೋರಿಸುತ್ತಿರಲು, ವಿಸ್ಮಿತರಾಗಿದ್ದರೂ ಅವರು ಪ್ರಯತ್ನಪಟ್ಟರೂ ಅವುಗಳನ್ನು ದೃಢವಾಗಿ ಪರಿಹರಿಸಲಾಗಲಿಲ್ಲ.',
        '0.19': 'ಆ ವಾಗ್ಮಿಗಳು ಹೇಳಿದರು: “ನೀನು ಕೇವಲ ಭಾಷ್ಯವನ್ನು ನಿರಾಕರಿಸುತ್ತಿರುವುದರಿಂದ, ನಿನ್ನಂತಹ ಕವಿಗಳಿಂದಲೂ ಯಾವ ರೀತಿಯಲ್ಲೂ ದೂಷಿಸಲಾಗದ ಈ ಸೂತ್ರದ ಬೇರೆ ಅರ್ಥವನ್ನು ಹೇಳು.”',
        '0.20': 'ಆಗ ಅವನು ಸಹಜವಾದ ಪದಾನ್ವಯವುಳ್ಳ, ಪ್ರಮಾಣೀಕೃತವಾದ ವೇದಸ್ಮೃತಿಗಳಿಂದ ಕೂಡಿದ, ಮುಂದೆ ಬರಲಿರುವ ಭಾಷ್ಯವೆಂಬ ನೃತ್ಯಕ್ಕೆ ಸೂತ್ರಧಾರನಂತಿರುವ ಸಾಧ್ಯವಾದ ಸೂತ್ರಾರ್ಥವನ್ನು ಗಟ್ಟಿಯಾಗಿ ಹೇಳಿದನು.',
        '0.21': 'ತಿಳಿಯುವ ಬಯಕೆಯಿಂದ ಬಂದ ಮತ್ಸರರಹಿತರಾಗಲಿ, ಗೆಲ್ಲುವ ಬಯಕೆಯಿಂದ ಬಂದ ಮತ್ಸರಿಗಳಾಗಲಿ, ಶಾಸ್ತ್ರಪ್ರವೀಣರೂ ಮಹಾತಾರ್ಕಿಕರೂ ಆದ ಅವರನ್ನು ಅವನು ಈ ರೀತಿಯಿಂದ ಮತ್ತೆ ಮತ್ತೆ ಸೋಲಿಸಿದನು.',
        '0.22': 'ಒಮ್ಮೆ ಸೌಮ್ಯಬುದ್ಧಿಯ ಶ್ರೇಷ್ಠನಾದ ಮಧ್ಯಗೇಹಭಟ್ಟನು ಅವನ ಬಳಿಗೆ ಬಂದು ಪ್ರಸನ್ನನಾದನು; ಯಾವುದೋ ಕಾರಣದಿಂದ ಖಿನ್ನನಾಗಿದ್ದರೂ ಗುಣಸಾಗರದಲ್ಲಿ ಆಸಕ್ತನಾದ ಸಜ್ಜನನು ಪ್ರಸನ್ನನಾಗುತ್ತಾನಲ್ಲವೇ!',
        '0.23': 'ಆ ಪಂಡಿತನು ಮಗನ ದೇಹವೆಂಬ ಪಾತ್ರೆಯಲ್ಲಿದ್ದ ಅಕ್ಷಯವಾದ ತೇಜೋಮೃತವನ್ನು ಕಣ್ಣುಗಳೆಂಬ ಬೊಗಸೆಗಳಿಂದಲೂ, ಅವನ ಮಾತೆಂಬ ಮಹಾಕಲಶದಲ್ಲಿ ತುಂಬಿದ ವಿದ್ಯಾಮೃತವನ್ನು ಕಿವಿಗಳೆಂಬ ಬಟ್ಟಲುಗಳಿಂದಲೂ ಕುಡಿದನು.',
        '0.24': 'ಲೀಲಾವಿವಾದದಲ್ಲಿ ಪ್ರಸಂಗವಶಾತ್ ಅಂತಹ ಸಂದರ್ಭ ಬಂದಾಗ, ಗುರುವು ಆಕ್ಷೇಪಪೂರ್ವಕವಾಗಿ “ನೀನು ಸೂತ್ರಾರ್ಥವನ್ನು ಬಲ್ಲೆಯಾದರೆ ಕೂಡಲೇ ಭಾಷ್ಯವನ್ನು ರಚಿಸು” ಎಂದು ಜಗದ್ಗುರುವಿಗೆ ಹೇಳಿದನು.',
        '0.25': 'ಹಂಸರಾಜನು ನೀರಿನಿಂದ ಶುದ್ಧ ಹಾಲನ್ನು ಮಾತ್ರ ತೆಗೆದುಕೊಳ್ಳುವಂತೆ, ಆ ಪರಮಹಂಸನು ಆಗ ವಿಧಾನವನ್ನು ಮಾತ್ರ ಸ್ವೀಕರಿಸಿ, ಅದರಲ್ಲಿ ಬೆರೆತ ನಿಷ್ಫಲ ಆಕ್ಷೇಪವನ್ನು ನೀರಿನಂತೆ ಉಪೇಕ್ಷಿಸಿದನು; ಸಜ್ಜನರು ಗುಣಾಂಶದಿಂದಲೇ ತೃಪ್ತರು.',
        '0.26': 'ಒಮ್ಮೆ ವೈರಾಗ್ಯ, ಧೈರ್ಯ, ಸುವಾಕ್ತ್ವ ಮೊದಲಾದ ಪರಮಹಂಸಭೂಷಣಗಳಾದ ಗುಣಗಳಿಂದ ಕೂಡಿದ, ಲಿಕುಚವಂಶದಲ್ಲಿ ಜನಿಸಿದ ಹಿರಿಯ ಯತಿಯು ಅಪಾರ ಭಕ್ತಿಯಿಂದ ಅವನಿಗೆ ಹೀಗೆ ಹೇಳಿದನು:',
        '0.27': '“ಈ ಭಾಷ್ಯಾದಿಗಳು ವೇದಾಂತಸಿದ್ಧಾಂತಸಂಪತ್ತಿಗೆ ವಿರೋಧಿಗಳಾದರೆ ಆಗಲಿ, ಏನು ಹಾನಿ? ಸೂತ್ರಗಳೂ ಉಪನಿಷತ್ತುಗಳೂ ವಿವಕ್ಷಿಸಿದ ಭಾವವನ್ನು ವಿಚಕ್ಷಣರಿಗೆ ಉಚಿತವಾಗಿ ನಮಗೆ ಹೇಳು.”',
        '0.28': 'ಅವನ ಮಾತಿನಿಂದ ಶರತ್ಕಾಲದಿಂದಂತೆ ಎಲ್ಲ ದಿಕ್ಕುಗಳೂ ಶುಭದಿಂದ ತುಂಬಿ ಬೆಳಗಿದಾಗ, ವಿಷ್ಣುಪದವನ್ನು (ಆಕಾಶವನ್ನು/ವಿಷ್ಣುತತ್ತ್ವವನ್ನು) ಬೆಳಗುವ “ವ್ಯಾಖ್ಯಾನ” ಎಂಬ ಆನಂದತೀರ್ಥರ ಮುಖಚಂದ್ರನ ಬೆಳದಿಂಗಳು ಪ್ರಕಾಶಿಸಿತು.',
        '0.29': 'ಒಮ್ಮೆ ಯಮನಿಂದ ಪಾಲಿತವಾದ ದಕ್ಷಿಣದಿಕ್ಕನ್ನು ಗೆಲ್ಲಲು ಅಚ್ಯುತಪ್ರೇಕ್ಷರೊಡನೆ ಹೊರಟ ಸಮಗ್ರಬುದ್ಧಿಯು ವಿಷ್ಣುಮಂಗಲದಲ್ಲಿ ಆ ಸ್ಥಳವನ್ನು ಅಲಂಕರಿಸಿರುವ ಜಗನ್ಮಂಗಲನಾದ ವಿಷ್ಣುವಿಗೆ ನಮಸ್ಕರಿಸಿದನು.',
        '0.30': 'ಅಲ್ಲಿ ಭಿಕ್ಷೆ ಕೊಟ್ಟವನು ಪರೀಕ್ಷಿಸಲು ಮತ್ತೆ ಮತ್ತೆ ಬಾಳೆಹಣ್ಣಿನ ರಾಶಿಯನ್ನು ಕೊಡಲು, ಅವನು ಪ್ರಯಾಸವಿಲ್ಲದೆ ಅವನ್ನೆಲ್ಲ ತಿನ್ನಲು, ವಿಸ್ಮಯವನ್ನು ತಡೆಯಲಾರದ ಗುರುವು ಏಕಾಂತದಲ್ಲಿ ಆ ಆರ್ಯಶ್ರೇಷ್ಠನಿಗೆ ಹೇಳಿದನು:',
        '0.31': '“ಭಿಕ್ಷೆಯ ಕೊನೆಯಲ್ಲಿ ನೀನು ತಿಂದ ಇನ್ನೂರಕ್ಕೂ ಹೆಚ್ಚು ಹಣ್ಣುಗಳಿಂದ ತುಂಬಿದ್ದರೂ ನಿನ್ನ ಸಣ್ಣ ಹೊಟ್ಟೆಯಲ್ಲಿ ಭಾರವೇ ಇಲ್ಲ; ಇದು ಹೇಗೆ? ಸುಚಿತ್ತನೇ, ಸತ್ಯ ಹೇಳು.”',
        '0.32': 'ಆಗ ವಿಶ್ವೇಶನಲ್ಲಿ ಮನಸ್ಸಿಟ್ಟ ಅವನು ಹೇಳಿದನು: “ನನ್ನ ಹೊಟ್ಟೆಯಲ್ಲಿ ಅಂಗುಷ್ಠಮಾತ್ರವಾದ, ಜಾಜ್ವಲ್ಯಮಾನವಾದ, ಸದಾ ಹಿತಕರವಾದ, ಎಲ್ಲವನ್ನೂ ದಹಿಸುವ ಅಗ್ನಿಯಿದೆ ಎಂದು ತಿಳಿ.”',
        '0.33': 'ಕಲಕಿದ ಅನೇಕ ನದಿಗಳ ಸಾಲುಗಳುಳ್ಳ ದೇಶಗಳನ್ನೂ, ನ್ಯಾಯಯುಕ್ತವಾದ ವಿವಿಧಾರ್ಥಗಳುಳ್ಳ ಮತಗಳನ್ನೂ ದಾಟಿ ಆ ಚಾರುಬುದ್ಧಿಯು ತಾನು ಬಯಸಿದ ಮಾರ್ಗದಲ್ಲಿ ಮುಂದೆ ಸಾಗಿದನು.',
        '0.34': 'ದಾರಿಯಲ್ಲಿ, ಆಟವಾಡುವಂತೆ ಮರಗಳ ಸಾಲನ್ನು ಉರುಳಿಸುವ, ಬುದ್ಧಿಶುದ್ಧಿಯನ್ನು ಕೊಡುವ, ಕೇರಳಕ್ಕೆ ಆಭರಣದಂತಿರುವ, ದ್ವಿಜಪೂಜಿತವಾದ ಪಯಸ್ವಿನೀ ನದಿಯನ್ನು ನೋಡಿ ಅವನು ಅಲ್ಲಿ ಪ್ರಕಟವಾಗಲಿರುವ ಚಂಡಿಕೆಯನ್ನು ನೆನೆದನು.',
        '0.35': 'ಆಮೇಲೆ ಕ್ರಮವಾಗಿ ಮುಂದೆ ಸಾಗಿ ಶ್ರೀಮದನಂತಪುರಕ್ಕೆ (ಅನಂತಶಯನಕ್ಕೆ) ಬಂದು, ನೀಲಕಮಲದಂತೆ ಸುಂದರ ಕಾಂತಿಯುಳ್ಳ, ಶೇಷಶಾಯಿಯಾದ ಪದ್ಮನಾಭನಾದ ಶ್ರೀಪತಿಗೆ ನಮಸ್ಕರಿಸಿದನು.',
        '0.36': 'ಸಿದ್ಧಾಂತಜ್ಞರಲ್ಲಿ ಶ್ರೇಷ್ಠನಾದ ಅವನು ಸಭೆಯಲ್ಲಿ ಶಿಷ್ಯರಿಗೆ ವೇದಾಂತಸೂತ್ರಗಳನ್ನು ವ್ಯಾಖ್ಯಾನಿಸುತ್ತಾ, ಗುಣಸಾಗರನಾದ ಅಚ್ಯುತನೆಂಬ ಬ್ರಹ್ಮವು ಜೀವಸಮೂಹದಿಂದ ವಿಲಕ್ಷಣವೆಂದು ಮತ್ತೆ ಮತ್ತೆ ಪ್ರತಿಪಾದಿಸಿದನು.',
        '0.37': 'ಆಗ ಅಪ್ರಾಂಶುನೂತನ ಎಂಬ ಹೆಸರಿನ ಸ್ಥಳದಲ್ಲಿ ಜನಿಸಿದ, ವೈರಪರಾಯಣನಾದ ಒಬ್ಬ “ಸಂಕರ”ನು (ಗೊಂದಲಕಾರನು) ಅಸೂಯೆಯಿಂದ “ಭಾಷ್ಯ ರಚಿಸದವರು ಸೂತ್ರಾರ್ಥವನ್ನು ಹೇಳುವುದು ಮಹಾ ಅತಿಕ್ರಮ” ಎಂದನು.',
        '0.38': '“ಉತ್ತರ ಹೊಳೆದರೆ ಹೇಳು; ನಾವು ಇಲ್ಲಿ ಭಾಷ್ಯವನ್ನು ರಚಿಸುತ್ತೇವೆ; ಜಗದ್ಗುರುಗಳಾದ ದಂಡಧಾರಿಗಳಿಗೆ ಗ್ರಂಥರಚನೆ ನಿಷಿದ್ಧವಲ್ಲ” ಎಂಬ ಗುರುವಿನ ಮುಗುಳ್ನಗೆಯ ಮಾತನ್ನು ಸಮಸ್ತ ಜನರೂ ಅಭಿನಂದಿಸಿದರು.',
        '0.39': 'ಪ್ರಾಜ್ಞರು ಆ ಪ್ರಭುವಿನ ದೇಹವು ಮಹಾಪುರುಷಲಕ್ಷಣಗಳೆಲ್ಲದರಿಂದ ಕೂಡಿದೆ ಎಂದು ಹೇಳಲು, ಇತರರು ಅವನ ನಿತಂಬದ ಅತಿ ಸ್ಥೂಲತೆಯನ್ನು ಮಾತ್ರ (ದೋಷವಾಗಿ) ಎತ್ತಿ ಹೇಳಿದರು.',
        '0.40': 'ಪೂರ್ಣಸಭೆಯಲ್ಲಿ ಲಕ್ಷಣಶಾಸ್ತ್ರದ ಆಧಾರದಿಂದ ನಿತಂಬದ ದೋಷಗಳನ್ನು ಆ ಟೀಕಾಕಾರನು ವಿಸ್ತಾರವಾಗಿ ಹೇಳಿ ಉತ್ತರ ಪಡೆದಾಗ, ಅದನ್ನು ಸಹಿಸಲಾರದೆ ಮಧ್ವರ ದಂಡವನ್ನು ಮುರಿಯುವುದಾಗಿ ಪ್ರತಿಜ್ಞೆ ಮಾಡಿದನು — ದುಷ್ಟರ ಸ್ವಭಾವವೇ ಅದು.',
        '0.41': 'ಅಲ್ಲಿನ ತೀರ್ಥಗಳಲ್ಲಿ ಸ್ನಾನಮಾಡಿ, ಬೇಗನೆ ಶ್ರೇಷ್ಠ ತೀರ್ಥವಾದ ಕನ್ಯಾತೀರ್ಥದಲ್ಲಿ (ಕನ್ಯಾಕುಮಾರಿಯಲ್ಲಿ) ಸುಖತೀರ್ಥರು ಮುಳುಗಿ, ಸಮುದ್ರಸೇತುವಿನಲ್ಲಿಯೂ ಸ್ನಾನಮಾಡಿ ವಿಷ್ಣುವಾದ ಶ್ರೀರಾಮನಾಥನಿಗೆ ನಮಸ್ಕರಿಸಿದರು.',
        '0.42': 'ಯತಿವೇಷಧಾರಿಯಾದ ಆ ಆಸುರನು ಬರಲು, ಅವನು ದಂಡವನ್ನು ತೋರಿಸಿ ನಗುತ್ತಾ ಹೇಳಿದನು: “ಚಂಡನೇ, ನಿನ್ನಿಂದ ಈ ದಂಡವು ಮುರಿಯದಿದ್ದರೆ ನೀನು ಷಂಡ, ಅಪಂಡಿತ, ವ್ಯರ್ಥವಾಕ್ಯನು.”',
        '0.43': 'ನಾಚಿಕೆಯಿಂದ ತಲೆತಗ್ಗಿಸಿ ತನ್ನ ಸ್ವಾರ್ಥವನ್ನು ಬಯಸುತ್ತಿದ್ದ ಆ ದುಷ್ಟನನ್ನು ಆಗ ಬ್ರಾಹ್ಮಣಶ್ರೇಷ್ಠರು ಉಪೇಕ್ಷಿಸಿದರು; “ಮುಖಚಂದ್ರನಿಂದ ಜಗತ್ತನ್ನು ಆನಂದಪಡಿಸುವ ಆ ಪ್ರಾಜ್ಞನನ್ನು ಇಲ್ಲಿ ಯಾರು ದ್ವೇಷಿಸುತ್ತಾರೆ?” ಎಂದರು ವಾದಿಗಳು.',
        '0.44': 'ಅವನೊಡನೆ ಸೇರಿದ ವಿವಿಧ ವಿದ್ಯಾವಿದಗ್ಧರು ಸಭೆಗಳಲ್ಲಿ ಯಾವ ಯಾವ ವಿದ್ಯೆಗಳನ್ನು ಎತ್ತಿದರೋ, ಆ ಎಲ್ಲ ವಿದ್ಯೆಗಳಲ್ಲೂ ತೇಜಸ್ವಿಯಾದ ಆ ವಿದ್ಯಾಧಿಪತಿಯು ಪ್ರಕಾಶಿಸಿ ಅವರನ್ನು ಗೆದ್ದನು.',
        '0.45': 'ಇಲ್ಲಿ ದುರ್ಬಲರಾದ ದುರ್ಜನರ ಚಾಪಲ್ಯಗಳಿಂದ ಅಲುಗಾಡದ ಆ ಮಹಾಮನಸ್ಕ ಗುರುವು ನಾಯಿಗಳ ನಡುವೆ ಗುಹೆಯನ್ನು ಸೇರಿದ ಸಿಂಹದಂತೆ ನಾಲ್ಕು ತಿಂಗಳು (ಚಾತುರ್ಮಾಸ್ಯ) ಅಲ್ಲಿ ವಾಸಿಸಿದನು.',
        '0.46': 'ತೀಕ್ಷ್ಣಬುದ್ಧಿಯುಳ್ಳ ಅವನು ಶ್ರೀರಂಗಕ್ಕೆ ಬಂದು, ಶೃಂಗಾರಸಾಗರನೂ ಸಜ್ಜನರಿಗೆ ಮಂಗಳ ಮಾಡುವವನೂ ಕಾವೇರಿಯ ತಂಪಾದ ಗಾಳಿಯಿಂದ ಸೇವಿತನೂ ಆದ ಶೇಷಶಾಯಿ ದೇವರಿಗೆ ನಮಸ್ಕರಿಸಿದನು.',
        '0.47': 'ಆಮೇಲೆ ಹಿಂದಿರುಗಿ, ಅನೇಕ ದೇವಾಲಯಗಳಲ್ಲಿ ಸಂಚರಿಸುತ್ತಾ ಪರಮಪುರುಷನಿಗೆ ನಮಸ್ಕರಿಸಿ, ತನ್ನ ಅಮಾನುಷ ಮಹಿಮೆಗಳನ್ನು ಪ್ರಕಟಿಸುತ್ತಾ ಅವನು ಕ್ರಮವಾಗಿ ಉತ್ತರದಿಕ್ಕಿನ ಕಡೆ ಹೊರಟನು.',
        '0.48': 'ಅಲ್ಲಲ್ಲಿ ವಿಸ್ಮಿತನೇತ್ರರಾದ ಜನರಿಂದ ನೋಡಲ್ಪಡುತ್ತಾ, ಅತಿ ಸುಲಕ್ಷಣವಾದ ಆಕಾರವುಳ್ಳ ಅವನು ಪಯಸ್ವಿನೀ ತೀರದ ಶ್ರೇಷ್ಠ ಗ್ರಾಮಗಳನ್ನು ತಲುಪಿ ಒಂದು ದೇವಾಲಯವನ್ನು ಪ್ರವೇಶಿಸಿದನು.',
        '0.49': 'ಧರ್ಮದಿಂದ ಷಡಂಗಸಹಿತ ವೇದವನ್ನು ಅಧ್ಯಯನಮಾಡಿ ಅದರ ಅರ್ಥವಿವರಣೆಯ ನಿರ್ಣಯವುಳ್ಳ ಬ್ರಾಹ್ಮಣಶ್ರೇಷ್ಠರು, ಜಗತ್ತನ್ನು ದಾಟಿಸುವುದಕ್ಕಾಗಿ ಪ್ರಸಿದ್ಧನಾದ ಆ ಅಪೂರ್ವಪುರುಷನನ್ನು ತಿಳಿಯಬಯಸಿ ಬಂದರು.',
        '0.50': 'ಮುಗುಳ್ನಗೆಯ ಚಂದ್ರನಂತಿರುವ, ಕಮಲನೇತ್ರನಾದ, ಸುವರ್ಣವರ್ಣನಾದ, ಅತಿ ಮಂಗಳವಾಗಿ ಮಾತನಾಡುವ, ಆಭರಣವಿಲ್ಲದಿದ್ದರೂ ವಿಶ್ವಭೂಷಣನಾದ ಅವನನ್ನು ನೋಡಬಯಸಿ ಜನರು ಬಹಳವಾಗಿ ಸೇರಿದರು.',
        '0.51': 'ವಿದ್ಯೆಯಿಂದ ಹೊಳೆಯುವ ತಾರೆಗಳನ್ನು ಮರೆಮಾಡುವಲ್ಲಿ ಸೂರ್ಯನಂತೆ, ದುರ್ವಾದಿಗಳೆಂಬ ಆನೆಗಳ ಕುತರ್ಕವೆಂಬ ಕುಂಭಸ್ಥಳವನ್ನು ಸೀಳುವಲ್ಲಿ ಶ್ರೇಷ್ಠ ಸಿಂಹದಂತೆ, ಕುತೂಹಲಿಗಳಾದ ಜನರ ಕಣ್ಣುಗಳೆಂಬ ನೈದಿಲೆಗಳನ್ನು ಅರಳಿಸುವಲ್ಲಿ ಚಂದ್ರನಂತೆ, ಸಭಾಮಂಡಲಕ್ಕೆ ಆಭರಣವಾದ ದೇಹವುಳ್ಳ ಆನಂದತೀರ್ಥರು ಶೋಭಿಸಿದರು.',
        '0.52': 'ಹೀಗೆ ಕವಿಕುಲತಿಲಕರಾದ ತ್ರಿವಿಕ್ರಮಪಂಡಿತಾಚಾರ್ಯರ ಪುತ್ರ ನಾರಾಯಣಪಂಡಿತಾಚಾರ್ಯರು ರಚಿಸಿದ “ಆನಂದ” ಎಂಬ ಅಂಕಿತವುಳ್ಳ ಶ್ರೀಮತ್ಸುಮಧ್ವವಿಜಯ ಮಹಾಕಾವ್ಯದ ಐದನೆಯ ಸರ್ಗ ಮುಗಿಯಿತು.',
      },
    },
    'sumadhva-vijaya-06': {
      verses: {
        '0.0': 'ಆಮೇಲೆ ಅಲ್ಲಿನ ಸಭೆಯಲ್ಲಿ ಒಬ್ಬ ಹಿರಿಯನು ಐತರೇಯದ ಒಂದು ಸೂಕ್ತವನ್ನು ಸೂಚಿಸುತ್ತಾ “ತಮ್ಮಿಂದ ಈ ಸೂಕ್ತದ ಭಾವವನ್ನು ಕೇಳಲು ಸಭೆ ಬಯಸುತ್ತದೆ” ಎಂದನು.',
        '0.1': 'ವರ್ಣಗಳ ಸೌಷ್ಠವದಿಂದ ಗಂಭೀರವಾದ, ಅವಸರವಿಲ್ಲದ, ಸಮಮಾತ್ರೆಯುಳ್ಳ, ಸರಿಯಾದ ಲಕ್ಷಣಗಳುಳ್ಳ, ಮೋಡದ ಗುಡುಗಿನಂತೆ ಹೃದಯಂಗಮವಾದ ಉಚ್ಚಾರಣೆಯಿಂದ ಅದನ್ನು ಪಠಿಸಿ ಅವನು ಅರ್ಥವನ್ನು ಹೇಳಿದನು.',
        '0.2': 'ಈ ಪಠಣದ ಲಕ್ಷಣಶುದ್ಧಿಯಿಂದ ಅವನು ದೇವಗುರು ಬೃಹಸ್ಪತಿಯನ್ನೂ ಮೀರಿಸುತ್ತಾನೆ ಎಂದು ಅವರು ಮನಸ್ಸಿನಲ್ಲೇ ಒಪ್ಪಿಕೊಂಡರೂ, ಆ ಸೂಕ್ತಕ್ಕೆ ಬೇರೆ ಅರ್ಥವಿದೆ ಎಂದು ಹೇಳಿದರು.',
        '0.3': 'ಅವನು ಹೇಳಿದನು: “ಹಾಗೆಯೂ ಇರಬಹುದು; ಈ ಅರ್ಥವೂ ಸಾಧ್ಯ. ಶ್ರುತಿಗಳಿಗೆ ಮೂರು ಅರ್ಥಗಳು, ಭಾರತಕ್ಕೆ ಹತ್ತು ಅರ್ಥಗಳು, ವಿಷ್ಣುಸಹಸ್ರನಾಮಕ್ಕೆ ನೂರು ಅರ್ಥಗಳೂ ಇವೆ ಎಂದು ತಿಳಿಯಿರಿ.”',
        '0.4': 'ವಿಶಾಲಮನಸ್ಕನಾದ ಅವನು ಹೀಗೆ ಹೇಳಲು, ಅವನನ್ನು ಗೆಲ್ಲಬಯಸಿದ ಅಲ್ಲಿನ ಬ್ರಾಹ್ಮಣರು ನಗುಮುಖದಿಂದ “ಹಾಗಾದರೆ ಹರಿಯ ಒಂದು ನಾಮಕ್ಕೆ ನೂರು ಅರ್ಥಗಳನ್ನು ವರ್ಣಿಸು” ಎಂದರು.',
        '0.5': '“ನಾನು ಅದನ್ನೆಲ್ಲ ನಿಮಗೆ ವರ್ಣಿಸುತ್ತೇನೆ; ನೀವು ಅದನ್ನು ಸರಿಯಾಗಿ ಅನುವಾದಿಸಿ” ಎಂದು ಅವನು ಹೇಳಲು, ಅವರು “ಹಾಗೆಯೇ” ಎಂದು ಬಹಳ ದೃಢವಾದ ಪ್ರಯತ್ನಕ್ಕೆ ತೊಡಗಿದರು.',
        '0.6': 'ವ್ಯಾಕರಣಶಾಸ್ತ್ರವು ವಿಧಿಸಿದ ಪ್ರಕೃತಿಪ್ರತ್ಯಯಗಳ ಸಂಯೋಗದ ರೀತಿಯನ್ನು ತೋರಿಸುತ್ತಾ, ಶುದ್ಧಬುದ್ಧಿಯು ನೂರಾರು ಉಪನಿಷದ್ವಾಕ್ಯಗಳಿಂದ ಸಿದ್ಧವಾದ “ವಿಶ್ವ” ಎಂಬ ಪದದ ಅರ್ಥಗಳನ್ನು ಕೂಡಲೇ ಹೇಳಿದನು.',
        '0.7': 'ನಿಃಶಂಕನಾಗಿ ನಿರಂತರವಾಗಿ ಮಾತನಾಡುತ್ತಾ ಅವನು ನೂರು ಅರ್ಥಗಳನ್ನು ಪೂರ್ಣಗೊಳಿಸುವಷ್ಟರಲ್ಲಿ, ವರ್ಣಿಸಿದುದನ್ನು ಧಾರಣೆ ಮಾಡಲು ದುರ್ಬಲರಾದ ಅವರು ಕಳವಳಗೊಂಡರು.',
        '0.8': 'ಷಡಂಗಸಹಿತ ವೇದಗಳಲ್ಲಿ ಚತುರರೂ ಇತಿಹಾಸಗಳಲ್ಲಿ ಶಿಕ್ಷಿತರೂ ಅತಿಧೈರ್ಯಶಾಲಿಗಳೂ ಆದ ಅನೇಕರಿದ್ದರೂ, ಪ್ರಳಯದ ನೀರನ್ನು ಬಾವಿಗಳು ಹಿಡಿಯಲಾರದಂತೆ, ಅವನು ಹೇಳಿದುದನ್ನು ಅವರು ಗ್ರಹಿಸಲಾಗಲಿಲ್ಲ.',
        '0.9': '“ನಿನ್ನ ಪ್ರತಿಭೆ ದೇವತೆಗಳಲ್ಲೂ ದುರ್ಲಭ; ಚಂಚಲರಾದ ಮನುಷ್ಯರ ಮಾತೇನು? ಸೌಮ್ಯನೇ, ಸರ್ವಜ್ಞನೇ, ಕ್ಷಮಿಸು; ನಿನಗೆ ನಮಸ್ಕಾರ” ಎಂದು ಹೇಳುತ್ತಾ ಅವರು ಅವನಿಗೆ ನಮಸ್ಕರಿಸಿದರು.',
        '0.10': 'ಆಮೇಲೆ ವಿಶಾಲಮನಸ್ಕನಾದ ಅವನು ವೇದಶಾಸ್ತ್ರಚತುರರೂ ವಿದ್ಯಾಧನವನ್ನು ಬಯಸುವವರೂ ಆದ ಕೇರಳದ ಸುಂದರ ಮಂಡಲದಲ್ಲಿ ಜನಿಸಿದವರೆಲ್ಲರೊಡನೆ ಕೂಡಿ ಬೇರೊಂದು ದೇವಾಲಯಕ್ಕೆ ಹೋದನು.',
        '0.11': '“ಅಯ್ಯೋ, ಇವನು ತರ್ಕಶಾಸ್ತ್ರನಿಪುಣರಾದ ಪುರುಷರನ್ನೂ ಮತ್ತೆ ಮತ್ತೆ ಗರ್ವರಹಿತರನ್ನಾಗಿಸುತ್ತಾನೆ; ಇಲ್ಲಿ ಸೇರಿರುವ ಈ ಪ್ರದೇಶದವರಾದ ನಮ್ಮ ಗರ್ವವನ್ನು ಹೇಗೆ ಮುರಿಯದಿರುವನು?”',
        '0.12': 'ಹೀಗೆ ಆಲೋಚಿಸಿ, ಬೇರೆ ದೇಶದವರು ಮುಂದಾಳುಗಳಾಗಿದ್ದ ಆ ವಿಪ್ರಶ್ರೇಷ್ಠರು ಅವನ ಬಳಿ ಬಂದು, ದಾನಿಯನ್ನು ಹೊಗಳುವ ಮತ್ತು ಲೋಭಿಯನ್ನು ನಿಂದಿಸುವ ಸೂಕ್ತದ ಅರ್ಥವನ್ನು ಕೇಳಿದರು.',
        '0.13': 'ಅದನ್ನು ಸ್ಪಷ್ಟಪಡಿಸುತ್ತಾ “ಪೃಣೀಯಾತ್” ಎಂಬ ಶಬ್ದಕ್ಕೆ “ಪೃಣ್” ಧಾತುವೇ ಮೂಲವೆಂದು ಅವನು ಹೇಳಿದನು; ಆಮೇಲೆ ಗೆಲ್ಲಬಯಸಿ “ಪ್ರೀ” ಧಾತುವೆಂದು ಹೇಳುತ್ತಿದ್ದ ವಿಪ್ರನಿಗೆ ಅವನು ಹೀಗೆ ಹೇಳಿದನು:',
        '0.14': '“‘ಪ್ರ’ ಮೊದಲಾದ ಉಪಸರ್ಗಗಳ ಭೇದವನ್ನೂ ತಿಳಿಯದ ಮೂಢನೇ, ಧೂಳಿನಲ್ಲಿ ಅಕ್ಷರಗಳನ್ನು ಬರೆಯುತ್ತಾ ಅಭ್ಯಾಸಮಾಡು!” ಎಂದು ಗದರಿಸುತ್ತಾ ಮತ್ಸರದಿಂದ ಕಳವಳಗೊಂಡವರನ್ನು ಸ್ತಬ್ಧಗೊಳಿಸಿ ಆ ಸುಹಾಸನು ನಕ್ಕನು.',
        '0.15': 'ಆ ಪ್ರಸಂಗದ ಬಲದಿಂದ ಆ ವಿಶಾಲಹೃದಯನ ಸಕಲವಿದ್ಯಾಪಾಟವವನ್ನು ಅರಿತು, ದೇವಸಮೂಹಗಳು ಯಾರಿಗೆ ನಮಿಸುತ್ತವೆಯೋ ಆ ಅವನಿಗೆ ಅವರು ಬಹುಮಾನದಿಂದ ನಮಸ್ಕರಿಸಿದರು.',
        '0.16': 'ಒಂದು ಸಭೆಯಲ್ಲಿ, ಇಂದ್ರನಿಂದ ಆದರಿಸಲ್ಪಟ್ಟ ಕನ್ಯೆಗೆ ದೇಹಸೌಂದರ್ಯವನ್ನು ಕೊಟ್ಟುದನ್ನು ಹೇಳುವ ಶ್ರೇಷ್ಠ ಸೂಕ್ತದ ತಾತ್ಪರ್ಯವನ್ನು ವಿವರಿಸುವಾಗ, “ಅಪಾಲಾ” ಎಂಬುದಕ್ಕೆ “ಅತಿ ತರುಣಿ” ಎಂದು ಅವನು ಹೇಳಿದನು.',
        '0.17': 'ಅಲ್ಲಿನ ಒಬ್ಬ ವಿದ್ವಾಂಸನು ಆ ಪದಕ್ಕೆ “ಶ್ವಿತ್ರರೋಗವುಳ್ಳವಳು” ಎಂಬ ಅರ್ಥವೆಂದು ಹಠದಿಂದ ಹೇಳಲು, “ಒಬ್ಬ ಜ್ಞಾನಿಯು ಇಲ್ಲಿಗೆ ಬರುವನು, ಅವನನ್ನು ಕೇಳಿ” ಎಂದು ಹೇಳಿ ಅವನು ಹೊರಟುಹೋದನು.',
        '0.18': 'ಸ್ವಲ್ಪ ಕಾಲದಲ್ಲೇ ಅಂತಹದೇ ಆಕಾರದ ಒಬ್ಬ ಜ್ಞಾನಿಯು ಆ ದೇಶಕ್ಕೆ ಬಂದು, ಆಶ್ಚರ್ಯವಾಗುವಂತೆ, ವಿದ್ವಚ್ಛಿರೋಮಣಿಯು ಹೇಳಿದಂತೆಯೇ ಆ ಪದದ ಭಾವವನ್ನು ಅವರಿಗೆ ಹೇಳಿದನು.',
        '0.19': 'ಅವನಿಗೆ ಸಕಲ ವೇದವಿದ್ಯೆಗಳೂ, ಪ್ರಮಾಣಬದ್ಧವಾದ ಸಕಲ ವಾಕ್ಕುಗಳೂ ಮಾತ್ರವಲ್ಲ, ಭೂತಭವಿಷ್ಯತ್ತುಗಳ ಜ್ಞಾನವೂ ಇದೆ ಎಂದು ಆ ವಿಶಾಲಮನಸ್ಕರು ನಂಬಿದರು.',
        '0.20': 'ತಕ್ಷಣ ಯಾವ ಯಾವ ವಿಷಯ ಪ್ರಸ್ತಾಪವಾದರೂ ಅವನು ಅದನ್ನೆಲ್ಲ ಅರಿತಿದ್ದರಿಂದ, ಸಕಲ ಪಂಡಿತರ ಸಭೆಯಲ್ಲಿ ಸದಾ “ಸರ್ವಜ್ಞಯತಿ” ಎಂದು ಪ್ರಸಿದ್ಧನಾದನು.',
        '0.21': 'ಪೂರ್ಣಚಂದ್ರನು ಬೆಳದಿಂಗಳಿನಿಂದ ಆವರಿಸುವಂತೆ, ಸಜ್ಜನರೆಂಬ ನೈದಿಲೆಗಳ ಬಂಧುವಾದ ಪೂರ್ಣಪ್ರಜ್ಞನು ತಾನು ಹೋಗದ ದೇಶಗಳೆಲ್ಲವನ್ನೂ ತನ್ನ ವಿಸ್ತಾರವಾದ ಕೀರ್ತಿಯಿಂದ ಆವರಿಸಿದನು.',
        '0.22': 'ಸುಂದರವಾದ ಅನೇಕ ದೇವಾಲಯಗಳಲ್ಲಿ ಇಂದಿರಾರಮಣನಿಗೆ ವಂದನೆ ಸಲ್ಲಿಸುತ್ತಾ, ಸುವಿಚಾರಿಯಾದ ಅವನು ಸ್ವಲ್ಪ ಕಾಲದಲ್ಲೇ ರೌಪ್ಯಪೀಠಪತಿಯಾದ ಮುಕುಂದನನ್ನು ಸೇರಿದನು.',
        '0.23': 'ಅಲ್ಲಿ ಅವನು ವೇದವನ್ನು (ದ್ರೌಪದಿಯಂತೆ) ಒಬ್ಬ ಶ್ರೇಷ್ಠ ಸ್ತ್ರೀಯ ರೂಪದಲ್ಲಿ ಕಂಡನು: ಬ್ರಾಹ್ಮಣಶ್ರೇಷ್ಠರ ಬುದ್ಧಿಸಮೃದ್ಧಿಯಿಂದ ಪ್ರಕಟವಾದ ದೇಹವುಳ್ಳ, ಸುಂದರಾಂಗಿಯಾದ, ಸೂತ್ರಗಳೆಂಬ (ದಾರಗಳೆಂಬ) ಹೊಳೆಯುವ ರತ್ನಮಾಲೆಯಿಂದ ಅಲಂಕೃತಳಾದ, ಲೋಕಕ್ಕೆ ಆಭರಣವಾದ —',
        '0.24': '— ಸುಂದರವಾದ ಪಾದ, ಪದ, ಕ್ರಮಗಳಿಂದ (ಹೆಜ್ಜೆಗಳಿಂದ) ಶೋಭಿಸುವ, ಸ್ಪಷ್ಟವಾದ ವರ್ಣಗುಣಗಳಿಂದ ಸಮೃದ್ಧಳಾದ, ಉತ್ತಮ ಭಾರತವನ್ನು ಧರಿಸುವವರಿಗೆ ತಕ್ಕ ಉಡುಪುಳ್ಳ, ಸ್ವರಗಳ ವಿಶೇಷ ಶೋಭೆಯುಳ್ಳ —',
        '0.25': '— ರಾಜಸೂಯವೇ ಮೊದಲಾದ ಮಹಾಯಜ್ಞಗಳಲ್ಲಿ ತೊಡಗಿದ, ವಾಸುದೇವನ ಗುಣಗಳಲ್ಲಿ ನೆಲೆಸಿದ ಭಾವವುಳ್ಳ, ಸಕಲ ಧರ್ಮಗಳನ್ನು ಕಲಿಸುವುದರಲ್ಲಿ ದಕ್ಷಳಾದ, ಜನರಿಂದ ತಾಯಿಯಂತೆ ವಂದಿತಳಾದ —',
        '0.26': '— ನ್ಯಾಯಮಾರ್ಗವನ್ನು ಬಿಟ್ಟು ತನ್ನ ಈಶ್ವರತ್ವವನ್ನೇ ಸಾಧಿಸಲು ಹೊರಟ ಮಾಯಾವಿಯಾದ ದುಷ್ಟನಿಂದ ಸಭೆಯಲ್ಲಿ ಮುಡಿಯನ್ನು (ಉಪನಿಷತ್ತುಗಳನ್ನು) ಹಿಡಿದು ಎಳೆಯಲ್ಪಟ್ಟು ದುಃಖಿತಳಾದ —',
        '0.27': '— ಕಲಿಯ ಬಲದಿಂದ ಶುಭಮಾರ್ಗದಿಂದ ಚಲಿತರಾದ, ಅತಿ ದೀನರಾದ ಕೆಲವು ಸಜ್ಜನರಿಂದಲೂ ಉಪೇಕ್ಷಿತವಾದ ಎಳೆತದ ದುಃಖವುಳ್ಳ, ಕೆಲವರಿಂದ ಅತಿ ಶೋಕದಿಂದ ನೋಡಲ್ಪಟ್ಟ —',
        '0.28': '— “ವಾಸುದೇವ, ಧರಣೀಧರ, ನಾಥ” ಎಂದು ಗಟ್ಟಿಯಾಗಿ ಮತ್ತೆ ಮತ್ತೆ ಕೂಗುತ್ತಿದ್ದ, ಪೂರ್ಣಷಡ್ಗುಣನೂ ಅಜನೂ ದೋಷರಹಿತನೂ ಎಲ್ಲದರಿಂದ ಭಿನ್ನನೂ ಆದವನನ್ನು ಹೃದಯದಲ್ಲಿ ಧರಿಸಿದ —',
        '0.29': '— “ಜ್ಞಾನಿಗಳು ಇದನ್ನು ತಡೆಯಲಿ; ಹಾ ಹಾ, ಇದು ಧರ್ಮವಲ್ಲ!” ಎಂದು ಹೇಳುತ್ತಿದ್ದ, ಕೃಷ್ಣನಿಂದ ಅತ್ಯಂತ ಲಾಲಿತಳಾದ, ನಿರ್ದೋಷಳಾದ, ಬೇರೆ ಶರಣವಿಲ್ಲದೆ ರಕ್ಷಣೆಗಾಗಿ ಹಂಬಲಿಸುತ್ತಿದ್ದ (ವೇದಮಾತೆಯನ್ನು ಕಂಡನು).',
        '0.30': 'ಹಿಂದೆ ಭರತಶ್ರೇಷ್ಠ ಭೀಮನು ಯಜ್ಞವೇದಿಯಿಂದ ಜನಿಸಿದ ದ್ರೌಪದಿಯನ್ನು ಕಂಡಂತೆ, ವೇದಸಮೂಹವನ್ನು ತಾನೇ ಆ ಸ್ಥಿತಿಯಲ್ಲಿ ಕಂಡು, ದೃಢಬುದ್ಧಿಯ ಕರುಣಾಸಾಗರನು ದುಷ್ಟಪಕ್ಷವನ್ನು ದಮನಮಾಡುವ ಸ್ಥಿರಪ್ರತಿಜ್ಞೆಯನ್ನು ಮಾಡಿದನು.',
        '0.31': 'ಎಷ್ಟು ಅನುಭವಿಸಿದರೂ ಕುಂದದ ಶ್ರೇಷ್ಠ ಧನದಂತಿರುವ ಜ್ಞಾನವನ್ನು ದೂರದವರೆಗೆ ಹರಡಲು ಬಯಸಿ, ಅವನು ಹರಿಗೀತಾಭಾಷ್ಯವನ್ನು (ಗೀತಾಭಾಷ್ಯವನ್ನು) ರಚಿಸಿ ಹಿರಿಯ ಗುರುವಿಗೆ ಸಮರ್ಪಿಸಿದನು.',
        '0.32': 'ವಿಶಾಲಬುದ್ಧಿಯ ಆ ಹೇತುವಾದಿಯು ತೀರ್ಥಯಾತ್ರೆಗೆ ಹೋಗಲು ಅನುಮತಿ ಕೇಳಿದಾಗ, ಪುರುಷೋತ್ತಮತೀರ್ಥರು (ಅಚ್ಯುತಪ್ರೇಕ್ಷರು) ಪುರುಷೋತ್ತಮನ ರಕ್ಷಣೆಯನ್ನು ಚಿಂತಿಸುತ್ತಾ ಅನುಮತಿಯನ್ನಿತ್ತರು.',
        '0.33': 'ಮಲಯಪರ್ವತದ ಸುಗಂಧಮಾರುತದಂತೆ — ಧೂಳಿಲ್ಲದ (ರಜೋಗುಣವಿಲ್ಲದ), ಭೂಮಿಯಲ್ಲಿ ಹೊಗಳಲ್ಪಟ್ಟ, ಸದಾ ದುಂಬಿಗಳಿಂದ (ಶಿಷ್ಯರಿಂದ) ಅನುಸರಿಸಲ್ಪಟ್ಟ, ಸಜ್ಜನ ಪಥಿಕರ ತಾಪವನ್ನು ಕಳೆಯುತ್ತಾ — ವಾಯ್ವಂಶನಾದ ಅವನು ಉತ್ತರದಿಕ್ಕಿಗೆ ಹೊರಟನು.',
        '0.34': 'ಬುದ್ಧಿಶುದ್ಧಿಯನ್ನುಂಟುಮಾಡುವ ವಾಕ್ಕುಗಳ (ಕಿರಣಗಳ) ಸಮೂಹದಿಂದ ಸಮೃದ್ಧವಾದ, ಭೂಮಿಯಲ್ಲಿರುವ ಎರಡು ಬಗೆಯ ತೀರ್ಥಗಳನ್ನೂ (ಪುಣ್ಯಜಲಗಳನ್ನೂ ಗುರುಗಳನ್ನೂ) ಆ ತೀಕ್ಷ್ಣಮತಿಯು ತಾನು ಮುಳುಗುವುದರಿಂದಲೇ ಚೆನ್ನಾಗಿ ಶುದ್ಧಗೊಳಿಸಿದನು.',
        '0.35': 'ಸದಾ ವಾಸುದೇವನ ಪಾದಗಳಲ್ಲಿ ಸಂಗವುಳ್ಳವನೂ, ತೇಜಸ್ಸಿನಿಂದ ಶಿವನನ್ನೂ ಕೆಳಗೆ ಮಾಡಿದವನೂ, ಪಾಪನಾಶಕ ಕೀರ್ತಿಯುಳ್ಳವನೂ ಆದ ಅವನು ಗಂಗಾಪ್ರವಾಹವನ್ನೂ ಅತ್ಯಂತ ಮೀರಿಸಿದನು.',
        '0.36': 'ಅಲ್ಲಲ್ಲಿ ಸಂಚರಿಸುತ್ತಾ, ಸ್ಮರಣಮಾತ್ರದಿಂದಲೇ ಸುಖವನ್ನು ಕೊಡುವ, ಮೂರು ಲೋಕಗಳಿಗೂ ಆಶ್ಚರ್ಯಕರವಾದ ಕಾರ್ಯಗಳನ್ನು ಮಾಡುತ್ತಾ, ಮನುಷ್ಯರಿಗೆ ಗೋಚರವಾದ ಬದರಿಕಾಶ್ರಮದ ಸಮೀಪವನ್ನು ಅವನು ತಲುಪಿದನು.',
        '0.37': 'ಅಖಂಡ ಭರತಖಂಡವನ್ನು ಅಲಂಕರಿಸುತ್ತಾ ಇಲ್ಲಿ ನಾರಾಯಣನೆಂದು ಪ್ರಸಿದ್ಧನಾದ ಪರಮಾತ್ಮನಿಗೆ ನಮಸ್ಕರಿಸಿ, ಅಪಾರಬುದ್ಧಿಯು ಗೀತಾಭಾಷ್ಯವನ್ನು ಅವನಿಗೆ ಕಾಣಿಕೆಯಾಗಿ ಅರ್ಪಿಸಿದನು.',
        '0.38': 'ಅವನ ಪ್ರೀತಿಗಾಗಿ ಜನರನ್ನು ದೂರ ಕಳುಹಿಸಿ ಅವನ ಮುಂದೆ ಶ್ರೇಷ್ಠ ಭಾಷ್ಯವನ್ನು ಓದುತ್ತಾ, “ಉರುಕ್ರಮನ ಗೀತೆಯ ಭಾವವನ್ನು ನನ್ನ ಶಕ್ತಿಗೆ ತಕ್ಕಂತೆ ಹೇಳುತ್ತೇನೆ” ಎಂದು ಪೂರ್ಣಪ್ರಜ್ಞನು ಹೇಳಿದನು.',
        '0.39': 'ಜಗಜ್ಜನಕನು ಹೇಳಿದನು: “ಇದರ ಸೂಕ್ಷ್ಮಾರ್ಥವನ್ನೂ ಸಮಸ್ತವನ್ನೂ ಹೇಳಲು ನೀನು ಸಮರ್ಥನೇ; ನೀನು ಎಲ್ಲವನ್ನೂ ಹೇಳದಿರುವುದರಿಂದ ಇಲ್ಲಿ ‘ಶಕ್ತಿತಃ’ ಎನ್ನದೆ ‘ಲೇಶತಃ’ (ಅಂಶವಾಗಿ) ಎಂಬ ಪದವಿರಬೇಕು.”',
        '0.40': 'ಆ ಸ್ವಾಮಿಯು ಹೀಗೆ ಪ್ರವಚನ ಮಾಡಲು, ಮಲಗಿದ್ದ ಶಿಷ್ಯರೂ ಅದನ್ನು ಕೇಳಿದರು — “ಹಾಗೆಯೇ ಹೇಳಲ್ಪಡಲಿ” ಎಂದು ಹರಿಯು ನೆಲವನ್ನು ತಟ್ಟುತ್ತಾ ಮತ್ತೆ ಮತ್ತೆ ಹೇಳಿದ ಮಾತನ್ನು.',
        '0.41': 'ಅರ್ಚಾರೂಪದಲ್ಲಿ ಕುಳಿತಿದ್ದ ಪರಮಾತ್ಮನು ಮಾಡಿದ ಆ ಪದಭೇದವನ್ನು ಗ್ರಹಿಸಿ, ಅವನ ಭಾವವನ್ನರಿತ ಮಹಾಬುದ್ಧಿಯು ಎದ್ದು ಶಿಷ್ಯರಿಗೆ ಅದನ್ನು ವಿವರಿಸಿದನು.',
        '0.42': 'ಹಿಮಕ್ಕೆ ಹೆದರಿ ಮನುಷ್ಯರು ಮುಟ್ಟದ ತಣ್ಣನೆಯ ಗಂಗಾಜಲದಲ್ಲಿ ಅವನು ಪ್ರತಿದಿನ ಅರುಣೋದಯಕಾಲದಲ್ಲಿ ಸ್ನಾನಮಾಡುತ್ತಿದ್ದನು; ಏಕೆಂದರೆ ಅವನು ವಾಯುದೇವರ ಅಂಶ.',
        '0.43': 'ಶುದ್ಧಹೃದಯನಾಗಿದ್ದರೂ, ನಿತ್ಯತುಷ್ಟನಾದ ಹರಿಯ ವಿಶೇಷ ಪ್ರೀತಿಯನ್ನು ಬಯಸಿ, ಅವನು ಕಾಷ್ಠಮೌನವನ್ನೂ ಶುದ್ಧ ಉಪವಾಸವನ್ನೂ ಆಚರಿಸುತ್ತಾ ಅನಂತಮಠದಲ್ಲಿ ಪ್ರಭುವನ್ನು ಧ್ಯಾನಿಸಿದನು.',
        '0.44': 'ಅಲ್ಲಿ ಒಂದು ಮಂಡಲಕಾಲದ ನಂತರ, ಇತರರಿಗೆ ಬೆಳಕನ್ನು ಕಂಡ ಮಾತ್ರದಿಂದ ತನ್ನ ಬರುವಿಕೆ ತಿಳಿಯುವಂತಿದ್ದ ಮುಕುಂದನು, ತನ್ನ ಪಾದಗಳಲ್ಲಿ ಮನಸ್ಸಿಟ್ಟ ಮಧ್ವರನ್ನು ತನ್ನ ಆಶ್ರಮಕ್ಕೆ ಬರುವಂತೆ ಪ್ರೇರೇಪಿಸಿದನು.',
        '0.45': 'ಭಗವಂತನು ರಾತ್ರಿಯೇ ಬಂದುಹೋದ ಮೇಲೆ, ಸಹಸ್ರಕಿರಣನು ಉದಯಿಸಲು, ಮೌನಿಯಾಗಿದ್ದ, ಉತ್ತಮಚಿತ್ತನಾದ, ಶಿಷ್ಯರಿಗೆ ಬೋಧಿಸುವುದರಲ್ಲಿ ತತ್ಪರನಾದ ಕರುಣಾಮಯನು ಹೀಗೆ ಬರೆದನು:',
        '0.46': '“ಇಂತಹ ಪಾಪನಾಶಕ ಸ್ಥಳವಿಲ್ಲ; ಈ ತೀರ್ಥಜಲಕ್ಕೆ ಸಮಾನ ಜಲವಿಲ್ಲ; ವಿಷ್ಣುವಿಗೆ ಸಮಾನ ದೈವವಿಲ್ಲ; ನಮ್ಮ ಉಪದೇಶಕ್ಕೆ ಸಮಾನ ಹಿತವಿಲ್ಲ.”',
        '0.47': '“ಈ ವ್ಯಕ್ತಿ ವ್ಯಾಸರೂಪಿಯಾದ ಅಜಿತನನ್ನು ಕಾಣಬಯಸಿ ಈಗಲೇ ಹೋಗುತ್ತಾನೆ; ಇಲ್ಲಿಗೆ ಮರಳಿ ಬರುತ್ತಾನೋ ಇಲ್ಲವೋ, ಅವನೇ ಬಲ್ಲ; ನಿಮಗೆ ಮಂಗಳವಾಗಲಿ” ಎಂದು ಬರೆದು ಮಧ್ವರು ಹೊರಟರು.',
        '0.48': '“ನಾಥ, ನಾಥ, ಅಯ್ಯೋ! ಇಲ್ಲಿ ಅನಾಥರಾದ ನಮ್ಮನ್ನು ಬಿಡಬೇಡ; ಭಗವನ್, ನೀನು ಮಹಾಕರುಣಾಳು” ಎಂದು ಶಿಷ್ಯರು ಮನಸ್ಸಿನಲ್ಲಿ ಅಂದುಕೊಂಡರೂ, ಸ್ವಾಮಿಯ ಇಚ್ಛೆಗೆ ಭಂಗ ತರುವ ಭಯದಿಂದ ಹೇಳಲಿಲ್ಲ.',
        '0.49': 'ಸದ್ಗುರುವಿನ ಅಗಲಿಕೆಯನ್ನು ಸಹಿಸಲಾರದೆ, ಪೂರ್ಣಪ್ರಜ್ಞರಿಂದ ಐತರೇಯಶಾಖೆಗಳ ಶ್ರೇಷ್ಠಾರ್ಥವನ್ನು ಮೂರು ಬಾರಿ ಕೇಳಿದ್ದ ಸತ್ಯತೀರ್ಥಯತಿಯು ಅವರನ್ನು ಹಿಂಬಾಲಿಸಿದನು.',
        '0.50': 'ದುರ್ಗಮಮಾರ್ಗದಲ್ಲಿ ಹಿಂದೆ ಓಡುತ್ತಿದ್ದರೂ, ಸೂರ್ಯನು ಕೆಂಪಾಗುತ್ತಿದ್ದಾಗ, ಕಣಿವೆಗಳ ಆಚೀಚೆ ಬಹಳ ದೂರದ ಬಂಡೆಗಳ ಮೇಲೆ ಲೀಲೆಯಿಂದ ವೇಗವಾಗಿ ಹೆಜ್ಜೆಯಿಡುತ್ತಿದ್ದ ಅವರನ್ನು ಅವನು ಸೇರಲಾಗಲಿಲ್ಲ.',
        '0.51': 'ಹಿಂದಿರುಗದೆಯೇ ದೂರದಿಂದ ಕೈಸನ್ನೆಯಿಂದ ಗುರುವು ಪ್ರೇರೇಪಿಸಲು, ಭಯಗೊಂಡ ಅವನು ಆ ದಿನ ಗುರುವು ಕ್ರಮಿಸಿದ್ದ ದಾರಿಯನ್ನೆಲ್ಲ ಕ್ಷಣಮಾತ್ರದಲ್ಲಿ ದಾಟಿದನು.',
        '0.52': 'ಅಲ್ಲಿನ ಆಶ್ರಮದಲ್ಲಿ ತನ್ನವರನ್ನು ಕಂಡು, ಗುರುವಿನ ಆ ಅನುಗ್ರಹದ ಮಹಿಮೆಯನ್ನೂ ಅತ್ಯಾಶ್ಚರ್ಯಕರವಾದ ಆ ಹಾರುವಿಕೆಯನ್ನೂ ಹೇಳಿ, ಅವರೊಡನೆ ಅದನ್ನು ಸದಾ ಸ್ಮರಿಸುತ್ತಿದ್ದನು.',
        '0.53': 'ವಾನರೇಂದ್ರ ಹನುಮಂತನಂತೆ ವಾಯುವೇಗಿಯೂ, ಭೀಮಸೇನನಂತೆ ದಾನವರಿಗೆ ಭಯಂಕರನೂ, ಹೆಸರೇ ಪಾಪವನ್ನು ನಾಶಮಾಡುವವನೂ ಆದ ಅವನು ಪರ್ವತಶ್ರೇಷ್ಠನ ಶಿಖರದ ಮೇಲೆ ಹೋಗುತ್ತಾ ಮೆರೆದನು.',
        '0.54': 'ಮುಂದೆ ಸಾಗುತ್ತಾ, ನಿರ್ಭಯನಾಗಿ ಅರಳಿದ ಕಣ್ಣುಗಳಿಂದ ಅವನು ಅನೇಕ ಪ್ರಾಣಿಗಳೂ ಪಕ್ಷಿಗಳೂ ತುಂಬಿದ, ದುರ್ಗಮವಾದ, ಅಪಾರ ಹಿಮವುಳ್ಳ ಮಹಾಹಿಮಾಲಯವನ್ನು ಕಂಡನು (ಈ ಪದ್ಯವು ಯಮಕಾಲಂಕಾರದಿಂದ ಕೂಡಿದೆ).',
        '0.55': 'ಆ ಪರ್ವತವು ಸಾಕ್ಷಾತ್ ಭಗವಂತನಂತೆಯೇ ಕಂಡಿತು: ನಗುತ್ತಿರುವ ಕಮಲಸರೋವರಗಳಿಂದ (ಕಮಲೆಯಿಂದ) ಆಲಿಂಗಿತವಾದ, ಸಜ್ಜನರ ಸುಖಕ್ಕಾಗಿ ಅನಂತನ ಹಾಸಿಗೆಯಂತೆ ವಿಸ್ತಾರವಾದ, ಎತ್ತರವಾದ, ಅರಳಿದ ಹೂವುಗಳ ಗೊಂಚಲುಗಳುಳ್ಳ, ಮರಕತರತ್ನಮಯವಾದ ತಪ್ಪಲುಗಳಿಂದ ಶೋಭಿಸುವ —',
        '0.56': '— ಪಾದದ ಬಳಿ ನಮಿಸುತ್ತಿರುವ ಮಹಾಮುನಿಸಮೂಹವುಳ್ಳ, ಚಿನ್ನದಂತೆ ಹೊಳೆಯುವ ಆಕಾಶವೆಂಬ ವಸ್ತ್ರವುಳ್ಳ, ರತ್ನಸಮೂಹಗಳಿಂದಲೂ ಚಿನ್ನದ ತಪ್ಪಲುಗಳೆಂಬ ಕಡಗಗಳಿಂದಲೂ ಶೋಭಿಸುವ, ವನಮಾಲೆಯಿಂದ ಮೆರೆಯುವ ಸುಂದರವಾದ ಆ “ಧರಣೀಧರ”ನನ್ನು ಕಂಡು, ಆನಂದತೀರ್ಥರು ಆನಂದಸ್ವರೂಪನಾದ ಮುರಾರಿಯನ್ನು ಸ್ಮರಿಸಿದರು.',
        '0.57': 'ಹೀಗೆ ಕವಿಕುಲತಿಲಕರಾದ ತ್ರಿವಿಕ್ರಮಪಂಡಿತಾಚಾರ್ಯರ ಪುತ್ರ ನಾರಾಯಣಪಂಡಿತಾಚಾರ್ಯರು ರಚಿಸಿದ “ಆನಂದ” ಎಂಬ ಅಂಕಿತವುಳ್ಳ ಶ್ರೀಮತ್ಸುಮಧ್ವವಿಜಯ ಮಹಾಕಾವ್ಯದ ಆರನೆಯ ಸರ್ಗ ಮುಗಿಯಿತು.',
      },
    },
    'sumadhva-vijaya-07': {
      verses: {
        '0.0': 'ಆಮೇಲೆ ಹಿಮಾಲಯದ ಇನ್ನೊಂದು ತಪ್ಪಲಿನಲ್ಲಿ, ಬದರೀವೃಕ್ಷಗಳ ವಿಶೇಷ ತೋಪಿನಿಂದ ಅಲಂಕೃತವಾದ, ಶ್ರೀಗೆ ನೆಲೆಯಾದ, ಪ್ರಸಿದ್ಧವಾದ ಪರಮಾಶ್ರಮವನ್ನು ಆ ಸರ್ವಜ್ಞನು ಕಂಡನು.',
        '0.1': 'ಅಲ್ಲಿ ಎರಡೂ ಸಮಾನವಾಗಿ ಶೋಭಿಸಿದವು — ವಿಚಿತ್ರ ವೃಕ್ಷಗಳೂ ಬ್ರಾಹ್ಮಣರೂ: ಹಿಮ, ಮಳೆ, ಸೂರ್ಯತಾಪಗಳನ್ನು ಸಹಿಸುವ, ವಿಶಾಲ ಆಶ್ರಯದಿಂದ (ಮಹಾಯಜ್ಞಗಳಿಂದ) ಪ್ರಸಿದ್ಧವಾದ, ಪಕ್ಷಿಗಳಿಗೆ (ದ್ವಿಜರಿಗೆ) ಆಶ್ರಯವಾದ, ಆಕಾಶವನ್ನು (ವಿಷ್ಣುಪಾದವನ್ನು) ಮುಟ್ಟುವ.',
        '0.2': 'ಕಿವಿಗೆ ಅಮೃತವಾದ ಹಾಡುಗಳುಳ್ಳ ಗಿಳಿಗಳೇ ಮೊದಲಾದ ಶುಭಪಕ್ಷಿಗಳಿಂದಲೂ (ಶುಕರೇ ಮೊದಲಾದ ಮುನಿಗಳಿಂದಲೂ), ಕಮಲೆಗೆ ಅತಿಪ್ರಿಯರಾದ, ಸ್ಥಿರಹೃದಯರಾದ, ನಿರ್ಮಲರಾದ ಶ್ರೇಷ್ಠ ಹಂಸಗಳಿಂದಲೂ (ಪರಮಹಂಸರಿಂದಲೂ) ಕೂಡಿತ್ತು.',
        '0.3': 'ಹೂವಿನ ರಾಶಿಗಳಿಂದ (ಸುಮನಸ್ಕರಿಂದ) ತುಂಬಿದ, ಮನಸ್ಸಿನ ಅಭೀಷ್ಟವನ್ನು ಕೊಡುವ, ಅಲ್ಪರಿಗೆ ದುರ್ಗಮವಾದ, ಪರಸ್ಪರ ಮತ್ಸರವಿಲ್ಲದ ಪ್ರಾಣಿಗಳುಳ್ಳ ಆ ಆಶ್ರಮವು ಅಚ್ಯುತನ ಆಲಯವಾದ ವೈಕುಂಠದಂತೆಯೇ ಇತ್ತು.',
        '0.4': 'ಮೂವತ್ತೆರಡು ಶ್ರೇಷ್ಠ ಲಕ್ಷಣಗಳುಳ್ಳ ಅವನು ಆ ಆಶ್ರಮವನ್ನು ಪ್ರವೇಶಿಸುತ್ತಿರುವುದನ್ನು ಕಂಡು, ಗುಣಸಾರವನ್ನರಿತ ಋಷಿಗಳು ಕುತೂಹಲದಿಂದ ಹೀಗೆ ಚಿಂತಿಸಿದರು:',
        '0.5': '“ಅನುಪಮ ಸುವರ್ಣ ತಾಳೆಮರದಂತಿರುವ, ಕಮಲನೇತ್ರನಾದ, ನಿರ್ಮಲ ಚಂದ್ರನಂತಹ ಮುಖವುಳ್ಳ, ಗಜರಾಜನ ನಡಿಗೆಯ, ಮಹಾಬಾಹುವಾದ, ಇತ್ತ ಬರುತ್ತಿರುವ ಈ ಅಪೂರ್ವಪುರುಷನು ಯಾರು?”',
        '0.6': '“ಚಂದ್ರನು ಅತಿಶಾಂತದೇಹಿ, ಸೂರ್ಯನು ಸಂಪೂರ್ಣ ತೀಕ್ಷ್ಣ; ಹೀಗಾಗಿ ಗುಣಸಾಗರರೂಪನಾದ ಇವನಿಗೆ ಲೋಕಗಳಲ್ಲಿ ಹೋಲಿಕೆ ಸಿಗುವುದಿಲ್ಲ.”',
        '0.7': '“ಶ್ರಮರಹಿತನಾದ ಈ ಧೀರಬುದ್ಧಿಯು ಪರಮಹಂಸರ ಚಿಹ್ನೆಗಳನ್ನು ಧರಿಸಿದ್ದಾನೆ; ಮನುಷ್ಯರೂಪದಲ್ಲಿದ್ದರೂ ನಮಗೆ ಅಪಾರ ವಿಸ್ಮಯವನ್ನುಂಟುಮಾಡುತ್ತಾನೆ.”',
        '0.8': '“ಶ್ರುತಿನಾಥನನ್ನು ಕಾಣಬಯಸಿ ಯತಿರೂಪದಲ್ಲಿ ಬರುತ್ತಿರುವ ಇವನು ಚತುರನಾದ ಚತುರ್ಮುಖನೋ ಅಥವಾ ವಾಯುವೋ ಇರಬೇಕು; ಇಲ್ಲದಿದ್ದರೆ ಸರ್ವಶ್ರೇಷ್ಠ ಲಕ್ಷಣಗಳುಳ್ಳವನಾಗಿರಲಾರನು.”',
        '0.9': 'ಕುತೂಹಲಗೊಂಡ ಅವರು ಲಕ್ಷಣಗಳನ್ನು ನೋಡಿ ಹೀಗೆ ಚಿಂತಿಸುತ್ತಿರಲು, ತಡಮಾಡದೆ ನಡೆಯುತ್ತಿದ್ದ ಅವನು ಹತ್ತಿರದಲ್ಲಿ ದೇವವೃಕ್ಷಗಳಲ್ಲಿ ಶ್ರೇಷ್ಠವಾದ ಒಂದು ಮರವನ್ನು ಕಂಡನು —',
        '0.10': '— ನಯವಾದ ತೊಗಟೆಯುಳ್ಳ, ಎತ್ತರವಾದ, ವಿಸ್ತಾರವಾದ, ಅನೇಕ ಕೊಂಬೆಗಳೇ ಹೆಡೆಗಳಾಗಿ ಹೂವುಗಳೇ ರತ್ನಗಳಾಗಿರುವ — ಸ್ವಾಮಿಯ ಸೇವೆಗಾಗಿ ಹತ್ತಿರದಲ್ಲಿ ನಿಂತ ಭಗವಾನ್ ಅನಂತನಂತೆ (ಶೇಷನಂತೆ).',
        '0.11': 'ಅತಿ ವಿಚಿತ್ರವಾದ ಎಲೆಗಳುಳ್ಳ (ಗರಿಗಳುಳ್ಳ), ಬಹುವರ್ಣದ, ಸೂರ್ಯಕಿರಣಗಳನ್ನು (ಸರ್ಪಗಳನ್ನು) ತಡೆಯುವ, ಮುನಿಗಳನ್ನು ಆನಂದಪಡಿಸುವ, ಇಂದಿರಾಪತಿಗೆ ಅತಿಪ್ರಿಯವಾದ ಆ ಮರವು ಪಕ್ಷಿರಾಜ ಗರುಡನಂತಿತ್ತು.',
        '0.12': 'ಅಮೃತಸ್ವರೂಪವಾದ ಮಹಾಫಲವನ್ನು ಕೊಡುವ, ಹರಿಭಕ್ತಿಯಿಲ್ಲದವರಿಗೆ ದುರ್ಲಭವಾದ, ಸಜ್ಜನ ಪುರಾಣ ಭಾರತಗಳನ್ನು ಆಶ್ರಯಿಸಿದ, ಅನೇಕ ಶಾಖೆಗಳುಳ್ಳ ಆ ಮರವು ಮೂರ್ತಿವತ್ತಾದ ವೇದದಂತಿತ್ತು.',
        '0.13': 'ಆಮೇಲೆ ಅದರ ಅತಿ ವಿಶಾಲವಾದ, ನಿರ್ಮಲವಾದ, ಮನೋಹರವಾದ ಕಟ್ಟೆಯ ಮೇಲೆ, ಸ್ವರ್ಗದಲ್ಲಿ ದೇವತೆಗಳಂತೆ ಶ್ರೇಷ್ಠ ತಪಸ್ವಿಗಳನ್ನು ಆ ಅನಂತಬುದ್ಧಿಯು ಕಂಡನು.',
        '0.14': '— ಏಳೇಳು ಗುಂಪುಗಳಾಗಿ ಶೋಭಿಸುವ, ಅಸಂಖ್ಯರಾದ, ಗುಣಶಾಲಿಗಳಾದರೂ ತ್ರಿಗುಣಾತೀತರಾದ, ಕೋಪ ಮದ ಮೊದಲಾದವುಗಳಿಲ್ಲದ, ಭೋಗರಹಿತರಾದ, ಸದಾ ವಾಯುಭಕ್ಷಕರಾದ.',
        '0.15': 'ಅಲ್ಲಿ ಮುನಿಮಂಡಲದ ಮಧ್ಯದಲ್ಲಿರುವ, ಮೂರು ಲೋಕಗಳ ಮಂಡಲಕ್ಕೆ ಆಭರಣದಂತಿರುವ ಸತ್ಯವತೀಸುತನಾದ ಹರಿಯನ್ನು (ವ್ಯಾಸರನ್ನು) ಪೂರ್ಣಪ್ರಜ್ಞನು ಕಂಡನು.',
        '0.16': 'ತನ್ನ ಅತಿನಿರ್ಮಲ ಹೃದಯಕಮಲದಲ್ಲಿ ಅವನನ್ನು ಸದಾ ಚೆನ್ನಾಗಿ ಕಾಣುತ್ತಿದ್ದರೂ, ಈಗ ಮತ್ತೆ ಮತ್ತೆ ಹೊಸತಾಗಿ ಕಾಣುತ್ತಾ ಅವನು ವಿಸ್ಮಿತನಾಗಿ ಹೀಗೆ ಚಿಂತಿಸಿದನು:',
        '0.17': '“ಎಣಿಸಲಾಗದ ಗುಣಗಳ ಸಾಗರನೂ ನಿರ್ಮಲನೂ ಆದ ಇವನು ಕೇವಲ ನಾರಾಯಣನೇ; ವಿಧಿಯಂತೆ ಪರಾಶರರಿಂದ ಸತ್ಯವತಿಯು ಇವನನ್ನು ಇಲ್ಲಿ ಹೆತ್ತಳು.”',
        '0.18': '“ಸಜ್ಜನರ ಮೇಲಿನ ಕರುಣೆಯೆಂಬ ಮಹಾಪರ್ವತದಿಂದ ಕಡೆಯಲ್ಪಟ್ಟ ಅವನ ಮನಸ್ಸೆಂಬ ಕ್ಷೀರಸಾಗರದಿಂದ, ದೈತ್ಯಾರಿಯ ಪ್ರಿಯೆಯಾದ ಲಕ್ಷ್ಮಿಯಂತೆ, ಸುಂದರವಾದ ತ್ರಯೀಮಯಿಯಾದ ವೇದವು ಪ್ರಕಟವಾಯಿತು.”',
        '0.19': '“ಇದೇ ಸಾಗರದಿಂದ ಪುರಾಣಗಳೆಂಬ ಬಿಳಿಯ ಕಾಮಧೇನುವೂ ಮಹಾಭಾರತವೆಂಬ ಪಾರಿಜಾತವೂ ಹುಟ್ಟಿದ ಮೇಲೆ, ಶ್ರೇಷ್ಠವಾದ ಸೂತ್ರಸಮೂಹವೆಂಬ ಅಮೃತವು ತಾನಾಗಿ ಜನಿಸಿತು.”',
        '0.20': '“ಪಾಂಡುಪುತ್ರರೇ ಮೊದಲಾದ ಸಜ್ಜನರ ಮೇಲೆ ಅಡೆತಡೆಯಿಲ್ಲದ ಅಪಾರ ಅನುಗ್ರಹವನ್ನು ಮಾಡುತ್ತಾ, ಸುಂದರವಾಣಿಯುಳ್ಳ ಇವನು ಜ್ಞಾನರಕ್ಷಣೆಗಾಗಿ ಬಹುಕಾಲ ಭೂಮಿಯಲ್ಲಿ ಸಂಚರಿಸಿದನು.”',
        '0.21': '“ಈಗ ಕಲಿಕಾಲವು ನಡೆಯುವುದಕ್ಕಾಗಿ — ರಾತ್ರಿಯು ಬರಲೆಂದು ಸೂರ್ಯನು ಮರೆಯಾಗುವಂತೆ — ಭಗವಂತನು ಈ ಆಶ್ರಮದಲ್ಲಿ ವಾಸಿಸುತ್ತಾ ಜನರ ಕಣ್ಣಿಗೆ ಕಾಣುವುದನ್ನು ಬಿಟ್ಟಿದ್ದಾನೆ.”',
        '0.22': '“ಅರಳಿದ ನೀಲಕಮಲದಂತೆ ಸುಂದರಕಾಂತಿಯುಳ್ಳ, ಶ್ರೇಷ್ಠ ಕೃಷ್ಣಾಜಿನದ ಯೋಗಪೀಠದಲ್ಲಿ ಕುಳಿತಿರುವ, ನನ್ನ ಮನಸ್ಸು ಕಣ್ಣುಗಳಿಗೆ ಆನಂದ ಕೊಡುವ ಅವನ ಈ ದೇಹವು ಇಲ್ಲಿ ಕಾಣುತ್ತಿದೆ.”',
        '0.23': '“ಎಣಿಸಲಾಗದ ಗುಣಗಳಿಂದ, ತನ್ನ ಪರಿಪೂರ್ಣವಾದ ಅಸಂಖ್ಯ ಸದ್ಗುಣಗಳಿಂದ ತುಂಬಿದ, ಸಮಸ್ತ ದೋಷರಹಿತವಾದ ಇದು ಕೇವಲ ಸಚ್ಚಿದಾನಂದಮಯವೇ.”',
        '0.24': '“ಕಮಲೆ, ಕಮಲಾಸನ, ವಾಯು, ಗರುಡ, ಶೇಷ, ಶಿವ, ಇಂದ್ರ ಮೊದಲಾದವರು ಇವನ ಪಾದಕಮಲದ ಧೂಳನ್ನು ತಲೆಯಲ್ಲಿ ಧರಿಸುತ್ತಾರೆ; ಆಹಾ, ನಾನೂ ಅದನ್ನು ಮತ್ತೆ ಮತ್ತೆ ಹೊರುತ್ತೇನೆ!”',
        '0.25': '“ಧ್ವಜ, ವಜ್ರ, ಅಂಕುಶ, ಪದ್ಮಗಳ ಚಿಹ್ನೆಗಳುಳ್ಳ, ಸ್ವಭಾವತಃ ಕೆಂಪಾಗಿದ್ದರೂ ಭಕ್ತರ ಮನಸ್ಸಿನ ಅನುರಾಗವನ್ನು ಒತ್ತುವುದರಿಂದ ಕೆಂಪಾದಂತಿರುವ ಪ್ರಭುವಿನ ಪಾದದ್ವಯಕ್ಕೆ ನಮಸ್ಕರಿಸುತ್ತೇನೆ.”',
        '0.26': '“ವಿಷ್ಣುಪದವನ್ನೇ ಆಶ್ರಯಿಸಿರುವ (ಸೂರ್ಯನು ಆಕಾಶವನ್ನು ಆಶ್ರಯಿಸಿರುವಂತೆ), ತಮ್ಮ ಕಾಂತಿಯಿಂದ ಹೊರಗಿನ ಒಳಗಿನ ಎರಡೂ ಕತ್ತಲೆಗಳನ್ನು ನಾಶಮಾಡುವ ಇವನ ಉಗುರುಗಳು ಉದಯಸೂರ್ಯನನ್ನೂ ಗೆಲ್ಲುತ್ತವೆ.”',
        '0.27': '“ಕೋಮಲವಾದ ಅಂಗಾಲು ಬೆರಳುಗಳುಳ್ಳ, ಮರೆಯಾದ ಗಿಣ್ಣುಗಳುಳ್ಳ ಇವನ ಪಾದಗಳಿಗೆ, ಒಂದಕ್ಕೊಂದನ್ನು ಬಿಟ್ಟು ಬೇರೆ ಹೋಲಿಕೆಯನ್ನು ಶ್ರೇಷ್ಠಕವಿಗಳೂ ಕಾಣರು.”',
        '0.28': '“ಉಚಿತವಾದ ಗುರುತ್ವವನ್ನು (ಗೌರವವನ್ನು) ಧರಿಸಿದ, ಕ್ರಮವಾಗಿ ಸಣ್ಣಗಾಗುವ, ಶುಚಿಯಾದ, ತೇಜಸ್ವಿಯಾದ, ಸುವೃತ್ತವಾದ (ಸದಾಚಾರಿಯಾದ) ಪ್ರಭುವಿನ ಈ ಜಂಘಾದ್ವಯವು ಭಜಿಸುವವರಿಗೆ ಸಮಾನರೂಪವನ್ನು ಕೊಡುತ್ತದೆ.”',
        '0.29': '“ಅಚಲಾಸನವನ್ನು ಕಟ್ಟುವ ಯೋಗಪಟ್ಟಿಕೆಯೆಂಬ ಶ್ರೇಷ್ಠ ಪಟ್ಟಿಯು, ಒಮ್ಮೆ ಪಡೆದರೆ ಇಷ್ಟವನ್ನು ಕೊಡುವ ಹರಿಯನ್ನು ಸುತ್ತಲೂ ನಿರಂತರ ಆಲಿಂಗಿಸುತ್ತದೆ; ಅದು ಧನ್ಯತಮವೆಂದು ನನ್ನ ಅಭಿಪ್ರಾಯ.”',
        '0.30': '“ಸುಂದರ ಕಾಂತಿಯಿಂದ ಹೊಳೆಯುವ, ವಿಶಾಲವಾದ ಶ್ರೇಷ್ಠ ನಿತಂಬವನ್ನು ಆವರಿಸಿರುವ ಮನೋಹರವಾದ ಶ್ರೇಷ್ಠ ಕೃಷ್ಣಾಜಿನದಿಂದ ಅವನು ಪರಮಾಶ್ಚರ್ಯವಾಗಿ ಶೋಭಿಸುತ್ತಾನೆ.”',
        '0.31': '“ಸಣ್ಣದಾದ, ಆಳವಾದ ಸುಂದರ ನಾಭಿಯಿಂದ ಶೋಭಿಸುವ, ವಳಿಗಳುಳ್ಳ, ಕೃಶವಾದ, ಅತಿಸುಂದರವಾದ, ಮೃದುವಾದ ಈ ಹೊಟ್ಟೆಯಲ್ಲಿ ಪದ್ಮನಾಭನು ಬ್ರಹ್ಮಾಂಡಮಂಡಲವನ್ನು ಧರಿಸಿದ್ದಾನೆ.”',
        '0.32': '“ಸಜ್ಜನರ ಅಭ್ಯುದಯಕ್ಕೆ ಕಾರಣವಾದ ವಿಶಾಲವಾದ ವಕ್ಷಸ್ಥಳದಲ್ಲಿ ಮುನಿವಂಶಶೇಖರನು ಎರಡನ್ನು ಧರಿಸಿದ್ದಾನೆ: ತ್ರಯೀಮಯವಾದ ನಿರ್ಮಲ ಯಜ್ಞೋಪವೀತ ಮತ್ತು ಶ್ರೇಷ್ಠವಾದ ಬ್ರಹ್ಮಸೂತ್ರ (ಎರಡೂ ಅರ್ಥಗಳಲ್ಲಿ).”',
        '0.33': '“ಸಮಾನರಿಲ್ಲದ, ಅಧಿಕರಿಲ್ಲದ ತನ್ನ ತಂದೆಯಾದ ಪ್ರಭುವಿಗೆ ಬ್ರಹ್ಮನು ಸೂರ್ಯರಾಶಿಯ ಕಾಂತಿಯುಳ್ಳ, ಮೂರು ಲೋಕಗಳ ವಿಜಯಧ್ವಜವಾದ, ಕಂಠದಲ್ಲಿರುವ ಈ ಆಭರಣವನ್ನು ಅರ್ಪಿಸಿದನು.”',
        '0.34': '“ಚಕ್ರ ಪದ್ಮಗಳ ಲಕ್ಷಣಗಳಿಂದ ಹೊಳೆಯುವ ಕೋಮಲವಾದ ಕೆಂಪು ಕರಕಮಲಗಳಿಗೂ, ವಿಶಾಲವೂ ಪುಷ್ಟವೂ ದುಂಡಾದವೂ ಆದ ತೋಳುಗಳಿಗೂ ನಾವು ಹೋಲಿಕೆಯನ್ನೇ ಕಾಣೆವು.”',
        '0.35': '“ಶ್ರೇಷ್ಠವಾದ ಜ್ಞಾನಮುದ್ರೆಯಲ್ಲಿರುವ ಪ್ರಭುವಿನ ಒಂದು ಕೈ ಭಜಿಸುವವರ ಅಜ್ಞಾನವನ್ನು ಕತ್ತರಿಸುತ್ತದೆ; ಮೊಣಕಾಲಿನ ಮೇಲಿಟ್ಟ ಇನ್ನೊಂದು ಕೈ ಅಪಾರ ಭಯವನ್ನು ನಾಶಮಾಡಿದ ಪರಮಮಂಗಳವಾದುದು.”',
        '0.36': '“ತಾನಾಗಿ ನಿರಂತರ ಹರಿಯುವ ಮೂರು ವೇದಗಳಿಂದಲೇ ಗುರುತಿಸಲ್ಪಟ್ಟಂತೆ, ಶಂಖವನ್ನು ಅಣಕಿಸುವ, ಮೂರು ಸುಂದರ ರೇಖೆಗಳುಳ್ಳ ಗುರುವಿನ ಕಂಠವು ಕಾಣುತ್ತಿದೆ.”',
        '0.37': '“ದೇವಶಿರೋಮಣಿಯ ಈ ಮುಖವು ತನ್ನ ಶೋಭೆಯಿಂದ, ಎಲ್ಲ ಕಳಂಕ ಕಪ್ಪುಗಳೂ ಹೋದ ಚಂದ್ರಸಮೂಹದ ಮಹಾವಿಲಾಸವನ್ನೂ ಕೆಳಗೆ ಮಾಡುತ್ತದೆ.”',
        '0.38': '“ಅವನು ನಗುವಾಗ ಕೆಂಪು ತುಟಿಗಳ ಕಾಂತಿಯೊಡನೆ ಹೊಳೆಯುವ ಪರಮಸುಂದರವಾದ ಬಿಳಿಯ ಹಲ್ಲುಗಳ ಸಾಲು, ಕೆಂಪುರತ್ನದ ಹಾಳೆಗಳ ನಡುವೆ ಹೊಳೆಯುವ ಹೊಸ ಮುತ್ತಿನ ಸರವನ್ನೂ ನಾಚಿಸುತ್ತದೆ.”',
        '0.39': '“ಆಹಾ, ಬ್ರಾಹ್ಮಣಸಮೂಹವು ಕುತೂಹಲದಿಂದ ಕೇಳಿದ ಸಾವಿರಾರು ಶ್ರೇಷ್ಠ ಪ್ರಶ್ನೆಗಳಿಗೆ ಶ್ರುತಿನಾಥನ ಈ ವಾಣಿಯು ಒಂದೇ ಪದದಲ್ಲಿ ಉತ್ತರ ಕೊಡುತ್ತದೆ!”',
        '0.40': '“ಕಮಲದಂತೆ ವಿಶಾಲ ನೇತ್ರಗಳುಳ್ಳವನ ಲೋಕಾನಂದಕರವಾದ ಮುಗುಳ್ನಗೆಯಿಂದ ಕೂಡಿದ ಈ ದೃಷ್ಟಿಯು ನನ್ನ ಬಳಿ ಬಂದು ಮುದ್ದಿಸುತ್ತಾ ಅಪ್ಪಿಕೊಂಡು ನನ್ನನ್ನು ಪರಿಪೂರ್ಣನನ್ನಾಗಿಸುತ್ತದೆ.”',
        '0.41': '“ಅವನ ಕಿವಿಯ ಬಳಿ ಹೊಳೆಯುವ ಮುದ್ದಿನ ತುಲಸಿಯು ‘ಕಮಲವೇ ಮೊದಲಾದ ಹೂವುಗಳು ಮತ್ಸರದಿಂದ ನನ್ನ ನಾಥನ ಬಳಿಯ ಸ್ಥಾನವನ್ನು ಕಸಿಯದಿರಲಿ’ ಎಂದು ಪಿಸುಗುಟ್ಟುವಂತಿದೆ.”',
        '0.42': "“ಶಿವ ಬ್ರಹ್ಮರೂ ಸೇರಿದಂತೆ ಲೋಕಗಳ ಪಾಲನೆ, ಸಂಹಾರ, ಉತ್ಪತ್ತಿ ಮೊದಲಾದುವೆಲ್ಲವೂ ಭುವನಪ್ರಭುವಿನ ಈ ಹುಬ್ಬುಗಳ ಅಲ್ಪ ಚಲನೆಯಿಂದಲೇ ಆಗುತ್ತವೆ.”",
        '0.43': '“ತ್ರಿಲೋಕತಿಲಕನಾದ ಅವನ ಹಣೆಯ ಮೇಲಿನ ಈ ತಿಲಕವು ಇಂದ್ರನೀಲಪರ್ವತದ ಶಿಖರದಲ್ಲಿ ಹೊಳೆಯುವ ಕೆಂಪುರತ್ನಗಳ ಸಾಲಿನಂತೆ ಪರಮಶೋಭೆಯನ್ನು ಪಡೆದಿದೆ.”',
        '0.44': '“ಉತ್ತಮ ಮಿಂಚಿನ ವಲಯವುಳ್ಳ ಹೊಸ ಮೋಡವನ್ನು ಅಣಕಿಸುವ, ಜಟಾಮಂಡಲದಿಂದ ಅಲಂಕೃತವಾದ ಜಗದ್ಗುರುವಿನ ದೇಹವನ್ನು ಕಂಡು ನಾನು ಕೃತಾರ್ಥನಾದೆನು.”',
        '0.45': '“ನಿರಂತರ ಎಣಿಸುತ್ತಿರುವ ರಮೆಯೂ ಇವನ ಕಾಲ್ಬೆರಳ ಉಗುರಿನ ಧೂಳಿನಲ್ಲಿ ಹೊಳೆಯುವ ಅನಂತ ಸದ್ಗುಣಗಳನ್ನು ಎಣಿಸಲಾರಳು; ಇವನ ಪರಮಗುಣಗಳನ್ನು ಬೇರೆ ಯಾರು ಹೇಳಬಲ್ಲರು?”',
        '0.46': '“ಒಂಬತ್ತು ಆವರಣಗಳುಳ್ಳ ಬ್ರಹ್ಮಾಂಡವನ್ನೂ ಮನೆಯೆಂಬ ಭಾವದಿಂದ ಕಂಡು ವಿಸ್ಮಯವಿಲ್ಲದಿದ್ದ ನನಗೆ, ಸದ್ಗುರುವಿನ ಈ ದೇಹವನ್ನು ಕಂಡು ಕುತೂಹಲವಾಗಿರುವುದು ಆಶ್ಚರ್ಯವಲ್ಲ.”',
        '0.47': 'ಹೀಗೆ ಚಿಂತಿಸುತ್ತಾ ಹೊರಗಿನ ದಾರಿಯನ್ನು ದಾಟಿದ ಆ ಮಹಾಬುದ್ಧಿಯು, ಮನಸ್ಸು ಕಣ್ಣುಗಳಿಂದ ಮೊದಲೇ ಸೇರಿದ್ದ ವೇದರಾಜನನ್ನು ಈಗ ದೇಹದಿಂದಲೂ ಸೇರಿದನು.',
        '0.48': 'ಗುರುಭಕ್ತಿಯ ಭಾರದಿಂದ ಬಾಗಿದ ದೇಹವುಳ್ಳ ಅವನು ಕೂಡಲೇ ಕೈಮುಗಿದು, ಕ್ಷಣಕಾಲ ಕಣ್ಣುಗಳನ್ನು ಅರೆಮುಚ್ಚಿ, ಗುರುವನ್ನು ಮಾತ್ರ ವಂದಿಸಿದನು.',
        '0.49': 'ವಿನಯವೆಂಬ ಆಭರಣದಿಂದ ಅಲಂಕೃತನಾಗಿ, ಸ್ಪಷ್ಟವಾದ ಅಷ್ಟಾಂಗ ನಮಸ್ಕಾರದಿಂದ ಆ ಭಾಗ್ಯಶಾಲಿಯಾದ ಭಗವಾನ್ ಪರಮಪೂಜ್ಯನ ಪಾದಕಮಲಗಳಿಗೆ ನಮಸ್ಕರಿಸಿದನು.',
        '0.50': 'ಸಕಲ ಸದ್ಗುಣಗಳಿಂದ ಕೂಡಿದ ಪ್ರಿಯತಮನು ನಮಸ್ಕರಿಸಿರುವುದನ್ನು ಕಂಡು, ಪರಾಶರಪುತ್ರನು ಬೇಗನೆ ಚಾಚಿದ ಸುಂದರವಾದ ಎರಡು ಕೈಗಳಿಂದ ಅವನನ್ನು ಮೇಲೆತ್ತಿದನು.',
        '0.51': 'ಪ್ರೇಮಾಮೃತದಿಂದ ತುಂಬಿದ ಮನಸ್ಸುಳ್ಳ, ಮುಗುಳ್ನಗೆಯ ಮುಖವುಳ್ಳ, ಅರಳಿದ ಕಣ್ಣುಗಳುಳ್ಳ ಶ್ರುತೀಶ್ವರನು ಅಮಿತಪ್ರಜ್ಞನನ್ನು ಬೇಗನೆ ಹಿಡಿದು ಅಪ್ಪಿಕೊಂಡನು.',
        '0.52': 'ಯಮನ ತಂಗಿಯಾದ ಯಮುನೆಯಿಂದ ಎದ್ದ ಬಲವಾದ ಕಪ್ಪು ಮೋಡವು ಜಾಂಬೂನದ ನದಿಯ ಚಿನ್ನದ ಜಲದೊಡನೆ ಸೇರಿದರೆ, ಆಗ ಸುವರ್ಣಕಾಂತಿಯ ಮಧ್ವರನ್ನು ಅಪ್ಪಿದ ನೀಲವರ್ಣದ ವ್ಯಾಸರನ್ನು ಅದಕ್ಕೆ ಹೋಲಿಸಬಹುದು.',
        '0.53': 'ಶ್ರೇಷ್ಠ ಬ್ರಾಹ್ಮಣವಂಶಗಳಲ್ಲಿ ಜನಿಸಿದ ಈ ಇಬ್ಬರು ಹರಿಗಳು ರಾಜಾಭರಣಗಳನ್ನು ಧರಿಸಿದ್ದರೆ, ಹಿಂದೆ ರಾಜವಂಶಗಳಲ್ಲಿ ಜನಿಸಿ ಪರಸ್ಪರ ಅಪ್ಪಿಕೊಂಡ ತಮ್ಮ ಪೂರ್ವರೂಪಗಳಾದ ಕೃಷ್ಣ ಭೀಮರಿಗೆ ಸ್ಪಷ್ಟವಾಗಿ ಸಮಾನರಾಗುತ್ತಿದ್ದರು.',
        '0.54': '“ಲೋಕಪಿತನ ಪಿತನಾದ ತನ್ನ ತಂದೆಯಿಂದ ಶುಕನೂ ಇಂತಹ ಸಂಪೂರ್ಣ ವಾತ್ಸಲ್ಯವನ್ನು ಪಡೆಯಲಿಲ್ಲ; ಅದನ್ನು ಈ ಧನ್ಯನು ಪಡೆದನು!” ಎಂದು ತಪಸ್ವಿಗಳು ಅತ್ಯಂತ ಕುತೂಹಲಪಟ್ಟರು.',
        '0.55': 'ಗುರುವಿನ ಅಭಿಪ್ರಾಯವನ್ನರಿತ ಸುಸಂಸ್ಕೃತರಾದ ಅವನ ಶಿಷ್ಯರು, ಮುಕುಂದನ ದಾಸರು ಚತುರ್ಮುಖನಿಗೆ ಕೊಡುವಂತೆ, ವಿನಯದಿಂದ ಅವನಿಗೆ ತಕ್ಕ ಆಸನವನ್ನು ಕೊಟ್ಟರು.',
        '0.56': 'ಸತ್ಯವಾಕ್ಕುಳ್ಳ ಸತ್ಯವತೀಸುತನು “ಕುಳಿತುಕೋ” ಎಂದು ಹೇಳಿ ತಾನು ಕುಳಿತ ಮೇಲೆ, ಮಂದಹಾಸ ದೃಷ್ಟಿಗಳಿಂದ ಆ ಮುನೀಂದ್ರರನ್ನು ಸನ್ಮಾನಿಸುತ್ತಾ ಅವನು ಕುಳಿತನು.',
        '0.57': 'ಅವನನ್ನು ಶ್ರೇಷ್ಠನೆಂದು ಅರಿತ ವಿಧಿಜ್ಞರಾದ ಮುನಿಸಮೂಹಗಳು ಅವನಿಗೆ ವಿಧಿವತ್ತಾಗಿ ಸನ್ಮಾನ ಮಾಡಿದರು; ಈ ಇಬ್ಬರು ಕವೀಂದ್ರರ ಕಿವಿಗಿಂಪಾದ ಸಂವಾದವನ್ನು ಕೇಳಿ ಪರಮಾನಂದವನ್ನು ಪಡೆದರು.',
        '0.58': 'ಸಜ್ಜನರಿಗಾಗಿ ಆನಂದ ವಿಜ್ಞಾನಮೂರ್ತಿಗಳಾಗಿ ಭೂಮಿಗೆ ಬಂದ, ವೇದವ್ಯಾಸ ಆನಂದತೀರ್ಥರೆಂಬ ಹೆಸರಿನ ವಿಷ್ಣು ವಾಯುಗಳೆಂಬ ಆ ಇಬ್ಬರು ದೇವರು ಆ ಆಶ್ರಮದಲ್ಲಿ ಜಾಜ್ವಲ್ಯಮಾನರಾಗಿ ಬೆಳಗಿದರು.',
        '0.59': 'ಹೀಗೆ ಕವಿಕುಲತಿಲಕರಾದ ತ್ರಿವಿಕ್ರಮಪಂಡಿತಾಚಾರ್ಯರ ಪುತ್ರ ನಾರಾಯಣಪಂಡಿತಾಚಾರ್ಯರು ರಚಿಸಿದ “ಆನಂದ” ಎಂಬ ಅಂಕಿತವುಳ್ಳ ಶ್ರೀಮತ್ಸುಮಧ್ವವಿಜಯ ಮಹಾಕಾವ್ಯದ ಏಳನೆಯ ಸರ್ಗ ಮುಗಿಯಿತು.',
      },
    },
    'sumadhva-vijaya-08': {
      verses: {
        '0.0': 'ಪ್ರತಿಭೆಯ ಪ್ರಭೆಯೇ ಮೊದಲಾದ ತನ್ನ ಸದ್ಗುಣಗಳಿಂದ ತಪಸ್ವಿಗಳ ಮನಸ್ಸನ್ನು ಅತಿವಿಸ್ಮಯಕ್ಕೆ ಒಯ್ಯುತ್ತಾ, ಆ ವಿಶಾಲಬುದ್ಧಿಯು ಒಮ್ಮೆ ಕಾಡಿನ ಏಕಾಂತಸ್ಥಳದಲ್ಲಿ ವೇದನಾಯಕನನ್ನು ಮೆಲ್ಲನೆ ಸಮೀಪಿಸಿದನು.',
        '0.1': 'ಶೇಷನಿಗಿಂತಲೂ ವಿಶೇಷವಾಗಿ ವರ್ಣಿತವಾದ ಎಲ್ಲವನ್ನೂ ಅರಿಯುವ ಇವನಿಗೆ ಶಿಷ್ಯತ್ವವೂ, ಮಹಾಮನಸ್ಕನಿಗೆ ಗುರುವಾಗುವುದು ಸತ್ಪತಿಗೂ ಉಚಿತವೇ ಎಂದು ದೇವತೆಗಳು ಆ ಸಮೀಪಿಸುವಿಕೆಯನ್ನು ಮನ್ನಿಸಿದರು.',
        '0.2': 'ಮೊದಲೇ ತುಂಬಿದ್ದ ಮನಸ್ಸನ್ನು ಈ ಕೃಷ್ಣನು (ವ್ಯಾಸರು) ಪರಮಾರ್ಥಗಳಿಂದ ಮತ್ತೆ ತುಂಬಿದನು; ಹಿಂದಿನಿಂದಲೇ ತನ್ನ ನೆಲೆಯಾಗಿದ್ದ, ನಗರದಂತೆ ವಿಶಾಲವಾದ ಭಗವಂತನ ಮನಸ್ಸನ್ನು ಮಧ್ವರು ಗ್ರಹಿಸಿದರು — ಇದು ಆಶ್ಚರ್ಯ!',
        '0.3': 'ಇತಿಹಾಸ, ಸುಂದರ ಪುರಾಣ, ಸೂತ್ರ, ಪ್ರಿಯವಾದ ಪಂಚರಾತ್ರಗಳ ನಿಜಭಾವದೊಡನೆ ಕೂಡಿದ, ಅಸಂಖ್ಯ ಆಗಮಗಳ ಪರಮಾರ್ಥವನ್ನು ಆ ಅನಂತಹೃದಯನು ಅನಂತನಿಂದ ಬೇಗನೆ ಕೇಳಿದನು.',
        '0.4': 'ಋಜುಗಣಶ್ರೇಷ್ಠನಾದ ಇವನು ಅನಂತಜನ್ಮಗಳಲ್ಲಿ ಅದೆಲ್ಲವನ್ನೂ ತಾನೇ ಚೆನ್ನಾಗಿ ಅರಿತಿದ್ದರೂ, ಶೇಷಶಾಯಿಯು ತನ್ನ ಮಹಾನುಗ್ರಹಬಲದಿಂದ ಅವನ ಬುದ್ಧಿಯನ್ನು ಇನ್ನಷ್ಟು ವಿಶೇಷಗೊಳಿಸಿದನು.',
        '0.5': 'ಆಮೇಲೆ ಬಾದರಾಯಣರ ಸಹವಾಸಸಂಪತ್ತಿನೊಡನೆ ಆ ಅಮಿತಮನಸ್ಕನು, ಬೇರೊಂದು ಆಶ್ರಮದಲ್ಲಿ ಶೋಭಿಸುವ ನಾರಾಯಣನೆಂದು ಕರೆಯಲ್ಪಡುವ ಹರಿಯ ಇನ್ನೊಂದು ರೂಪಕ್ಕೆ ನಮಿಸಲು ಹೊರಟನು.',
        '0.6': 'ಆ ಶ್ರೇಷ್ಠಾಶ್ರಮದಲ್ಲಿ, ಹೊಗೆಯಿಲ್ಲದೆ ಉರಿಯುವ ಅಗ್ನಿಯಂತೆ ಬೆಳಗುವ, ಶ್ರೇಷ್ಠ ನಾರುಮಡಿ ಮೌಂಜೀಮೇಖಲೆಗಳನ್ನು ಧರಿಸಿದ, ಹೊಳೆಯುವ ಜಟಾವಲಯವುಳ್ಳ ಆದಿಪುರುಷನನ್ನು ಆ ಮಹಾಬುದ್ಧಿಯು ಕಂಡನು.',
        '0.7': 'ಜಯಿಸಲು ಅತಿಕಷ್ಟವಾದ ಇಂದ್ರಿಯಜಯವೇ ಮೊದಲಾದ ತಪಸ್ಸಿನಿಂದ ಸದಾ ಕಾಡಿನಲ್ಲಿ ವಾಸಿಸುತ್ತಿರುವಂತೆ ತೋರಿದರೂ, ಅವನು ತನ್ನ ಸ್ವರೂಪಭೂತವಾದ ನಿರಪೇಕ್ಷ ನಿರ್ಮಲ ಅಪಾರ ಆತ್ಮಸುಖದಲ್ಲಿ ನಿರಂತರ ರಮಿಸುತ್ತಾನೆ.',
        '0.8': 'ಕಮಲದ ಕಾಂತಿಯನ್ನೂ ಮೀರಿಸುವ, ಅರಳಿದ ಕಣ್ಣುಗಳಿಂದ, ಅಧರ್ಮಿಗಳಿಗೆ ದುರ್ಲಭನಾದ ಆ ಧರ್ಮಪುತ್ರನನ್ನು ವಿಸ್ಮಯದಿಂದ ನೋಡುತ್ತಾ ಆ ವಿಶಾಲಮನಸ್ಕನು ಮನಸ್ಸಿನಲ್ಲಿ ಹೀಗೆ ಸ್ಮರಿಸಿದನು:',
        '0.9': '“ಚತುರ್ಮುಖನೇ ಮೊದಲಾದವರೊಡನೆ ಹದಿನಾಲ್ಕು ಲೋಕಗಳನ್ನು ಪ್ರಳಯಕ್ಕೆ ಒಯ್ದು, ಕಮಲೆಯೊಡನೆ ಮಾತ್ರ ಬೆಳಗುವ ಪರಮನಾದ ಪುರಾಣಪುರುಷನು ಇವನೇ.”',
        '0.10': '“ತ್ರಿಗುಣಾತ್ಮಕ ಪ್ರಕೃತಿಯಿಂದ ಮಹತ್ತತ್ತ್ವವನ್ನೂ, ಅದರಿಂದ ಮೂರು ಬಗೆಯ ಅಹಂಕಾರವನ್ನೂ, ಅದರಿಂದ ದೇವತೆಗಳನ್ನೂ ಇಂದ್ರಿಯಗಳನ್ನೂ, ಪಂಚಭೂತಗಳನ್ನೂ, ಇವುಗಳಿಂದ ಬ್ರಹ್ಮಾಂಡಮಂಡಲವನ್ನೂ, ಇಲ್ಲಿ ಲೋಕಗಳನ್ನೂ ಈ ಭಗವಂತನು ಸೃಷ್ಟಿಸಿದನು.”',
        '0.11': '“ಬ್ರಹ್ಮ, ವಾಯು, ಗರುಡ, ಇಂದ್ರ, ಶಿವ ಮೊದಲಾದ ಈಶರು, ಪ್ರಜಾಪತಿಗಳು, ದೇವತೆಗಳು, ಅವರ ಅನುಚರರು, ಮನುಷ್ಯರು, ಅಸುರರು ಮೊದಲಾದವರನ್ನು ಇವನು ಲೀಲೆಯಿಂದ ಸದಾ ಸೃಷ್ಟಿಸುತ್ತಾನೆ, ಪಾಲಿಸುತ್ತಾನೆ, ಸಂಹರಿಸುತ್ತಾನೆ, ಅವರವರ ಗತಿಗೆ ಸೇರಿಸುತ್ತಾನೆ.”',
        '0.12': '“ಎಣಿಸಲಾಗದ ಸದ್ಗುಣಗಳ ಸಮೂಹವುಳ್ಳ, ದೋಷರಹಿತನಾದ, ಉಪಚಾರವಿಲ್ಲದೆ ನಿಜವಾಗಿಯೇ ಎಲ್ಲವನ್ನೂ ತನ್ನ ವಶದಲ್ಲಿಟ್ಟುಕೊಂಡ ಇವನು, ತನ್ನವರ ಮುಕ್ತಿಗಾಗಿ ಸ್ಮರಣ, ಕೀರ್ತನ, ನಮಸ್ಕಾರಗಳಿಗೆ ವಿಷಯನಾಗಲು ಅನೇಕ ರೂಪಗಳನ್ನು ಧರಿಸುತ್ತಾನೆ.”',
        '0.13': '“ದೇವೇಶ್ವರನಾದ ಈ ಪ್ರಭುವು ಹಿಂದೆ ಹಯಗ್ರೀವರೂಪದಿಂದ ವೇದಗಳನ್ನು ಕದ್ದ ಪುರಾತನ ಸಜ್ಜನಶತ್ರುವನ್ನು ಕೊಂದು, ಚತುರ್ಮುಖನಿಗೆ ನಾಲ್ಕು ವೇದಗಳನ್ನು ಕೊಟ್ಟನು.”',
        '0.14': '“ಇಂದ್ರಶತ್ರುವಿನ (ಹಿರಣ್ಯಾಕ್ಷನ) ಭುಜಬಲದ ಎಳೆತದಿಂದ ಜಲದಲ್ಲಿ ಮುಳುಗಿದ ಭೂಮಿಯನ್ನು ಅವನು ವರಾಹರೂಪದಿಂದ ಮೇಲೆತ್ತಿದನು; ಅಲೆಗಳುಳ್ಳ ಸಮುದ್ರದಲ್ಲಿ ಕೂರ್ಮರೂಪದಿಂದ ತನ್ನವರನ್ನು ರಕ್ಷಿಸಿದನು.”',
        '0.15': '“ಇಷ್ಟಜನರ ಭಯವನ್ನು ಭಂಗಿಸುವ ಈ ನರಸಿಂಹನು ಕೋಪೋದಯದಲ್ಲಿ ಚಕ್ರದಂತಿರುವ ಉಗುರುಗಳ ತೇಜಸ್ಸಿನಿಂದ ಭಯಂಕರನೂ ಮಹಾಬಲನೂ ಆದ ತನ್ನ ಶತ್ರುವನ್ನು ಕ್ಷಣದಲ್ಲಿ ಸೀಳಿದನು.”',
        '0.16': '“ಸುಂದರ ಬಾಲ್ಯವುಳ್ಳ ಈ ವಾಮನನು ತನ್ನ ಪ್ರತಿಭೆಯಿಂದ ದೈತ್ಯರಿಗೆ ಕುತೂಹಲವನ್ನುಂಟುಮಾಡಿ, ನೆಪದಿಂದ ಇಂದ್ರಶತ್ರುವಾದ ಬಲಿಯನ್ನು ಕೆಳಗೆ ತಳ್ಳಿ, ತನ್ನವರಿಗೆ ಪರಮಪದವನ್ನು ಕೊಟ್ಟನು.”',
        '0.17': '“ಮಹಾಶಕ್ತಿಶಾಲಿ ತಪಸ್ವಿಶ್ರೇಷ್ಠರ ವಂಶದಲ್ಲಿ ಜನಿಸಿ, ಕೊಡಲಿಯ ಹೊಳಪಿನಿಂದ ಗರ್ವಿತ ರಾಜರೆಂಬ ಕತ್ತಲೆಯನ್ನು ನಾಶಮಾಡಿದ, ಲೋಕಹಿತಕ್ಕಾಗಿ ಇನ್ನೊಬ್ಬ ಸೂರ್ಯನಂತಿರುವ ಪರಶುರಾಮನೆಂದು ಇವನನ್ನು ಮತ್ತೆ ಮತ್ತೆ ವರ್ಣಿಸುತ್ತಾರೆ.”',
        '0.18': '(ಇಲ್ಲಿಂದ ಕವಿಯು ಶ್ಲೇಷದಿಂದ ರಾಮ ಕೃಷ್ಣರ ಚರಿತ್ರೆಗಳನ್ನು ಒಟ್ಟಿಗೆ ಹೇಳುತ್ತಾನೆ.) “ವಸುದೇವನಿಗೆ (ದೇವತೆಗಳಿಗೆ) ಆನಂದ ಕೊಡುವ ಆ ಕರುಣಾಕರ ಭಗವಂತನು ಹಿಂದೆ ಚಂದ್ರವಂಶದಲ್ಲಿ (ಸೂರ್ಯವಂಶದಲ್ಲಿ) ಅವತರಿಸಿದನು; ದಿಕ್ಕುಗಳನ್ನು ಗೆದ್ದ, ಉಗ್ರಸಂಪತ್ತಿನ, ಶತ್ರುನಾಶಕನಾದ ದಶರಥನು ಭೂಮಿಯಲ್ಲಿ ಅವನ ತಂದೆಯಾದನು.”',
        '0.19': '“ಭುವನೇಶ್ವರನಿಗೆ ಪ್ರಿಯನಾದ ಭುಜಗೇಶ್ವರನಾದ ಶೇಷನೂ ಜನಿಸಿದನು; ಕಾಂತಿಯಿಂದ ಚಂದ್ರನನ್ನು ಗೆದ್ದ ಸುಂದರನಾದ ಅಣ್ಣನನ್ನು ‘ರಾಮ’ ಎಂದು ಕರೆಯುತ್ತಾರೆ (ಕೃಷ್ಣಕಥೆಯಲ್ಲಿ ಬಲರಾಮ; ರಾಮಕಥೆಯಲ್ಲಿ ಲಕ್ಷ್ಮಣನ ಅಣ್ಣನಾದ ರಾಮನೇ).”',
        '0.20': '“ಆಮೇಲೆ ಅಗಲಿಕೆಯನ್ನು ಸಹಿಸಲಾರದ ತಂದೆಯಿಂದ ಮತ್ತೆ ಮತ್ತೆ ನೋಡಲ್ಪಡುತ್ತಾ, ದುಷ್ಟರಿಗೆ ಹೆದರಿದ ತಪಸ್ವಿಯಿಂದ (ವಿಶ್ವಾಮಿತ್ರರಿಂದ; ಕಂಸನಿಂದ ದೂರ ವ್ರಜಕ್ಕೆ) ಆ ಪ್ರಭುವು ಕಾಡಿಗೆ ಒಯ್ಯಲ್ಪಟ್ಟನು; ಅಲ್ಲಿ ಅವನು ಆಸುರೀ ನಿಶಾಚರಿಯನ್ನು (ತಾಟಕೆಯನ್ನು; ಪೂತನಿಯನ್ನು) ಕೊಂದನು.”',
        '0.21': '“ಮುನಿಗಳ ಯಜ್ಞಗಳಿಗೆ ವೈರ ಕಟ್ಟಿದ ದುಷ್ಟರನ್ನು — ಯುದ್ಧದಲ್ಲಿ ತೋಳೆತ್ತಿದ ಸುಬಾಹುವನ್ನು (ರಾಮಕಥೆ), ಕ್ರೂರರಾದ ಕೇಶಿ ಅರಿಷ್ಟರೇ ಮೊದಲಾದವರನ್ನು (ಕೃಷ್ಣಕಥೆ) — ನಾಶಮಾಡುತ್ತಿದ್ದ ಅವನನ್ನು ದೇವತೆಗಳೇ ಮೊದಲಾದ ಸಜ್ಜನಸಮೂಹವು ಅಭಿನಂದಿಸಿತು.”',
        '0.22': '“ಅವನ ಗುಣಗಳನ್ನು ಹಾಡುವ ಪಕ್ಷಿಗಳಿಂದ (ಯಜ್ಞದಲ್ಲಿ ಸ್ವರವಾಗಿ ಹೇಳುವ ದ್ವಿಜರಿಂದ) ಬೆಳಗುವ ಕಾಡಿನಲ್ಲಿ ಸಂಚರಿಸುತ್ತಾ, ಸಕಲ ಗೋಕುಲಕ್ಕೆ ಪ್ರಿಯನಾದ ಅವನು ಕಾಮರಹಿತವಾದ ಪ್ರೇಮರಸದಿಂದ ಆರ್ದ್ರವಾದ ಮನಸ್ಸು ಮಾತುಗಳುಳ್ಳ ಸುಂದರಿಯರನ್ನು (ಗೋಪಿಯರನ್ನು) ಲಾಲಿಸುತ್ತಾ ರಮಿಸಿದನು.”',
        '0.23': '“ಸಹೋದರನೊಡನೆ, ಎಲ್ಲ ಮಿತ್ರರೊಡನೆ ಕೂಡಿ ಅವನು ಜನಕನಿಗೆ ಪ್ರಿಯವಾದ ಮಧುರ ನಗರಕ್ಕೆ (ಮಥುರೆಗೆ; ಜನಕನ ಮಿಥಿಲೆಗೆ) ಹೋದನು; ಅದನ್ನು ಪ್ರವೇಶಿಸುತ್ತಾ ಜಗದೇಕಸುಂದರನಾದ ಅವನು ಸ್ತ್ರೀಪುರುಷರ ಕಣ್ಣುಗಳಿಗೆ ಮಹೋತ್ಸವವಾದನು.”',
        '0.24': '“ಆಮೇಲೆ ಲೀಲೆಯಿಂದ ಈಶ್ವರನ ಧನುಸ್ಸನ್ನು (ಕಂಸನ ಧನುಸ್ಸನ್ನು) ಮುರಿದು, ಉಗ್ರಸೇನರಾಜನ ಮಗನ (ಕಂಸನ) ಪೌರುಷವನ್ನು ನಾಶಮಾಡಿ, ಬ್ರಾಹ್ಮಣಗುರುವನ್ನು ಸೇವಿಸಿ, ಬ್ರಹ್ಮನ ಗುರುವಾದ ಅವನು ಅಪಾರ ತೇಜಸ್ಸಿನಿಂದ ತನ್ನವರನ್ನು ಸಂತೋಷಪಡಿಸಿದನು.”',
        '0.25': '“ಭೂಮಿಗೆ ಬಂದ ಕಮಲಾಸ್ವರೂಪಳಾದ, ಕಮಲಪತ್ರನೇತ್ರೆಯಾದ ರಾಜಪುತ್ರಿಯನ್ನು (ಸೀತೆಯನ್ನು; ರುಕ್ಮಿಣಿಯನ್ನು) ಅವನು ಸ್ವೀಕರಿಸಿದನು; ತನ್ನ ಲೀಲೆಯಿಂದ ಶತ್ರುರಾಜರನ್ನು ಗೆದ್ದು, ಸಮುದ್ರದಂತೆ ದುರ್ಗಮವಾದ ನಗರವನ್ನು ಸೇರಿ ಸಂತೋಷಪಟ್ಟನು.”',
        '0.26': '“ತಾಯಿಯರ ಸಂತೋಷಕ್ಕಾಗಿ, ಸಜ್ಜನರ ಬಯಕೆಯನ್ನು ನೆರವೇರಿಸುತ್ತಾ, ಶುಭಳಾದ ಪತ್ನಿಯೊಡನೆಯೂ ಮಹಾವಿಜಯಧ್ವಜನಾದ ಶ್ರೇಷ್ಠಮಿತ್ರ ಲಕ್ಷ್ಮಣನೊಡನೆಯೂ ಅವನು ಬೇಗನೆ ಸಂತೋಷದಿಂದ ಕಾಡಿಗೆ ಹೋದನು.”',
        '0.27': '“ಪರ್ವತಗಳೇ ಮೊದಲಾದ ದುರ್ಗಮಸ್ಥಳಗಳನ್ನು ದಾಟಿ, ಖರ ದೂಷಣರೇ ಮೊದಲಾದ ಅನೇಕ ಸಜ್ಜನದ್ವೇಷಿಗಳನ್ನು ಕೊಂದು, ಲೋಕಕ್ಕೆ ಭಯಕರನೂ ಅಸಹನೀಯನೂ ಆದವನನ್ನು ಕ್ರಮವಾಗಿ ಮಹಾಂಧಕಾರದ ನರಕಕ್ಕೆ ಕಳುಹಿಸಿದನು (ನರಕಾಸುರನನ್ನು ಕೊಂದನು).”',
        '0.28': '“ಸುಂದರ ಆಶ್ರಮದ ಅಂಗಳವನ್ನು ತನ್ನ ತೇಜಸ್ಸಿನಿಂದ ಶೋಭಿಸಿದ, ಲೋಕಮಾನ್ಯಳಾದ ಪ್ರಿಯೆಯೊಡನೆ, ಮದ ಪ್ರಮಾದಗಳುಳ್ಳ ದೇವತೆಗಳನ್ನು ಕಳವಳಗೊಳಿಸಿ ಅವರ ಪಾರಿಜಾತವನ್ನು ಕೊಂಡೊಯ್ದ ಆ ಪ್ರಿಯನು ತನ್ನ ಧಾಮವನ್ನು ಸೇರಿದನು.”',
        '0.29': '“ದಿಕ್ಪಾಲಕರನ್ನೂ ರಾಜಮಂಡಲಗಳನ್ನೂ ಹತ್ತು ದಿಕ್ಕುಗಳಲ್ಲಿ ಮತ್ತೆ ಮತ್ತೆ ಗೆದ್ದ, ಇತರರಿಗೆ ಭಯಂಕರನಾದ ಅಪ್ರಿಯನು (ರಾವಣನು) ಇಲ್ಲಿ ಬೆಳಗುತ್ತಿದ್ದ ತನ್ನ ಪ್ರಿಯತಮೆಯಾದ ಶ್ರೀಯನ್ನು ಕೊಂಡೊಯ್ಯುವುದನ್ನು ಭಗವಂತನು ಉಪೇಕ್ಷಿಸಿದನು.”',
        '0.30': '“ಪವನಪುತ್ರ ಹನುಮಂತನೇ ಮೊದಲಾದವರಿಂದ ವಂದಿತನಾದ ಅವನು ಒಮ್ಮೆ ಬಾಣದಿಂದ ಇಂದ್ರಪುತ್ರನನ್ನು (ವಾಲಿಯನ್ನು) ಕೊಂದು, ಶತ್ರುರಹಿತವಾದ ರಾಜ್ಯವನ್ನು ತನ್ನ ಪ್ರಿಯಮಿತ್ರನಾದ ಸೂರ್ಯಪುತ್ರ ಸುಗ್ರೀವನಿಗೆ ಕೊಟ್ಟನು.”',
        '0.31': '“ಅಲ್ಲಿ ಪವನಪುತ್ರನ ಬಾಯಿಂದ ಬಂದ ಪ್ರಿಯೆಯ ಮಹಾವಾರ್ತೆಯಿಂದ ಸಂತೋಷಗೊಂಡ ಮಧುಸೂದನನು, ಕಪಿಗಳ ತೀಕ್ಷ್ಣಸೈನ್ಯದಿಂದ (ತೀಕ್ಷ್ಣಚಕ್ರದಿಂದ) ಶೋಭಿಸುತ್ತಾ, ಸಮುದ್ರಮಧ್ಯದಲ್ಲಿರುವ, ಪುಣ್ಯಜನರಿಂದ (ರಾಕ್ಷಸರಿಂದ; ಸಜ್ಜನರಿಂದ) ಸೇವಿತವಾದ ನಗರಕ್ಕೆ ಹೋದನು.”',
        '0.32': '“ತೀಕ್ಷ್ಣಬಾಣಗಳ ಸಮೂಹದಿಂದ (ತೀಕ್ಷ್ಣಚಕ್ರದಿಂದ) ಪರಾಕ್ರಮ ತೋರಿದ ಪ್ರಭುವು, ಭೂಭಾರವಾಗಿದ್ದ ಮಹಾಸಮೂಹವನ್ನು — ಗಜರಾಜನಂತಿರುವ ಉದ್ಧತ ಕುಂಭಕರ್ಣನನ್ನು (ಕುವಲಯಾಪೀಡ ಆನೆಯನ್ನು), ಅವನ ಸಹೋದರನನ್ನು, ಇಂದ್ರಶತ್ರುವನ್ನು — ನಾಶಮಾಡಿದನು.”',
        '0.33': '“ಆಮೇಲೆ ಅಗ್ನಿಪ್ರವೇಶ ಮಾಡಿದ ಪತ್ನಿಯೊಡನೆ, ಸಹೋದರರು ಮುಂದಾಳುಗಳಾಗಿರಲು, ಸಜ್ಜನರಿಗೆ ಇಷ್ಟವನ್ನು ಕೊಡುವ ಇವನು ಬಹುಕಾಲದ ನಂತರ ಧಾಮವನ್ನು ಸೇರಿ ತನ್ನ ಮೂಲರೂಪದೊಡನೆ ಪರಮೈಕ್ಯವನ್ನು ಪಡೆದನು.”',
        '0.34': '“ಮಹಿದಾಸನೆಂದು ಪೂಜ್ಯಪಾದನಾದ ಅವನು ಪ್ರಸಿದ್ಧನೂ ನಿರ್ಮಲಾತ್ಮನೂ ಆದ ವಿಷ್ಣುಯಶಸ್ಸೆಂಬ ಬ್ರಾಹ್ಮಣನಿಂದ (ಕಲ್ಕಿಯಾಗಿ) ಜನಿಸಿದನು; ಲೋಕದ ಪಾಪಶಾಂತಿಗಾಗಿ ಮಹಾತೇಜಸ್ಸಿನ ಖಡ್ಗವನ್ನು ಧರಿಸಿ, ಹೊಳೆಯುವ ವೇದವಾಕ್ಯಗಳ ಸ್ಥಿತಿಯನ್ನು ಕಾಪಾಡುತ್ತಾನೆ.”',
        '0.35': '“ಈ ದೇವರಾಜನು ತಪಸ್ಸಿನಿಂದ ಹೊಳೆಯುವ ನಿಷ್ಪಾಪ ಕರ್ದಮನಿಂದ ಮನುಪುತ್ರಿ ದೇವಹೂತಿಯ ಮಗನಾದನು (ಕಪಿಲನಾದನು); ಕಾಲಕ್ರಮದಲ್ಲಿ ತನ್ನ ಭಕ್ತಿಯಿಂದ ತುಂಬಿದ ಸಜ್ಜನರನ್ನು ಉಂಟುಮಾಡಿದನು.”',
        '0.36': '“ಪರಮಯೌವನಾಕೃತಿಯು ಪ್ರಕಟವಾಗಿರುವ ಶ್ರೇಷ್ಠ ಸುಂದರಿಯ (ಮೋಹಿನಿಯ) ರೂಪವನ್ನು ಧರಿಸಿದ ಅಸುರಶತ್ರುವಾದ ಇವನು ದೇವಸಮೂಹಕ್ಕೆ ಅಮೃತವನ್ನು ಕೊಟ್ಟನು.”',
        '0.37': '“ಸಜ್ಜನರಿಗೆ ಪದವಿಯನ್ನು ಕೊಡುವ, ಆತ್ಮಶುದ್ಧಿಯನ್ನು ಕೊಡುವ ಈ ಶಾಶ್ವತನು ಮುನಿಶ್ರೇಷ್ಠ ಅತ್ರಿಯ ಪತ್ನಿಯಾದ, ಶುದ್ಧಮನಸ್ಕಳಾದ ಅನಸೂಯೆಯಿಂದ ಪರಮಾದರದಿಂದ ಧರಿಸಲ್ಪಟ್ಟ ಸುಕುಮಾರ ಶಿಶುವಾದನು (ದತ್ತಾತ್ರೇಯನಾದನು).”',
        '0.38': '“ಸಜ್ಜನರಿಗೆ ಪ್ರಿಯನಾದ, ಭೂಪಾಲನಾದ ಈ ಋಷಭನು ಪರಮಹಂಸಲಕ್ಷಣಗಳುಳ್ಳ ದೇಹವನ್ನು ಧರಿಸಿ, ಪರತತ್ತ್ವವನ್ನು ಬಯಸುವ ಸನಕಾದಿಗಳಿಂದ ವಂದಿತನಾಗಿ, ಎಲ್ಲ ಬಂಧನಗಳಿಂದ ಮುಕ್ತನಾಗಿ ಸಂಚರಿಸಿದನು.”',
        '0.39': '“ಈ ಹರಿಯು ಧರ್ಮಪುತ್ರನಾಗಿ, ನರನ ಸಹೋದರನಾಗಿ, ಉದಾರಪರಾಕ್ರಮಿಯಾಗಿ ಜನಿಸಿದನು; ಸಜ್ಜನರ ಸಂತೋಷಕ್ಕಾಗಿ ‘ಕೃಷ್ಣ’ ಎಂದು ಕರೆಯಲ್ಪಡುವ ಅವನ ಸಹೋದರನೂ ಸ್ವಯಂ ಜನಿಸಿದನು.”',
        '0.40': '“ಸದಾ ಏಕರೂಪಿಯಾದ, ದಶರೂಪಿಯಾದ, ಲಕ್ಷೋಪಲಕ್ಷರೂಪಿಯಾದ, ವಿಕಾರರಹಿತನಾದ, ಸ್ಪಷ್ಟವಾಗಿ ಅನಂತರೂಪಿಯಾದ, ಎಲ್ಲ ದೇಹಗಳೂ ಆನಂದಜ್ಞಾನಮಯವಾದ ಪರಮಾತ್ಮನಿಗೆ ನಮೋ ನಮಃ.”',
        '0.41': 'ಹೀಗೆ ಚಿಂತಿಸುತ್ತಾ ತುಂಬಿದ ಹೃದಯದಿಂದ ಅವನು ಪ್ರೇಮದಿಂದ ಹರಿಗೆ ನಮಸ್ಕರಿಸಿ ಅವನಿಂದ ಆದರಿಸಲ್ಪಟ್ಟನು; ಪರಸ್ಪರ ಸನ್ಮಾನಿಸಿಕೊಂಡು ಮೊದಲೇ ಕುಳಿತಿದ್ದ ಆ ಇಬ್ಬರು ಅಜಿತರ ಬಳಿ ಅವನು ಕುಳಿತನು.',
        '0.42': 'ಅಲ್ಲಿ ವಿವಿಧ ಸಂಭಾಷಣೆಗಳನ್ನು ನಡೆಸಿದ ಮೇಲೆ, ಲೋಕಪತಿಯು (ನಾರಾಯಣನು) ಮುನಿಪುತ್ರನ (ವ್ಯಾಸರ) ಸುಂದರ ಮುಖವನ್ನು ನೋಡಿ, ನಮಿಸಿದ್ದ ಮಹಾಸುಖತೀರ್ಥರಿಗೆ ಏಕಾಂತದಲ್ಲಿ ಈ ಮಾತನ್ನು ಹೇಳಿದನು.',
        '0.43': '“ಧೈರ್ಯಶಾಲಿಯೇ, ದೇವಕಾರ್ಯವನ್ನು ಮನಸ್ಸಿನಲ್ಲಿಟ್ಟುಕೊಂಡು ಆರ್ಯಸಮ್ಮತವಾದ ನಾನು ಹೇಳುವ ಈ ಮಾತನ್ನು ಕೇಳು: ಇತರರಿಗೆ ಅತಿ ದುಷ್ಕರವಾದುದನ್ನು ಮಾಡಿ ನಿನ್ನ ಈ ತರುಣ ಅವತಾರವು ಮಹಾಫಲವುಳ್ಳದ್ದಾಗುವುದು.”',
        '0.44': '“ಸಜ್ಜನರಿಗೆ ಪ್ರಿಯವಾದ ಸೂತ್ರಗಳ ಹೃದಯವನ್ನು ಮುಚ್ಚಿ, ಈಗ ತಮ್ಮ ಇಚ್ಛೆಯಂತೆ ಭಾಷ್ಯಗಳನ್ನು ರಚಿಸಿ, ಶ್ರುತಿಸ್ಮೃತಿಗಳ ನಿಜಾರ್ಥವನ್ನು ದೂಷಿಸುವ ಇತರರಿಂದ ಆಹತವಾದ ಜ್ಞಾನವು ಸಂಪೂರ್ಣವಾಗಿ ಮರೆಯಾಗುತ್ತಿದೆ.”',
        '0.45': '“ದುಷ್ಟರು ಮಾಡಿದ ಈ ಅನ್ಯಾಯವನ್ನು ತೊಲಗಿಸಲು, ನಿನ್ನವರನ್ನು ಶುಭಗತಿಗೆ ಮರಳಿ ಕೊಂಡೊಯ್ಯಲು, ತಡಮಾಡದೆ ಸೂತ್ರಭಾಷ್ಯವನ್ನು ರಚಿಸು; ಕವಿಯೇ, ಶ್ರುತಿಸ್ಮೃತಿಗಳನ್ನು ಸನ್ಮತದೊಡನೆ ಹೊಂದಿಸು.”',
        '0.46': 'ಜಗದ್ಗುರುವಿನ ಮಿತವಾದರೂ ಅಮಿತಾರ್ಥವುಳ್ಳ ಆ ಮಾತನ್ನು ಕೇಳಿ, ತುಂಬಿದ ಹೃದಯದ, ಚರಾಚರೇಶ್ವರರಾದ ಆ ಇಬ್ಬರ ಅಗಲಿಕೆಯನ್ನು ಸಹಿಸಲಾರದ ವಾಗ್ಮಿಶ್ರೇಷ್ಠನು ಆಗ ಅವರಿಗೆ ಹೀಗೆ ಹೇಳಿದನು:',
        '0.47': '“ಭಗವನ್, ಇನ್ನು ಮುಂದೆ ನಿಮ್ಮಿಬ್ಬರ ನಿರಂತರ ಸೇವೆಯೆಂಬ ಅಮೃತದಲ್ಲಿ ಮುಳುಗಲು ನನಗೆ ಅನುಗ್ರಹವಾಗಲಿ; ಜಗತ್ತಿಗೆ ಏಕಮಂಗಳವಾದ ಇಂತಹ ಪ್ರಿಯತಮ ಸುಖವನ್ನು ಮೂರು ಲೋಕಗಳಲ್ಲೂ ನಾನು ಪಡೆಯಲಾರೆ.”',
        '0.48': '“ಕಲಿಕಾಲದಿಂದ ಗುಣಗಳು ಕಬಳಿಸಲ್ಪಟ್ಟ ಈ ಭೂಮಿಯಲ್ಲಿ ಈಗ ಯೋಗ್ಯಬುದ್ಧಿಯುಳ್ಳ ಸಜ್ಜನನು ನಿಶ್ಚಯವಾಗಿ ಇಲ್ಲ; ಅಯೋಗ್ಯನಿಗೆ ಪರತತ್ತ್ವವನ್ನು ವರ್ಣಿಸುವುದು ನಾಯಿಗೆ ಹವಿಸ್ಸನ್ನು ಕೊಡುವಂತೆ ನಿಂದ್ಯವಾದುದು.”',
        '0.49': 'ಹೀಗೆ ಹೇಳಿದ ಅವನಿಗೆ ಪ್ರಭುವು ಹೇಳಿದನು: “ಸೌಮ್ಯನೇ, ಭೂಮಿಯಲ್ಲಿ ಗುಣಯೋಗ್ಯರಾದ ಜನರಿದ್ದಾರೆ; ದಾರದಲ್ಲಿ ಪೋಣಿಸದ ನಿರ್ಮಲ ರತ್ನಗಳಂತಿರುವ ಅವರನ್ನು ದಯೆಯಿಂದ ನಿನ್ನ ಶುದ್ಧ ವಾಕ್ಕುಗಳಿಂದ (ಕಿರಣಗಳಿಂದ) ಶುದ್ಧಗೊಳಿಸು.”',
        '0.50': '“ನನ್ನ ಪರಮಾಜ್ಞೆಯಿಂದ ನಿನ್ನ ಕೀರ್ತಿಯು ಸೂರ್ಯಪ್ರಭೆಯು ಗೂಬೆಗಳಿಗೆಂತೋ ಹಾಗೆ ದುರ್ಜನರಿಗೆ ಅತಿಶಯ ಸಂಕಟವನ್ನು ತರುವುದು; ಕಮಲಸರೋವರಗಳನ್ನು ಅರಳಿಸುವಂತೆ ಸಜ್ಜನರನ್ನು ನಿರಂತರ ಎಚ್ಚರಿಸುವುದು.”',
        '0.51': 'ಹೀಗೆ ಲೋಕಸುಖಕ್ಕಾಗಿ ಧರಣೀಧರನ ಮುಖದಿಂದ (ಪರ್ವತದಿಂದ ನದಿಯಂತೆ) ಹೊರಟ ಆ ನಿರ್ಮಲ ವಾಣಿಯು, ಚಂದ್ರಕಿರಣಗಳಿಂದ ಉಕ್ಕುವ ಸಮುದ್ರದಂತೆ ಮೊದಲೇ ತುಂಬಿದ್ದ ಮಧ್ವರ ವಿಶಾಲಬುದ್ಧಿಸಾಗರವನ್ನು ಪ್ರವೇಶಿಸಿತು.',
        '0.52': 'ಆ ಇಬ್ಬರು ಮಹಾತ್ಮರ ಮಾನ್ಯವಾದ ಅಭಿಪ್ರಾಯವನ್ನು ಅರಿತು “ಹಾಗೆಯೇ ಆಗಲಿ” ಎಂದು ಹೇಳಿ, ಆ ಧೀರಬುದ್ಧಿಯು ನಮಸ್ಕರಿಸುತ್ತಾ ಬೇರೆ ಯಾರಿಂದಲೂ ಹೊರಲಾಗದ ಅವರ ಆಜ್ಞೆಯನ್ನು ತನ್ನ ತಲೆಯ ಮೇಲೆ ಧರಿಸಿದನು.',
        '0.53': 'ತತ್ತ್ವವನ್ನು ಬೋಧಿಸುವ ಮೂರು ವೇದಗಳಂತೆ, ಪ್ರಜೆಗಳ ಪಾಪವನ್ನು ನಾಶಮಾಡುವ ಮೂರು ಅಗ್ನಿಗಳಂತೆ, ಅಥವಾ ಎಲ್ಲವನ್ನೂ ಧರಿಸುವ ಮೂರು ಲೋಕಗಳಂತೆ, ಮುನಿಪುತ್ರ ವ್ಯಾಸರು, ಧರ್ಮಪುತ್ರ ನಾರಾಯಣ, ಮಧ್ವರು — ಈ ಮೂವರು ಅಲ್ಲಿ ಆನಂದದಿಂದ ಬೆಳಗಿದರು.',
        '0.54': 'ಹೀಗೆ ಕವಿಕುಲತಿಲಕರಾದ ತ್ರಿವಿಕ್ರಮಪಂಡಿತಾಚಾರ್ಯರ ಪುತ್ರ ನಾರಾಯಣಪಂಡಿತಾಚಾರ್ಯರು ರಚಿಸಿದ “ಆನಂದ” ಎಂಬ ಅಂಕಿತವುಳ್ಳ ಶ್ರೀಮತ್ಸುಮಧ್ವವಿಜಯ ಮಹಾಕಾವ್ಯದ ಎಂಟನೆಯ ಸರ್ಗ ಮುಗಿಯಿತು.',
      },
    },
  },
};
